window.__D("text/keter-shem-tov/c002",{"p":[[300010330,"רעג-ב\n\n<b>כל</b> הדיבורים שמדברים בני אדם הוא עולם הדיבור, ומחשבתו הוא עולם המחשבה. וכשהם מדברים טוב ומדבקים המחשבה בזה הדיבור, אז הם מחברים עולם הדיבור בעולם המחשבה וגורמים טוב. וכן כשמדברים רע גורמים רע ח\"ו, ויש בזה חכמה נפלאה. וזהו ותבחר לשון ערומים, שלא ירגיל עצמו שיצא מפיו דברים רעים שהם מסטרא דדינא, רק ירגיל תמיד את עצמו בדברים טובים שהם מסטרא דחסד, וכן במחשבתו, ויגרום כך.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י לט (מב)</b>\n<i>ותבחר לשון ערומים</i> – איוב טו, ה.\n----- הערות וציונים -----\n<i>וכשהם מדברים כו' וכן כשמדברים כו'</i> – להעיר מזח\"ב מז, ב ושם רסה, רע\"א. זח\"ג לא, ב ושם קה, א. ברכות יט, סע\"א אל יפתח אדם פה כו' (זח\"א קעה, א ושם קצה, ב) ושם נה, ב כל החלומות הולכין אחר הפה. זח\"א קצא, א. וראה לעיל סי' רד-ב, בהערות לסי' רל, ולקמן סי' רצט-א. רג\"כ לקמן סי' שא-ג. עיין מדבר קדמות להחיד\"א בסוף מערכת ד אות כא (דבור).\n<i>וכן במחשבתו</i> – ראה לעיל סי' רל ולקמן סי' רפג."]]],[300010331,"עדר\n\n<b>בזוהר</b> צריך לשתפא בהילוכא דידיה ובישיבה ובהקיץ דיליה לשכינתא. פירוש, שכל דבר שעושה יעשה הכל לניצוץ השכינה שבתוכו, ויעשה הכל עבור השכינה ולא לעצמו.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י מ (מג)</b>\n<i>בזוהר צריך כו'</i> – זח\"ג קי, ב.\n----- הערות וציונים -----\nראה לעיל סי' רסח והנסמן שם בהערות."]]],[300010332,"ערה\n\n<b>שמעתי</b> <i>ממורי</i> &lt;הבעש\"ט&gt; זלה\"ה מקום שהמחשבה של אדם מגעת שם הוא כולו כו' ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י שלח קכט</b>,<b> רע</b>\"<b>ג (תצ</b>,<b> ב)</b>\n----- הערות וציונים -----\nעיין לעיל סי' נו ובהערות שם."]]],[300010333,"רעו\n\n<b>&lt;שמעתי</b> ממורי הבעש\"ט בענין ר' יוסי&gt; באותה שעה למדתי ממנו ג' דברים, למדתי שאין נכנסין לחורבה, ר\"ל גם שנזדמן במעשה עוני ועינוי ועל כרחך הוא כדי שיתפלל, מ\"מ איך יתפלל, צריך לכלכל הדבר במשפט שיהיה לרצון לו יתברך ולא בהכרח שיכנס בעובי הקורה. ומה שאמר שאין נכנסין לחורבה דייקא, והוא כלל גדול בתפלה כאשר שמעתי בזה מפורש מפי <i>מורי</i> <span data-k=\"sm\">[שיחי' נצח]</span>. ולמדנו שמתפללין בדרך, &lt;והיינו דרך הרבים, ולעטף א\"ע בין תפילות הרבים&gt;<i>[ftnref_1_נו]</i> כנלמד מפ' תפלה לעני כי יעטוף, שהבין פי' פסוק זה ג\"כ ע\"י שאלת אליהו ז\"ל וכו'. ולמדתי שהמתפלל בדרך מתפלל תפלה קצרה הביננו, פי' הבנת התפלה בלא כוונה &lt;ודפח\"ח&gt; <span data-k=\"sm\">[וק\"ל]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י שלח קלד</b>,<b> סע</b>\"<b>ב (תקי</b>,<b> א)</b>\n<i>בענין ר' יוסי כו'</i> – ברכות ג, א. <i>תפלה לעני גו'</i> – תהלים קב, א.\n----- שולי הגליון -----\n[ftn_1_נו]) <i>הוספה זו ע\"פ המבואר שם בתוי\"י לפני הנ\"ל</i>,<i> והוא ע\"פ ההבדל בין אורח לדרך – שדרך מורה על דרך רבים כבזח\"ג פח</i>,<i> ע\"א המרומז לעיל סי' רלז</i>.\n----- הערות וציונים -----\nעיין שם בתוי\"י, שם כל ביאור הסוגיא דר\"י שנכנס לחורבה וביאור פסוק תפלה לעני (החל שם קלג, ד ואילך)."]]],[300010334,"רעז\n\n<b>בגמרא</b> הצדיקים דומין לאילן הנטוע &lt;במקום טהרה&gt;. פי' שכמו שזורעים דבר בארץ אז ממשיך כל הכוחות שיש בארץ לתוך הזרע ומוציא הפירות, כך הצדיק בעולם הזה ממשיך הניצוצות שמשורש נשמתו בכל דבר שבעולם, ומעלה אותן הניצוצות לבורא ית'.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י מא (מד)</b>\n<i>הצדיקים דומין כו'</i> – קידושין מ, ב.\n----- הערות וציונים -----\nראה לעיל סי' נג וקצד. צוה\"ר סי' קט ובהערות שם. מדל\"י סי' יא."]]],[300010335,"רעח\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; כשיש לו תענוג בתורה ועבודה סוד ברית, כמו שביארתי <span data-k=\"sm\">[פסוק]</span> ויעמידה ליעקב לחק לישראל ברית עולם <span data-k=\"sm\">[וכו' יעו\"ש]</span> לא יתפאר בזה. כמו ששמעתי &lt;ממורי הבעש\"ט ז\"ל&gt; <span data-k=\"sm\">[בשם </span><i>מורי</i><span data-k=\"sm\">]</span> פי' הש\"ס ריש לקיש זבין נפשיה ללודאי כו' חייתא ופלגא כו', והעולה מדבריו כי אחר שזכה להתפלל בתכלית השלמות או למד בתכלית בא יצה\"ר אח\"כ כמה נאה מעשיך וכו' וזהו חייתא ופלגא כו' ודפח\"ח &lt;פירוש שהי' מופלג גדול מדביקת הש\"י ע\"י החייתא שסבור שעובד בחיות עליון&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י נשא קכא</b>,<b> ריש ע</b>\"<b>ב (תנג</b>,<b> ב)</b>\n<i>ויעמידה ליעקב גו'</i> – תהלים קה, י. <i>ר\"ל זבין כו'</i> – גיטין מז, א.\n----- הערות וציונים -----\n<i>יעו\"ש</i> – כמה עמודים לפני דיבור זה – קכ, ב (תנ, ב).\n<i>בא יצה\"ר אח\"כ כו'</i> – ראה לעיל סי' רלה."]]],[300010336,"רעט\n\n<b>המשל</b><i>[ftnref_1_נז]</i> הוא כלי להשכל, וכן הדיבור הוא כלי למחשבה, וכשהוא מדבר בלי כוונה הוא שבירת הכלים שאין חיות בכלים. וכשהוא מפשיט עצמו מהגשמיות, שהוא הגוף והכלי שלו, אז יכול לראות הפנימיות הכלי דהיינו החיות והאורות של אותיות. כשהוא מפשיט עצמו מגשמיות ומלביש עצמו בתוך דיבורים, אז הוא דבוק בבורא ית' שהוא מלובש בתוך הדיבורים, ויראה שלא יפול ממחשבתו ויחזיק עצמו להעלות למעלה.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י מב (מה)</b>\n----- שולי הגליון -----\n[ftn_1_נז]) <i>בכ\"י של ס' מדל\"י יש נ\"א</i>: המחשבה.\n----- הערות וציונים -----\n<i>הדיבור הוא כלי למחשבה</i> – ראה צוה\"ר סי' קח ולקמן סי' שיג.\n<i>יכול לראות הפנימיות הכלי</i> – להעיר משער האמונה לאדה\"א ס\"פ כז (הובא בהוספות למדל\"י-או\"ת סי' פח).\n<i>החיות והאורות של אותיות</i> – ראה לעיל ריש סי' רז-ב."]]],[300010337,"רפ\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; איתא בתנא דבי אליהו &lt;כתיב&gt; הוכח תוכיח את עמיתך פי' חבירך בתורה ובמצות. אבל אותם בני אדם שאינם הולכים <span data-k=\"sm\">[תמיד]</span> בדרך התורה והמצות אינו מחוייב להוכיחם דכתיב אל תוכח לץ פן ישנאך הוכח לחכם ויאהבך.",[["","","----- מקורות ומראה מקומות -----\n<b>הנה</b>\"<b>י ד</b>,<b> א. לקו</b>\"<b>א להרמ</b>\"<b>מ כח</b>,<b> א</b>\n<i>איתא בתדב\"א</i> – פי\"ח. <i>הוכח תוכיח גו'</i> – קדשים יט, יז. <i>אל תוכח לץ גו'</i> – משלי ט, ח.\n----- הערות וציונים -----\nכל הסימן הוא לשון התד\"א (ומשם בילק\"ש קדשים רמז תרי\"ג) ולכאורה צ\"ע מאי קמ\"ל בהעתקת הדברים. להעיר שכן נמצא ג\"כ בס' הנהגות ישרות ובלקו\"א המיוחס להרמ\"מ, ואולי שם בא בהמשך (וכתנא דמסייע) להנזכר שם לפני זה כשיחרפוהו ב\"א על עבודתו כו' לא יענה להם אפילו בדברים טובים כו' (הובא ג\"כ בצוה\"ר סי' מט-נ), ובעל הכש\"ט העתיקו משם דהרי סי' רפא ורפב באים כאן תיכף אחרי דיבור זה כמו שם. לאידך י\"ל בדרך אפשר שהבעש\"ט אמר כן ע\"ד דאיתא באבות פ\"ד מי\"ט שמואל הקטן אומר כו' (שהם פסוקים מפורשים), ועוד כה\"ג."]]],[300010338,"רפא-א\n\n<b>וכתיב</b> שלח אורך ואמתך המה ינחוני, שיכוין שהשכינה שמלא כל הארץ כבודו &lt;מלביש&gt; <span data-k=\"sm\">[מולכת]</span> מחשבתו מתתא לעילא בכח הגדול ויבקעו הרקיעים במחשבתו כאלו הם פתוחות לפניו, ויכנס בעולם היצירה, ואח\"כ בעולם הבריאה, ואח\"כ באצילות. ויהיה יורד במחשבתו למטה, ואח\"כ יעלה למעלה. ויהיה עולה ויורד &lt;ועולה&gt; במחשבתו כמה פעמים, כי הירידה הוא צורך עליה, כי מכח הירידה שירד אח\"כ כשיעלה יעלה למקום גבוה מאד, כמו אדם שרוצה לזרוק אבן וכו'<i>[ftnref_1_נח]</i>. וכשעולה במחשבתו בעולם העשיה או ביצירה יכוין שמדבר שם באותו עולם, ודיבור יוצא מפיו באותו העולם, ויכוין שיש בזה העולם השם לנגדו בעשר ספירות שהוא א\"ס לגדולתו. וכל מה &lt;שהוא עולה&gt; <span data-k=\"sm\">[שילך]</span> למעלה יכוין שהוא עולה ומתקרב אל השם במקום גבוה, כדאיתא בזוהר אינו דומה רגלוי דמלכא לרישי' דמלכא. וגם כל היום, אפי' שלא בשעת תפלה, יעלה עצמו למעלה במחשבתו תמיד. וצריך כח גדול לזה שיוכל לדבק במחשבתו למעלה, ויחזיק עצמו בכל כוחו. ומתחלה אע\"פ שיכול לעלות מאד, לא יעלה רק בעולם עשיה <span data-k=\"sm\">[נ\"א: לא יעלה במהירות, רק בהדרגה, תחילה אל עולם העשיה]</span> לתקן שם, ואח\"כ לעולם היצירה, ואח\"כ לבריאה, ואח\"כ לאצילות.",[["","","----- מקורות ומראה מקומות -----\n<b>הנה</b>\"<b>י ד</b>,<b> א. לקו</b>\"<b>א להרמ</b>\"<b>מ כח</b>,<b> א. או</b>\"<b>ת סי</b>'<b> רכד (סט</b>,<b> ד). אוה</b>\"<b>א צ</b>,<b> ב</b>\n<i>שלח אורך גו'</i> – תהלים מג, ג. <i>שמלא כל גו'</i> – ישעי' ו, ג. <i>כדאיתא בזוהר</i> – זח\"ב פב, א.\n----- שולי הגליון -----\n[ftn_1_נח]) <i>בס' הנהגות ישרות</i>: והמשל כמו אדם שרוצה לזרוק אבן מה שמוריד ידו למטה עם האבן בזריקתו למקום גבוה מאד.\n----- הערות וציונים -----\nראה לעיל סי' קצט-א, רטז-א, רטז-ב ורנט; ולקמן סי' שפז-ב."]]],[300010339,"רפא-ב\n\n<b>כשאדם</b> רוצה להבין איזה דבר ומרבה עצה להבין הדבר, אז הוא מעלה אותו לעולם המחשבה וממשיך לעצמו מהחכמה עליונה.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י מג (מו)</b>\n----- הערות וציונים -----\nראה לעיל סי' קב-ב."]]],[300010340,"רפב-א\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; בכל דרכיך [דעהו]. זהו כלל גדול, דעהו הוא לשון חבור ה' בוא\"ו <span data-k=\"sm\">[בכל מעשיו]</span> &lt;דעהו לחברם יחד בכל מעשיך&gt;, אפי' בדברים גשמיים שעושה.",[["","","----- מקורות ומראה מקומות -----\n<b>צוה</b>\"<b>ר סי</b>'<b> צד. לקו</b>\"<b>א להרמ</b>\"<b>מ כח</b>,<b> ריש ע</b>\"<b>ב. אוה</b>\"<b>א צט</b>,<b> ב</b>\n<i>בכל דרכיך דעהו</i> – משלי ג, ו.\n----- הערות וציונים -----\n<i>בכל גו' זהו כלל גדול</i> – להעיר מברכות סג, א.\n<i>דעהו לשון חיבור</i> – ראה מדל\"י סי' רלז (רנ). צוה\"ר סי' צט. להעיר מתקו\"ז תס\"ט צט, א.\n<i>חיבור ה' בוא\"ו</i> – כן איתא בס' תוצאות חיים לבעל ר\"ח אות נ. ובהערה הסמוכה.\n<i>חיבור ה' בוא\"ו דכל מעשיו</i> – ראה צ\"פ פ' תרומה קה, סע\"ג (שעא, א): בכל דרכי\"ך הגשמי במעשה דעה\"ו לייחד ולחבר ה' שהוא המעשה עם ו' שהוא עולה עד המחשבה הנקרא אין סוף ונעשה מן אנ\"י אי\"ן כמו שקבלתי ממורי זלה\"ה (ראה לעיל סי' קפט-ב ובהערות שם). ועוד שם בצ\"פ פ' ויקהל קיח, סע\"ג (תיז, ב): ששמעתי ממורי זלה\"ה ביאור פסוק כל אשר תמצא ידך לעשות בכחך עשה, וחנוך מט\"ט היה מייחד בכל תפירה קוב\"ה ושכינתיה וכו' יעו\"ש (ראה לעיל סי' מב-א וצא), ובזה מקשר מעשה הגשמי של עולם התחתון ע\"י המחשבה שהיא בכחך אל רוחני עולם העליון, ובזה מקיים בכל דרכי\"ך הגשמי דעה\"ו דע לייחד ה' עם ו' קוב\"ה ושכינתיה.\n<i>אפילו בדברים הגשמיים</i> – ראה רמב\"ם הל' דעות פ\"ג. טושו\"ע או\"ח סי' רלא. ורג\"כ לעיל סי' רכ-א."]]],[300010341,"רפב-ב\n\n<b>ועוד</b> כלל אחר גדול &lt;אמרו&gt;, שתהיה העבודה צורך גבוה &lt;מאוד&gt; <span data-k=\"sm\">[לבד]</span> ולא לכוונת עצמו, ואפילו מעט מן המעט לא תהיה לכוונת עצמו רק כולו לה'.",[["","","----- מקורות ומראה מקומות -----\n<b>צוה</b>\"<b>ר סי</b>'<b> צה. לקו</b>\"<b>א להרמ</b>\"<b>מ כח</b>,<b> ב. אוה</b>\"<b>א צט</b>,<b> ב</b>\n----- הערות וציונים -----\nראה לעיל סי' רפב-א. ראה ס' עבודת הקודש לרמא\"ג ח\"ב, ושל\"ה פ' עשרה מאמרות מאמר ג-ד."]]],[300010342,"רפג\n\n<b>כשהוא</b> מחשב בדברים רעים שהם מסטרא דדינא, אז מצמצם מחשבתו באותן הדברים רעים ומרחיק עצמו מהתפשטות החסד עליון של א\"ס &lt;ב\"ה&gt; ושורין עליו דינים. וכן כשמחשב בדברים גשמיים הוא מצמצם לשם מחשבתו, שבכל מקום שהוא <span data-k=\"sm\">[מחשב הוא]</span> ממשיך עצמו לשם, שהמחשבה היא קומה שלימה.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י מה (מח)</b>\n----- הערות וציונים -----\nראה לעיל סי' רל ורעג.\n<i>שבכל מקום שהוא מחשב כו'</i> – ראה לעיל סי' נו וערה, ובהערות שם.\n<i>שהמחשבה הוא קומה שלמה</i> – ראה לעיל סי' לט ובהערות שם."]]],[300010343,"רפד-א\n\n<b>יש</b> יראה שירא מהדבורים שיוצאים מפיו, הוא עולם הדיבור. המחשבה הוא כמו ספר, שאומר מה שראה בספר, כן אומר מה שרוצה במחשבתו <span data-k=\"sm\">[וכמדומה לי שזהו ששמעתי הפירוש אסתכל קוב\"ה באורייתא וברא עלמא, שהתורה מחכמה נפיק, ר\"ל מה שראה שמחשבתו כביכול רוצה שיברא זו הדבר ברא]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י מה (מט</b>-<b>נ)</b>\n<i>אסתכל קוב\"ה כו'</i> – זח\"ב קסא, א. <i>שהתורה מחכמה נפיק</i> – זח\"ב פה, א. שם קכא, א.\n----- הערות וציונים -----\n<i>יש יראה כו' עולם הדיבור</i> – ראה לקמן סי' שיג ותיא. וראה ג\"כ לקמן סי' ת-א, ומדל\"י סוף סי' רכח (רמב)."]]],[300010344,"רפד-ב\n\n<b>ישים</b> כל מחשבתו בכח התיבות שהוא מדבר עד שיראה האורות של התיבות האיך מתנוצצים זה בזה ומתוכם נולדים כמה אורות. וזהו אור זרוע לצדיק ולישרי לב שמחה. &lt;האותיות שבתורה הם חדרים של הש\"י שהוא ממשיך בהן אצילות אורו, כמ\"ש בזהר קודשא ב\"ה ואורייתא כולה חד, ולתוכן צריך אדם לתת כל הכוונה שהיא הנשמה, כי הכוונה היא הנשמה, וזהו הדביקות קב\"ה ואורייתא וישראל כולא חד. וזהו התפשטות הגשמיות, פירוש שיפשיט נשמתו מגופו ותהיה נשמתו מלובשת באותן המחשבות שהוא מדבר ויראה כמה עולמות העליונים&gt;<i>[ftnref_1_נט]</i>.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י מז (נב)</b>\n<i>אור זרוע גו'</i> – תהלים צז, יא. <i>קוב\"ה ואורייתא כולא חד</i> – זח\"א כד, א. זח\"ב ס, א. שם צ, ב. <i>הכונה היא הנשמה</i> – ע\"ח ש\"מ דרוש ב. לקו\"ת להאריז\"ל פ' עקב. <i>קוב\"ה ואורייתא וישראל כולא חד</i> – ר' זח\"ג עג, א.\n----- שולי הגליון -----\n[ftn_1_נט]) <i>במקורו</i>: בסתם האורות של האותיות הם חדרים של הש\"י שהוא ממשיך את אצילות, ולתוכן צריך להפשיט נשמתו מגופו ותהי' נשמתו מלובשת באותן המחשבות שהוא מדבר ויראה כמה עולמות העליונים <i>(וההמשך דשם הובא לקמן סי' רפז)</i>.\n----- הערות וציונים -----\nעיין צוה\"ר סי' עה, ולקמן סי' שפז-ב.\n<i>וזהו הדבקות</i> – ראה לעיל סי' מד וקצב.\n<i>וזהו התפשטות הגשמיות</i> – ראה לעיל סוף סי' קצט-א ובהערות שם."]]],[300010345,"רפה-א\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה כל שרוח הבריות נוחה הימנו. פירוש&gt; <span data-k=\"sm\">[לשון נוחה הימנו צריך הבנה. ובשם </span><i>מורי</i><span data-k=\"sm\"> זלה\"ה שמעתי]</span> כי המקום משרה רוחו על הדור בשבילו, שהוא מרכבה לקדושה עליונה, וממנו נמשך רוח המקום לבני דורו שנוחה ושורה עליו, וז\"ש רוח המקום נוחה הימנו <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י ויחי פד</b>,<b> ב (שצח</b>,<b> ב)</b>\n<i>כל שרוח הבריות כו'</i> – אבות פ\"ג מ\"י.\n----- הערות וציונים -----\nראה לעיל סי' קכה ובהערות שם."]]],[300010346,"רפה-ב\n\n<b>ולפעמים</b> כאשר מקשר מחשבות חבירו למעלה יכול &lt;להשיג מחשבת&gt; <span data-k=\"sm\">[לשנות מחשבות]</span> חבירו באופן שהוא רוצה, &lt;כמו ראיה, כשאדם רואה שחבירו מביט ומשים כל ראייתו לצד אחד גם הוא מתחיל להביט ולהסתכל שם, וכן דיבור וכו'&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י מט (נה)</b>\n----- הערות וציונים -----"]]],[300010347,"רפו\n\n<b>&lt;מהבעש\"ט&gt;</b> תורי זהב נעשה לך &lt;פירוש&gt; <span data-k=\"sm\">[תורי זהב]</span> דחילו, עם נקודת הכסף <span data-k=\"sm\">[רחימו]</span> &lt;פירוש&gt; שלא ידבר התורה והתפלה בפניה חצונית, שמזה נברא הקליפות ומתלבש ברשעים לנקום ממנו, כמו ששמעתי כעין זה <i>ממורי</i> &lt;הבעש\"ט&gt;. וז\"ש שלא יהרגוהו רשעים שבדור והבן.\n<b>וצריך</b> דחילו יותר מרחימו שנקרא נקודת הכסף, <span data-k=\"sm\">[כמו ששמעתי </span><i>ממורי</i><span data-k=\"sm\"> זולת בשבת וכו'. דיש לפרש]</span> &lt;גם פירש&gt; תורי זהב וגו' על פי משל <span data-k=\"sm\">[ששמעתי]</span> &lt;למה הדבר דומה ל&gt;אחד שלמד מלאכת נפחין ולא ראה איך משימין תחלה ניצוץ אש להבעיר, והלך לבית המלך ונטרד משם, וחזר לרבו ראשון ללמדו העיקר <span data-k=\"sm\">[וכו']</span>. וז\"ש תורי זהב <span data-k=\"sm\">[נעשה לך]</span> היא תורה ועבודת ה', אמנם העיקר <span data-k=\"sm\">[היא]</span> נקודת הכסף, ניצוץ אש להבעיר התלהבות &lt;וכוסף וחישוק לעבודת הש\"י ודפח\"ח&gt; <span data-k=\"sm\">[חשק וכוסף לאהבת ה' וק\"ל]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>בפ</b>\"<b>י נח כא</b>,<b> ב (קז</b>,<b> א)</b>\n<i>תורי זהב גו'</i> – שה\"ש א, יא. <i>זהב דחילו </i>. .<i> הכסף רחימו</i> – זח\"ב קמח, א. <i>שלא יהרגוהו כו'</i> – רש\"י נח ו, יח.\n----- הערות וציונים -----\n<i>כמו ששמעתי כעין זה ממורי</i> – ראה צ\"פ פ' שמות ח, א (מא, א): ונ\"ל דשמעתי ממורי כי ע\"י פניה חיצונית שהיא קומה שלימה מזה נברא אדם א' המצערו וכו' וזהו שכתב האלשיך ותמוגגנו בעונינו וכו' (פירושו לישעיה סד, ו וכן בפירושו לאמור כב, לא) יעו\"ש.\n<i>זולת בשבת וכו'</i> – ראה לעיל סי' קל."]]],[300010348,"רפז<i>[ftnref_1_ס]</i>\n\n<b>יש</b> באדם כמה כוחות, שלזה העולם צריך כח זה ולזה העולם כח זה, שעולה נשמתו לכל העולמות שצריך לעלות, ובודקין אותו בכל עולם אם הוא ראוי לעלות, ואם לאו דוחין אותו לחוץ. ולפעמים שולחין לו מחשבה זרה מחמת שדוחין אותו, ואם הוא חכם באותה המחשבה יכול לקשר עצמו יותר בהש\"י. שהמחשבה הוא אותיות שהם איברי השכינה, רק שנפלו מכח השבירה ונעשה הצירוף של האותיות רע בקליפות <span data-k=\"sm\">[כמו אדם שנותן מעדנים מעורבין מין בשאינו מינו, שכל אחד בפני עצמו הוא טוב, וכאשר נתערבו הוא מאוס ורע מאד, כך זה הוא ג\"כ נעשה רע]</span>. וכשהוא מבין באיזה ענין המחשבה, אם בתאוה הוא מעולם האהבה נפל, אם ביראה רעה הוא מעולם היראה, אם בגאוה הוא מעולם התפארת, וכן בשארי הדברים שכולם מז' ימי הבנין נפלו. וכשהוא מקשר אותם בהש\"י באהבת הבורא וביראת הבורא הוא מחזיר אותם לשרשם, וכן בשאר מדות. כל מחשבה לפי המדה שנפלה הימנה הוא מקשר אותה לאותה המדה, והקליפות נופלים ונעשה הצירוף טוב. וזהו מתיר את החבלים והשקים נופלים, השקים דהיינו הקליפות נופלים, ויש להש\"י ב\"ה בזה &lt;תענוג גדול, מלה\"ד&gt; <span data-k=\"sm\">[הנאה גדולה, כמשל]</span> לבן מלך שנפל לשביה כשמביאין אותו לפני המלך הוא נהנה &lt;ומתענג&gt; מאוד, יותר מזה הבן שיש אצלו תמיד.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י מז (נג)</b>\n<i>ובודקין אותו כו'</i> – ר' זח\"ב רמה, ב. <i>מתיר את החבלים כו'</i> – שבת קנג, א.\n----- שולי הגליון -----\n[ftn_1_ס]) <i>סי' רפז הוא המשך מסי' רפד</i><i>ב</i>,<i> עיי\"ש בשוה\"ג</i>.\n----- הערות וציונים -----\nראה לעיל סי' רכז ובהערות שם, ולקמן סי' שפז."]]],[300010349,"רפח\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; וכאשר יענו אותו כן ירבה וכן יפרוץ, כמ\"ש ופרעה הקריב, וכמו ששמעתי <i>ממורי</i> <span data-k=\"sm\">[שיחי' נצח]</span> &lt;ע\"פ&gt; אמר אויב ארדוף שיש ה' אלפין, כי אלופו של עולם נסתר <span data-k=\"sm\">[בו]</span> כדי שיתקרב יותר לעבודתו ית', לכך כן ירבה וכן יפרוץ &lt;כו'&gt; <span data-k=\"sm\">[וק\"ל]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י שמות לו</b>,<b> סע</b>\"<b>ג (קלה</b>,<b> ב)</b>\n<i>וכאשר יענו גו'</i> – שמות א, יב. <i>ופרעה הקריב</i> – בשלח יד, י. <i>אמר אויב גו'</i> – בשלח טו, ט.\n----- הערות וציונים -----\n<i>כמ\"ש ופרעה הקריב</i> – ראה לעיל סי' כ ובהערות שם.\n<i>ע\"פ אמר אויב כו'</i> – ראה לעיל סי' פה ובהערות שם."]]],[300010350,"רפט\n\n<b>כל</b> מי שירצה לקשר את עצמו בבורא ית' יקשור את עצמו &lt;על ידי התורה&gt; למדת החכמה, וזהו ומלט את העיר בחכמתו.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י סוף סי</b>'<b> יו</b>\"<b>ד</b>\n<i>ומלט את גו'</i> – קהלת ט, טו.\n----- הערות וציונים -----\n<i>לקשר כו' למדת החכמה</i> – עיין מדל\"י סי' ז (ח) – ונשנה שם עם שנויים בסי' רג (ריג), ושם סי' צא (ק), קי (קכב), קסו (קעג) וקעו (קפא) שהתחברות לא יכול להיות כ\"א ע\"י חכמה עיי\"ש."]]],[300010351,"רצ\n\n<b>אל</b> תעש תפלתך קבע, ר\"ל אל יתפלל אדם על עסקי צרכיו &lt;לבד&gt;, רק יתפלל תמיד בשביל השכינה שתגאל מהגלות. וז\"ש אלא רחמים ותחנונים, ר\"ל שיתפלל תמיד לפני המקום, כלומר עבור השכינה הנקרא מקום כנודע. <span data-k=\"sm\">[וכן הזהר קורא אותן המתפללין בשביל עצמן ולא בשביל השכינה (וקוראן) כלבים עזי נפש הצועקים הב הב]</span>.\n<b>וזה</b> פירוש <span data-k=\"sm\">[הפסוק]</span> אחת שאלתי מאת ה' אותה אבקש, ר\"ל בשביל השכינה אני אבקש ומתפלל לפניך לתקן הפגם מה שנעשה ע\"י עונות.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י יב (יג)</b>\n<i>אל תעש כו' אלא רחמים כו'</i> – אבות פ\"ב מי\"ג. <i>השכינה הנקרא מקום</i> – זח\"א כה, א. <i>וכן הזוהר קורא כו'</i> – תקו\"ז ת\"ו כב, א. <i>כלבים עני נפש</i> – ישעי' נו, יא. <i>אחת שאלתי גו'</i> – תהלים כז, ד.\n----- הערות וציונים -----\nראה לעיל סי' כ והנסמן שם בהערות, וסי' פ ובהערות שם (בפרט ד\"ה לתועלת השכינה)."]]],[300010352,"(רצא)\n\n<b>ואפילו</b> אם עושין מצוה שלא לשם שמים, דהיינו שעושה עם איזה פניה, נמצא שעושה בזה ר\"ל פירוד ח\"ו. מפני כי אורייתא וקב\"ה כולא חד, נמצא אם עושה מצוה כתיקונה נעשה מצוה זו וקב\"ה חד, כי הכל קדושה אחת מרוחניות אחד. אבל אם עושה שלא כתיקונה נמצא שנעשה קליפה סביב למצוה זו שלא תוכל להתאחד עם הקדושה של הקב\"ה, ונעשה פירוד בין הקדושה של המצוה זו ובין קדושה של הקב\"ה, וזאת נקרא קליפה, שנעשית קליפה סביב מצוה זו כדי שלא תוכל להתאחד עם קדושתו ית' &lt;והמשכיל יבין&gt; <span data-k=\"sm\">[וד\"ל]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י יב (יד)</b>\n<i>אורייתא וקוב\"ה כולא חד</i> – זח\"א כד, א. זח\"ב ס, א. שם צ, ב.\n----- הערות וציונים -----\n<i>שלא תוכל להתאחד כו'</i> – להעיר מתקו\"ז ת\"ו כה, ב אורייתא בלא דו\"ר לא פרחת לעילא . . ותורה ומצוה בלא דו\"ר לא יכילת לסלקא ולמיקם קדם י\"ה. וראה לעיל סי' יז ד\"ה אמנם."]]],[300010353,"רצב-א\n\n<b>איזהו</b> שוטה המאבד מה שנותנין לו. &lt;פי' אדם גי' מ\"ה והוא שם הוי\"ה במלוי אלפין שנותנין לו מעולמות העליונים, ואין אדם עובר עבירה אא\"כ יש בו רוח שטות&gt;<i>[ftnref_1_סא]</i>.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י כב (כו)</b>\n<i>איזהו שוטה כו'</i> – חגיגה ד, א. <i>אדם גי' מ\"ה</i> – תקו\"ז ז, ב. <i>ואין אדם עובר כו'</i> – סוטה ג, א. <i>כשחיה דורסת כו'</i> – זח\"א עא, א. שבת קנא, ב.\n----- שולי הגליון -----\n[ftn_1_סא]) <i>במקורו</i>: פי' כי עיקר האדם הוא הצלם דמות אדם שבו, וכדאיתא בזוהר כשחיה דורסת את האדם בודאי נדמה לה כבהמה, והלך ממנו דמות אדם מחמת העבירות שעשה. ואדם בגימטריא מ\"ה, וזהו פירוש איזהו שוטה המאבד מ\"ה, ר\"ל צלם אדם גי' מ\"ה, שנותנים לו מעולמות עליונים (ונקרא שוטה אם איבד זה מחמת שטות, כי אין אדם עושה עבירה אלא א\"כ נכנס בו רוח שטות).\n----- הערות וציונים -----\nראה לקמן סי' רצב-ב.\n<i>צלם אדם גי' מ\"ה</i> – ראה זח\"א כד, א ושם כה, ב. זח\"ג עדר, ב. תקו\"ז תס\"ט קו, סע\"ב. זו\"ח רות עח, ג."]]],[300010354,"רצב-ב\n\n<b>&lt;כי&gt;</b><i>[ftnref_1_סב]</i> כשמתדבק בהקב\"ה שהוא אלופו של עולם נעשה אדם. והקב\"ה עשה כמה צמצומים דרך כמה עולמות כדי שיהיה אחדות עם אדם, שלא היה יכול לסבול בהירותו, ואדם צריך לפרוש א\"ע מכל גשמיות כ\"כ עד שיעלה דרך כל העולמות ויהא אחדות עם הקב\"ה, עד שיבוטל ממציאות ואז יקרא אדם.\n<b>כמשל</b><i>[ftnref_2_סג]</i> אחד שיושב לפני המלך שיש לו בושה גדולה ממנו עד שאין מחשב אם המלך אוהב אותו כדי שיאהבנו, אלא מחשב גדולתו כדי שיבוש ממנו. &lt;וזהו בראשית ירא בושת&gt;.",[["","","----- מקורות ומראה מקומות -----\n<i>כשמתדבק </i>. .<i> אדם</i>: <b>מדל</b>\"<b>י כט (לג)</b>; <i>כמשל </i>. .<i> ממנו</i>: <b>מדל</b>\"<b>י כו (ל)</b>\n<i>עשה לך שתי גו'</i> – בהעלתך י, ב. <i>ועל דמות הכסא גו'</i> – יחזקאל א, כו. <i>בהקב\"ה שהוא אלופו של עולם</i> – חגיגה טז, א. זח\"ג לא, א. <i>איתא בזוהר</i> – זח\"ב רמא, א. <i>משכן כו' לא שלטה כו'</i> – אליהו רבה פי\"ח (ד\"ה ד\"א קומי רוני). <i>דור דיעה</i> – ויק\"ר ט, א. <i>כסא של רגל א'</i> – ע\"פ ברכות לב, א. <i>בראשית יר\"א בש\"ת</i> – זח\"ג רנז, רע\"א. תקו\"ז ה, ב.\n----- שולי הגליון -----\n[ftn_1_סב]) <i>במקורו</i>: עשה לך שתי חצוצרות כסף, פי' שתי צורות, על דרך ועל דמות הכסא דמות כמראה אדם עליו מלמעלה. כי האדם הוא רק דל\"ת מ\"ם והדיבור שורה בו, [באו\"ת: ד' מ' דיבו\"ר מלכו\"ת שורה בו], וכשמתדבק בהקב\"ה <i>(כבפנים)</i>.\n[ftn_2_סג]) כמשל . . . ממנו: <i>המשל לקוח ממדל\"י סי' כו (ל)</i>,<i> ולפי הנראה צרפו לכאן כביאור לביטול הנ\"ל</i>.<i> במקורו</i>: איתא בזוהר משכן איהו בלא רברבנוהי, פי' דמשכן שעשה משה לא שלטה בו יד אויב שהחזיק את המשכיל, וזהו למעלה מהמדות כי משם באים אל כל המדות, והם היו דור דיעה כי עבודתו היתה כסא של רגל אחד שעבד אותו ית' בכל עצמיות, כמשל (<i>כבפנים</i>).\n----- הערות וציונים -----\nעיי\"ש במקורו במדל\"י המשך הדברים, ובפרט הסיפא (בנו\"א באו\"ת סי' קלד), ובהוספות למדל\"י-או\"ת סי' סו. ורג\"כ במדל\"י סי' רטז (רכז): עיקר האדם הוא ע\"ש דמו שבו, ולמה נקרא אדם ולא דם אלא שמדבק א\"ע בבורא ית' וממשיך בקרבו אלופו של עולם נתחבר האל\"ף אליו ונק' אדם, וזהו לא תאכלו על הדם (קדשים יט, כו) ר\"ל כשעדיין לא חיבר אלופו של עולם, רק אחר התפלה כשחיבר דמו לאלופו של עולם ואז נק' אדם מותר לו לאכול ולא קודם כנ\"ל.\nולהעיר שעד\"ז הובא בשם הרה\"מ בבפ\"י, דרוש לשה\"ג שנת תקכ\"ה קי, סע\"ג: שמעתי בשם החסיד מ' דוב בער טורצינר ביאור פסוק הגיד לך אדם מה טוב וגו' (מיכה ו, ח), כי ח\"ו נרגן מפריד אלוף (משלי טז, כח) ע\"י שנסתלק א' דאהי' ונשאר מ\"ד, ולהמשיך אלוף הוא טוב כשיהיה בחי' מ\"ה גי' אדם, כמשה ונחנו מה (בשלח טז, ז-ח) וכו', ובזה יובן הגיד, דהיינו להמשיך לו בחי' אדם, לזה טוב שיהיה בבחי' מה שפל ועניו, ואז נמשך א' ונעשה מ\"ה גי' אדם ודפח\"ח.\n<i>דור דיעה</i> – ראה לקמן סי' שע.\n<i>כמשל כו'</i> – השוה המשל דלקמן סי' שיד."]]],[300010355,"רצג\n\n<b>כל</b> העוסק בתורת עולה כאלו הקריב עולה, מפני שכאשר הוא מדבר באותן הדיבורים ביראה ובאהבה אז הוא נותן חיות חדש באלו הדיבורים. <span data-k=\"sm\">[ואע\"פ שנתקלקלו מחמת חטאים, אעפ\"כ הם לבושים דמלכא]</span>. אבל כשהיה בית המקדש קיים והיה מקריב קרבן עולה היה נותן כח אף בעולם המעשה.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י לב (סוף סי</b>'<b> לה)</b>\n<i>כל העוסק כו'</i> – מנחות קי, א.\n----- הערות וציונים -----\nלהעיר מלעיל סי' רעט. צוה\"ר סי' קג ומש\"כ שם בהערות. וראה לקמן סי' רצד."]]],[300010356,"רצד\n\n<b>כשם</b> כשנבראו העולמות נבראו בשם הוי\"ה אלהים, כך כאשר מזכיר האדם דברי קדושה צריך להיות בדחילו ורחימו שהם הוי\"ה אלקים.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י לג (לו)</b>\n<i>נבראו בשם הוי' אלקים</i> – בראשית ב, ד. <i>שהם הוי' אלקים</i> – זח\"ג סה, א.\n----- הערות וציונים -----\nראה לעיל סי' רצג.\n<i>כאשר מזכיר כו'</i> – ראה זח\"א כד, א. תקו\"ז ת\"י כה, ב."]]],[300010357,"רצה<i>[ftnref_1_סד]</i>\n\n<b>תמיד</b> יראה &lt;אדם&gt; במחשבתו איזה מדה נולד בו, אם מאהבה &lt;אם&gt; <span data-k=\"sm\">[או]</span> מיראה או מתפארת, ויעלה אותה המחשבה למעלה.\n<b>אף</b> על פי שהוא מעניני עולם הזה בתאות גופניות הוא יכול להעלות אותה. וידע שאותה המחשבה צריך להתתקן בזו השעה, אם באהבה אם ביראה אם בהתפארות, שנתקלקלה מחמת השבירה, ועכשיו הוא עת להעלות אותה. ולכך ירדה המחשבה מעולמות עליונים ובאה לאדם כדי להעלותה מהשבירה, היינו שידבק עצמו בבורא ית' לפי אותה המדה הנ\"ל, אם באהבה או ביראה או בתפארת ובשאר מדות של ז' ימי הבנין.\n<b>וכן</b> באכילה ושתיה, כשנולד בו אהבה אז לוקח התענוג שהיה מאכילה ושתיה זו ומעלה אותו התענוג לבורא ית'.\n<b>וזה</b> המשל <span data-k=\"sm\">[הראשון]</span> שייך &lt;ג\"כ&gt; בענין שאמרו רז\"ל שמצוה בשבת אכילה ושתיה. &lt;פירוש כי כמו שבכל צרתם לו צר, כן כשישראל שרויים בתענוג יש לו ית' תענוג&gt;. ו&lt;גם&gt; לכאורה קשה מה הנאה יש לנשמה יתירה ב&lt;תענוג&gt; אכילה ושתיה, ולפי המשל הזה אתי שפיר, שהנשמה יתירה יש לה ג\"כ תענוג זה כמ\"ש בזהר ע\"פ באתי לגני כו' &lt;אכלתי יערי עם דבשי&gt; <span data-k=\"sm\">[בשביל רעותא דילה אכיל ושתי]</span>.\n<b>וכן</b> כשנולד בו התפארות יעלה אותו התפארות שיש באותו דבר, שמכח זה נולד אותו התפארות, וידבק אותו להבורא יתברך. שבכל דבר נמצא התפשטות הבורא יתברך שמלא כל הארץ כבודו, ויעלה אותו הפנימית שיש באותו דבר, כ\"א לפי מדתו מז' ימי הבנין, וידבק הפנימית של אותו הדבר בבורא יתברך.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י לו</b>-<b>לז (לט</b>-<b>מ)</b>\n<i>צדיק מושל גו'</i> – ש\"ב כג, ג. <i>צדיקים הופכין כו'</i> – בר\"ר לג, ג. <i>שמצוה בשבת אכילה ושתיה</i> – פסחים סח, ב. <i>בכל צרתם גו'</i> – ישעי' סג, ט. <i>כמ\"ש בזוהר</i> – זח\"ג רמא, סע\"ב. שם רמד, א. <i>באתי לגני גו'</i> – שה\"ש ה, א. <i>שמלא כל גו'</i> – ישעי' ו, ג.\n----- שולי הגליון -----\n[ftn_1_סד]) <i>בסי' רצה הרכיב ב' מאמרים מס' מדל\"י – סי' לו (לט; וכן באו\"ת סי' שיט) וסי' לז (מ)</i>,<i> בהשמטת התחלות המאמרים ושנוי סדר הדברים</i>.<i> וזהו נוסח המקורי</i>:\n<b>לו</b>\nצדיק מושל ביראת אלקים, צדיקים הופכין מדת הדין למדת הרחמים. למשל כשתינוק רוצה איזה דבר שהתינוק נהנה ממנו, אביו מחמת אהבתו לתינוק יש לו הנאה כשיהיה אותו הדבר להתינוק, שנמצא התינוק מוליד אהבת אותו דבר באביו. וכן למשל כשיש כאב לאדם ברגלו גורם הרגל רצון במחשבתו שיצוה ליד להסיר הכאב, כיון שהם אחדות אחד. וכן הצדיק כשהוא דבוק בבורא ית' כל מה שחסר לו גורם למעלה כביכול רצון בבורא ית'. וזה המשל הראשון שייך <i>(כבפנים ד\"ה וזה המשל </i>. . .<i> ושתי)</i>.\n<i>אח\"כ בא סי' לז</i>:\n<b>לז</b>\nכשיש למלך בן במקום מטונף הוא הולך לאותו מקום מחמת אהבת הבן כדי ליקח אותו משם. כך לפעמים נולד מחשבה באדם מחמת שהעולמות יורדים מלמעלה, ובאין לאדם ג\"כ אותה המחשבה. וכשהוא חכם לידע באיזה ענין הוא המחשבה, אם באהבה אם ביראה אם בתפארת אעפ\"י שהוא <i>(כבפנים ד\"ה אף על פי</i> . . . <i>ז' ימי הבנין</i>. <i>ואח\"כ</i>:<i>)</i> ובשאר מדות של ז' ימי הבנין ותמיד יראה במחשבתו איזה מדה נולד בו אם מאהבה או מיראה או מת\"ת ויעלה אותה המחשבה למעלה. וכן באכילה ושתיה כשנולד בו אהבה אז לוקח התענוג שהי' מאכילה ושתיה זו ומעלה אותו התענוג לבורא ית'. <i>ואח\"כ ד\"ה </i>וכן כשנולד<i> (עד גמירא)</i>.\n----- הערות וציונים -----\n(ההערות ע\"פ הסדר שבשוה\"ג)\n<i>וכן הצדיק כו' גורם למעלה כ\"י כו'</i> – להעיר ממדל\"י סי' כט (לג) ושם סי' רלט (רנב).\n<i>שמצוה בשבת כו'</i> – ראה לעיל סי' קז ובהערות שם.\n<i>לז </i>(תוכן כל סי' לז כפי שצויין שם בשוה\"ג) – ראה לעיל סי' לט והנסמן שם בהערות."]]],[300010358,"רצו\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> כי צדיקייא אינון שלוחי דמטרוניתא, ומה שחסר להם ידעון שחסרון זה הוא בשכינה, ויתפללו שימולא החסרון שם ולא שיכוין להנאת עצמו, והוא כלל גדול שהוא חסיד המתחסד עם קונו ולא עם עצמו. &lt;והסוד אשה מזרעת תחלה יולדת זכר.&gt;<i>[ftnref_1_סה]</i>",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י וארא לח</b>,<b> ג (קמב</b>,<b> ב)</b>\n<i>צדיקייא אינון כו'</i> – זח\"א רמב, א. <i>חסיד המתחסד כו'</i> – זח\"ב קיד, ב. <i>אשה מזרעת כו'</i> – ברכות ס, א. <i>מצפון שהיא דחילו</i> – תקו\"ז ת\"ע קל, א. <i>לדרום שהוא רחימו</i> – זח\"א קנג, רע\"א.\n----- שולי הגליון -----\n[ftn_1_סה]) והסוד אשה מזרעת תחלה יולדת זכר <i>הובא במקורו (לח</i>,<i> ריש ע\"ד) בענין אחר – בסוף ביאור הברייתא דאבא בנימין ועל מטתי שתהא נתונה בין צפון לדרום (ברכות ה</i>,<i> ב) ושם</i>: וזהו צחות לשונו בין צפון לדרום שיתחיל מצפון שהיא דחילו ואח\"כ לדרום שהוא רחימו והסוד אשה מזרעת תחילה דחילו של האשה מצד צפון הוין ליה בנים זכרים, וכמו ששמעתי בשם מורי מה שנאמר לו משמים טעם איחור ביאת משיח שאין מאריכין באהבה רבה, סוד נשיקין שקודם הזווג כדי לעורר תאותה שתזריע תחלה ותלד זכר שהוא רחמים ודפח\"ח.\n----- הערות וציונים -----\nראה לעיל סי' קפב ובהערות שם, וסי' רסח.\n<i>והסוד כו'</i> – ראה מש\"כ כאן בשוה\"ג, והשוה לעיל סי' רנט ובהערות שם."]]],[300010359,"רצז\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; <span data-k=\"sm\">[דשמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> משל לסוחר אחד שהיה בים והיה סוער הים והולך למאוד עד סכנת מיתה, אז הסוחר עמד בתפלה שינצל בזכות אשתו הצנועה. והיה שם עכו\"ם עע\"ז ותמה על הסוחר שהתפלל עבור זכות אשתו, והשיבו שבאמת ראויה להפליג בשבחה. ואמר זה העכו\"ם אני אלך ואפתנה ואיזה אות אתה מבקש ממנה, והשיב שיש לה טבעת א' חשוב על ידה ואם יביאנו אז ידע וכו'. והסכימו על איזה קנס שיתן כל אחד סחורתו לזה שכנגדו שינוצח. והלך אצלה לפתותה ולא יכול להתקרב אצלה כלל, וחזר ובא אליה כמה פעמים באומרו שיש לו סוד מבעלה ולא השגיחה עליו, עד ששכר את שפחתה לגנוב ממנה הטבעת זה בכמה תחבולות שעשה ועלתה בידו, ובא עם טבעת זה הסימן לבעלה ולקח הסחורה ממנו, ובא בספינה ריקנית אל ביתו. ובשמעה האשה מביאת בעלה אז קשטה א\"ע ויצאה לקראתו בדברי ריצוי ואהבה שהיה ביניהם מאז ומקדם, וכל זה לא נכנס באזניו, והיתה תמה עליו ולא ידעה על מה זו ולמה זז מחיבתה ואהבתה, ובא עמה לביתה ולבו בל עמה, וסיבב הדבר עד ששלחה מעל פניו בספינה על הים בלי מנהיג, רק הבעל הכסות ולשון שינה כאלו הוא מלח אחד ממנהיגי הספינה לבדו. והלכה בספינה כמה ימים בלי מאכל ומשתה, והתחננה מזה המלח שיתן לה מעט אוכל להשיב נפשה, ואמר אם תנשק אותי אזי אתן לך, וכך עשתה בהכרח, ואח\"כ תבעה לתשמיש כו'. ויהי היום באה הספינה לחוף הים וזרקה הספינה וקפצה ליבשה וביקשה אוכל, ומצאה ב' אילנות, אחד שהאוכל ממנו נעשה מצורע והשני האוכל ממנו מתרפא מצרעתו, ולקחה זה בתרמילה עד שבאה לבית המלך בדמות איש והוצרך שם לרפואה זו, והיא עשתה רפואה ונתנו לה הון רב. וחזרה לביתה ומצאה לבעלה והתרעמה עליו מה שעשה לה ושילחה מביתו בספינה עם מלח אחד מכוער והוצרכה לנשקו ושאר דבר מכוער עבור גודל צער אכילה כו'. והבעל שמח בלבו על גודל תרעומתה וצניעותה, וחקר הבעל וימצא הדבר ששקר ענה בה העכו\"ם ושגנב טבעתה, ונתברר הדבר ואז עשה בו שפטים וכו'.\n<b>והנמשל</b> מובן בכל עניני עולם הזה מימות החורבן עד ביאת משיחנו ב\"ב אמן סלה. כי <i>מורי</i> &lt;הבעש\"ט זלה\"ה&gt; עשה עליית נשמה וראה איך מיכאל אפטרופסא רבא דישראל המליץ עבור ישראל שכל חוב שלהם הוא הכל זכות, כי כל &lt;מה&gt; שעושין פסלנות ושאר דברי חוב הכל כדי שיוכל לעשות שידוך עם ת\"ח, או לעשות צדקה וכיוצא בזה, הכל מוכרחים וכו'. ואשה צנועה הוא השכינה בסוד אשת חיל עטרת בעלה, ונתקנא הס\"ם ואמר עכשיו שיש להם בית המקדש וקרבנות, אבל אם תרצה לנסותן תחריב הבית המקדש ואני אפתנה כביכול וכו', וע\"י השפחה גנב הטבעת סוד גורל ב' השעירים, א' לה' וא' לעזאזל, וע\"י החטא עלה בשמאל וכו' ונחרב הבית המקדש, וכמ\"ש הרמב\"ן וכו', ושלחה בספינה וכביכול הש\"י שינה את עצמו בתוך שם קדוש סאל וכו', וזה סוד הוידוי תרעומות השכינה אליו ית' איך שהוכרחה וכו', ואח\"כ הוברר הדבר ששקר ענה בה, ואז זבח לה' בבצרה וכו' ודפח\"ח. והמשל הזה נוקב ויורד והבן.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י רב</b>,<b> ב [השמטה מפ</b>'<b> דברים] (תריד</b>,<b> א)</b>\n<i>מיכאל אפוטרופסא רבא דישראל</i> – זח\"ב רנד, א. שם קלט, א. <i>אשת חיל גו'</i> – משלי יב, ד. <i>א' לה' וא' לעזאזל</i> – אחרי טז, ח. <i>וכמ\"ש הרמב\"ן</i> – ראה פירושו לאחרי טז, ח. <i>שם קדוש סא\"ל</i> – זח\"ב ער, א. <i>זבח לה' בבצרה</i> – ישעי' לד, ו.\n----- הערות וציונים -----\n<i>מורי עשה </i>. .<i> מוכרחים וכו'</i> – כבר הובא לעיל סי' קסה.\n<i>וכ\"י הש\"י שינה כו' סאל</i> – ראה לעיל סי' פה, קטו וקכח ובהערות שם.\n<i>וזה סוד הוידוי</i> – ראה לעיל סי' רנב ובהערות שם."]]],[300010360,"רחצ\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> פי' המשנה עתיד הקב\"ה להנחיל לכל צדיק ש\"י עולמות שנא' להנחיל אהבי יש, וגם פסוק הישכם אוהבים את ה' כו'.",[["","","----- מקורות ומראה מקומות -----\n<b>סו</b>\"<b>ס תוי</b>\"<b>י ר</b>,<b> סע</b>\"<b>ג (תשכח</b>,<b> ב אות ה)</b>\n<i>עתיד הקב\"ה להנחיל כו'</i> – עוקצין פ\"ג מי\"ב. <i>להנחיל גו'</i> – משלי ח, כא. <i>הישכם גו'</i> – ראה יג, ד.\n----- הערות וציונים -----\nדיבור זה סתום ולא מצאתי לו ביאור. וראה מש\"כ בריש ההערות לסי' קנג-ג."]]],[300010361,"רצט-א\n\n<b>לפעמים</b> יכול להמשיך טובות ע\"י הדיבורים שהוא מדבר. למשל אם הוא בשביה ידבר מאותו ענין ארבעה צריכין להודות וכו', וכן כשחולה באיזה אבר ידבר באותו ענין בספירות העליונים השייכים לאותו אבר.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י מט (נו)</b>\n<i>ארבעה צריכין להודות</i> – ברכות נד, ב.\n----- הערות וציונים -----\nלהעיר מלעיל סי' רעג-ב והערות שם."]]],[300010362,"רצט-ב\n\n<b>כשיש</b> כאב לאדם יקשר א\"ע לבורא ית', דהיינו שיקשור את עצמו למעלות הבורא ית' ולא ירגיש הכאב.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י מט (נז)</b>\n----- הערות וציונים -----\nראה לקמן סי' תיב. ורג\"כ לקמן סי' שה. להעיר מר\"ה כט, א בזמן שישראל מסתכלין כו' היו מתרפאין. ולהעיר עוד מעירובין נד, א וזח\"ג קס, ריש ע\"ב."]]],[300010363,"רצט-ג\n\n<b>כשמדבר</b> דברי תורה על השלחן, הדברי תורה הם נשמה לאותו <span data-k=\"sm\">[מצוה]</span> הגשמיות של השלחן. וידבר הרבה דברי תורה &lt;על שלחנו תמיד בסעודתו בחול, וכל שכן בשבת&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י נ (נט)</b>\n----- הערות וציונים -----\n<i>וידבר הרבה כו'</i> – ראה זח\"ב קנג, ב. של\"ה שער האותיות אות ק', ערך יאריך על שולחנו לעשות רצון קונו (פה, ב (סא, ג) ואילך). מג\"א או\"ח ריש סי' קע. כף החיים או\"ח סי' קנז אות טז ואילך. ועיין ראשית חכמה שער הקדושה פט\"ו (ושם בסופו בענין המובא בזו\"ח רות פו, ד – הובא בנצוצי אורות להחיד\"א זח\"ב קנג, ב).\n<i>וכל שכן בשבת</i> – ראה מגילה יב, ריש ע\"ב."]]],[300010364,"רצט-ד\n\n<b>בערב</b> שבת בתפלת מנחה וקבלת שבת מעלין כל אותן הדיבורים והמצות של כל השבוע, שאז הוא עליית העולמות.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י נ (ס)</b>\n<i>בערב שבת כו'</i> – פע\"ח שער השבת פ\"א, פ\"ג ופ\"ה, ושם בהקדמה, פ\"ד ופ\"ז.\n----- הערות וציונים -----\nלהעיר מלקמן בהוספות סי' שכד-שכה."]]],[300010365,"ש\n\n<b>שמעתי</b> <i>ממורי</i> &lt;הבעש\"ט זלה\"ה&gt; ביאור מוסר למוכיח שיזהר בעצמו, על פי משל שנכנס חסיד אחד לכרך שיש בה בתי זונות, וביקש לחקור מהות אנשי הכרך אמר אלך אל בית המוזג ששם רבים מצויין ויש להבחין מעניני הסיפורים ודיבורים, כי הלשון הוא קולמוס הלב. וכך היה, שזה סיפר מה עשה עם הזונה פלונית, וכן חבירו כו', עד שחרה לו עד מאד. וכאשר הרגישו בו שהוא חסיד מפורסם נתנו לו כל אחד מתנה הגונה שיכפרו פניו במנחה. למחר עשה תחבולות שיתאספו שמה שיקבל מהם מתנות, עד שאח\"כ עשה כמעשיהם. והנמשל מובן. לכך ישמור את עצמו המוכיח מן הכיעור והדומה לו <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>סו</b>\"<b>ס תוי</b>\"<b>י רא</b>,<b> ב (תשלא</b>,<b> ב אות כב)</b>\n<i>הלשון הוא קולמוס הלב</i> – חובה\"ל שער הבחינה פ\"ה.\n----- הערות וציונים -----\nלהעיר מתוי\"י ר\"פ בהעלתך קלט, ריש ע\"ב (תפא, א): דשמעתי ביאור פסוק על זאת יתפלל כל חסיד אליך לעת מצוא רק לשטף מים רבים אליו לא יגיעו (תהלים לב, ו), כי הטובע בנהר וחבירו רוצה להצילו מושכו עמו, וז\"ש רק לשטף מים רבים אליו לא יגיעו וכו' והתקנה לזה שיקשור א\"ע תחלה בו ית' וכו' (והובא כ\"פ בתוי\"י ובשאר ספריו, ובכמה דוכתי מזכיר ששמע זה ממוהרי\"ל פיסטנר). ולהעיר על זה מזח\"א קיב, ריש ע\"ב. וראה לקו\"י סי' קיג (ואיתא ג\"כ באו\"ת סי' תפח), ושם הביא ג\"כ המשל אשר בזוהר שם."]]],[300010366,"שא-א\n\n<b>עוד</b> שמעתי <i>ממורי</i> &lt;הבעש\"ט זלה\"ה&gt; ביאור גדולה הכנסת אורחים מהקבלת פני שכינה. והקשה, והעולה אף שלפעמים הכנסת אורחים הוא ביטול תורה &lt;ע\"י סיפורים&gt; <span data-k=\"sm\">[או סיפורי לשון הרע וכו']</span>, מ\"מ גדולה הכנסת אורחים.",[["","","----- מקורות ומראה מקומות -----\n<b>סו</b>\"<b>ס תוי</b>\"<b>י רא</b>,<b> ב (תשלא</b>,<b> ב אות כד)</b>\n<i>גדולה הכנסת אורחים כו'</i> – שבת קכז, א.\n----- הערות וציונים -----\nראה לקמן סי' שב-א ובהערות שם.\n<i>אף שלפעמים כו'</i> – להעיר מלעיל סי' ח, צג-ג וסוף רכ-א, ולקמן סי' שעג."]]],[300010367,"שא-ב\n\n<b>כשמדבר</b> יחשוב ברמז קול ודיבור, וידבר ביראה ואהבה, ויחשוב שזה מדבר עולם הדיבור מפיו, אז מעלה הדיבורים.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י נו (ע)</b>\n<i>ברמז קול ודיבור</i> – זח\"ג רכח, א-ב. תקו\"ז ב, סע\"ב ואילך.\n----- הערות וציונים -----\nראה לעיל סי' ריח וריא.\n<i>וידבר ביראה ואהבה ויחשוב כו'</i> – ראה לקמן סי' שיג, ת-א ותיא."]]],[300010368,"שא-ג\n\n<b>&lt;פי'</b> המצא לנו בבקשתינו, כי&gt;<i>[ftnref_1_סו]</i> יחשוב שהוא אינו רק כלי, ומחשבתו ודיבורו הם עולמות המתפשטים. &lt;פי'&gt; עולם הדיבור שהיא השכינה מבקשת מעולם המחשבה על הדיבורים האלו, וכשימשוך אור הבורא ית' במחשבתו ודיבורו יהיה בקשתו שיתפשט השפע מעולם המחשבה אל עולם הדיבור, ויבוא ג\"כ באותו ענין שהוא מדבר מה שצריך לו ויעשה לו בקשתו. וזהו המצא לנו בבקשתינו, שיהיה הוא ית' נמצא באותן הבקשות.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י נג (סו)</b>\n<i>המצא לנו גו'</i> – סדר סליחות ד\"ה זכר לנו. <i>הדיבור שהיא השכינה</i> – זח\"ג רכח, א, ושם ע\"ב. זח\"א קמה, א. תקו\"ז ב, סע\"ב.\n----- שולי הגליון -----\n[ftn_1_סו]) <i>במקורו</i>: כשצריך לבקש איזה דבר מהבורא ית', יחשוב שנשמתו הוא אבר מהשכינה כביכול, כטפה מן הים. ויבקש על השכינה שאותו דבר הוא חסר להשכינה, ויהיה לו האמנה שבוודאי הוא פועל מלמעלה להשכינה. רק אם יהיה דבוק כראוי אל השכינה יתמשך גם כן השפע עליו. כמשל אדם שיש לו שמחה מטפח ביד, אפילו כשאינו מתכוין לכך, מחמת שהשמחה מתפשטת באבר, כן הוא בענין זה, שהוא אבר מהשכינה כביכול, יתמשך גם כן השפע עליו. ויחשוב שהוא <i>(כבפנים)</i>.\n----- הערות וציונים -----\nראה לקמן סי' שא-ד\n<i>עולם הדיבור שהיא השכינה</i> – ראה לקמן סי' שיג ותיא. ועיין תניא, אגה\"ק סי' כה."]]],[300010369,"שא-ד\n\n<b>האדם</b> כשידבק עצמו להדיבורים הדיבורים ימליצו בעדו, והוא שלא תהיה כוונתו לשום דבר רק לדבק עולם הדיבור לעולם המחשבה. וזהו פי' ג' ספרים נפתחים בראש השנה, ספר הוא לשון דיבור, <span data-k=\"sm\">[לשון]</span> סיפור של צדיקים שכוונתם אינו כ\"א ליחד עולם הדיבור לעולם המחשבה, נכתבים לאלתר לחיים, &lt;פי'&gt; שהם מתדבקים לאלתר להיות חיים. בינונים, שכוונתם לייחד וגם בשביל שיעשה הקב\"ה רצונם, &lt;בינונים&gt; תלוים ועומדים עד יוה\"כ שאז הוא התגלות עולם המחשבה, ויש לכל המחשבה עליה ונעשה ג\"כ מחשבתם. <span data-k=\"sm\">[וזהו הכתיבה, שמדבק האדם מחשבתו להקב\"ה ונרשם במחשבתו מה שיארע לו]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י נח (עא)</b>\n<i>ג' ספרים כו'</i> – ר\"ה טז, ב.\n----- הערות וציונים -----\nראה לעיל סי' שא-ג.\n<i>פי' ג' ספרים כו'</i> – ראה צוה\"ר סי' קכג."]]],[300010370,"שב-א\n\n<b>&lt;כתב</b> המחבר הרב הגאון החסיד הקדוש מ' יעקב יוסף הכהן זלה\"ה וז\"ל&gt; שמעתי <span data-k=\"sm\">[מהרבני הוותיק]</span> מוהר\"ן &lt;זלה\"ה&gt; פירוש על דברי &lt;מורי הבעש\"ט זלה\"ה&gt; <span data-k=\"sm\">[</span><i>הרב</i><span data-k=\"sm\"> הנ\"ל]</span> שיכוין בכל דיבור הכנעה והבדלה והמתקה <span data-k=\"sm\">[דמעל\"ד]</span><i>[ftnref_1_סז]</i> &lt;פירוש&gt; שיצא ממדת הגבורה שלא ללמד חוב על בני &lt;אדם&gt; <span data-k=\"sm\">[עולם]</span> רק שיכנס ברחמים וילמוד זכות על כולם. גם שרואה דברי כעירות מחבירו, ירגיש שהוא לטובתו שיבחין בעצמו שיש בו שמץ מנהו וישוב בתשובה ממנה גם במחשבה, וזהו טובתו, שאלו היה יחיד היה סובר שהוא חסיד משא\"כ עתה. ונ\"ל שזהו פי' לא טוב היות האדם לבדו מטעם זה, רק אעשה לו עזר מן כנגדו, שיבחין שיש בו שמץ מזה והבן. ולכך אם ע\"י שכן רע מבלבל תפלתו או תורתו או שאר ביטול, יתן לב שהוא לטובתו שלא היה בכוונה ישרה ושלחו לו ביטול זה להרגיש ויתחזק יותר, וכיוצא בזה, ישמע חכם ויוסף לקח. והעיקר להבין שהש\"י בכל מקום ובכל עסקיו, א\"כ גם בסיפורי דברים יוכל להרגיש עניני הבורא ית' כמו בלימודו ותפלתו.",[["","","----- מקורות ומראה מקומות -----\n<b>סו</b>\"<b>ס תוי</b>\"<b>י רא</b>,<b> סע</b>\"<b>ב ואילך (תשלא</b>,<b> ב אות כה)</b>\n<i>דברי הרב הנ\"ל</i> – לעיל סי' קס. <i>לא טוב היות גו'</i> – בראשית ב, יח. <i>ישמע חכם גו'</i> – משלי א, ה.\n----- שולי הגליון -----\n[ftn_1_סז]) שמעל\"ד: <i>הובא לעיל סי' קס</i>.\n----- הערות וציונים -----\n<i>פירוש על דברי הרב הנ\"ל</i> – פירוש זה בא תיכף אחרי סי' שא-א, וא\"כ דברי הרב הנ\"ל קאי על זה, וכן משמע מתוכן הדברים.\n<i>דמע\"ל</i> – דמעבר לדף, כלומר המובא שם בעמוד הקודם, תורת הבעש\"ט בענין הכנעה הבדלה והמתקה אשר הובאה לעיל סי' קס.\n<i>וילמוד זכות על כולם</i> – להעיר שעד\"ז הביא בשם מוהר\"ן בתוי\"י פ' וישב כט, א (קד, א). ולהעיר מלעיל סי' קסה (סוף סי' שצז). וראה תניא ריש פ\"ל. ולהעיר מאבות פ\"א מ\"ו ולקו\"ש חכ\"ז ע' 164.\n<i>שרואה דברי כעירות כו'</i> – ראה לעיל סי' צג-ג בשוה\"ג.\n<i>שיש בו שמץ מנהו</i> – ראה לעיל סי' פט וקטז ובהערות שם.\n<i>אם ע\"י שכן רע כו' יתן לב כו'</i> – ראה לעיל סי' צג-ג וצו-ג, ובהערות שם מצוה\"ר סי' קכ וביאורו בתניא, אגה\"ק סי' כה.\n<i>גם בסיפורי דברים כו'</i> – ראה לעיל סי' צג-ג ובהערות שם."]]],[300010371,"שב-ב\n\n<b>וגם</b> ביאר ענין נעשה ונשמע שהוא בכל אדם ובכל זמן, כי ע\"י עשיה כפשטא יוכל לשמוע ולהבין איך יתנהג בו לעבודת הש\"י, והוא בין בתפלה יעשה עשיה כפשוטו ואח\"כ ישמע, וכן בתורה ע\"י דביקות עשיה יהיה אח\"כ שמיעה להבין, וכן בכל ענינים גשמיים והבן.",[["","","----- מקורות ומראה מקומות -----\n<b>שם</b>\n<i>נעשה ונשמע</i> – משפטים כד, ז.\n----- הערות וציונים -----\n<i>שהוא בכל אדם ובכל זמן</i> – ראה לעיל סי' קי-א ובהערות שם.\n<i>ע\"י עשיה כפשטא יוכל למשוך כו'</i> – להעיר מתו\"א לאדה\"ז אסתר צו, ג ולקו\"ת במדבר יד, רע\"א."]]],[300010372,"שב-ג\n\n<b>והעיקר</b> להסיר העצבות ולאחוז בשמחה. וסיפר מה שחלם לו כשהיה בארץ ישראל והיה נבוך אם לצאת לחוץ לארץ מחמת טעמים הכמוסים לו כו', עד שראה בחלום שאחד סיפר לו שיש כמה רופאים הנותנים רפואות ע\"י משקה מר, אך זה הרופא יותר טוב שנותן רפואה ע\"י משקה מתוק מדבש, והוא ענין הנ\"ל שע\"י תענית וסיגופים <span data-k=\"sm\">[והתמדת לימודו]</span> גובר העצבות ומלמד חוב על בני עולם שאינן עושים כמעשיו ומניחין חיי עולם כו', וכמעשה דרשב\"י ובנו שיצאו ממערה הנזכר בש\"ס דשבת, עד שיצאה ב\"ק חזרו למערתכם כו', והוא רפואה ע\"י מים מרים, משא\"כ רפואה זו בדרך זה שיתן לב אף בכל דבר מגונה שרואה בחבירו שהוא לתועלת עצמו &lt;וידינהו לזכות&gt; וכנ\"ל, הוא ע\"י משקה מתוק מדבש לעורר רחמים בעולם ועל כל אדם שידע שהש\"י הוא בכל דבר פרטי ויתנהג כנ\"ל, אז הוא רפואה מתוקה בלי שום סיגוף, ויערב לו ויבושם, ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>שם</b>\n<i>וכמעשה דרשב\"י ובנו כו'</i> – שבת לג, ב.\n----- הערות וציונים -----\n<i>להסיר העצבות</i> – ראה לעיל סי' צג-ג ורמח (התנאי הג') ובהערות שם. צוה\"ר סי' טו, מד, מה ומו ובהערות שם. ועיין לקמן בהוספות סי' רה.\n<i>ולאחוז בשמחה</i> – ראה לעיל סי' נח (וסי' ערב) ובהערות שם, וסי' רכט. צוה\"ר סי' טו, מד, מה וקלז, ועיי\"ש בהערות וש\"נ. להעיר מזח\"ב קפד, ב ושם ריח, סע\"א ובהג' דרך אמת ונצוצי אורות שם.\n<i>הרופא יותר טוב כו'</i> – ראה לעיל בהערות לסי' רמט ד\"ה להלביש.\n<i>שע\"י תענית וסיגופים כו'</i> – ראה צוה\"ר סי' נו.\n<i>וכנ\"ל</i> – לעיל סי' שב-א ובהערות שם."]]],[300010373,"שב-ד\n\n<b>עוד</b> שמעתי ממוהר\"ן &lt;זלה\"ה&gt; <span data-k=\"sm\">[הנ\"ל]</span> פי' הש\"ס בת תחלה סימן יפה לבנים <span data-k=\"sm\">[. . . בשעה שעוסק בתורה ותפלה נקרא בן, וכשאינו עוסק בתורה כי אי אפשר שיהיה בתמידות אז ראוי שישמע מאחרים תורה או מוסר ואז נקרא בת וז\"ש שמעי בת וגו' . . . והנה לולי בחינת הבת היה סובר מאחר שהוא מדרגת הבן אין למעלה ממדרגתו, משא\"כ על ידי בחינת בת יש לידע שיש גבוה מעל גבוה שומר, וז\"ש בת תחילה]</span>, ר\"ל בכל מדריגה שיש לו יתן לב לידע שעדיין הוא בבחינת בת, ואז הוא סימן יפה לבנים שילך ממדריגה למדריגה הנק' בני\"ם, והבן ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>שם</b>\n<i>בת תחילה כו'</i> – ב\"ב קמא, א. <i>שמעי בת וגו'</i> – תהלים מה, יא. <i>גבוה מעל גבוה שומר</i> – קהלת ה, ז.\n----- הערות וציונים -----"]]],[300010374,"שב-ה\n\n<b>עוד</b> שמעתי &lt;ממוהר\"ן ז\"ל&gt; <span data-k=\"sm\">[ממנו]</span> וקוי ה' יחליפו כח, כי ע\"י מחשבה <span data-k=\"sm\">[רעה או זרה]</span> יוכל לעבוד ה' <span data-k=\"sm\">[כגון וכו']</span>, וז\"ש יחליפו רע בטוב כדי שיהיה להם כח לעבוד ה' וכו', <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>שם</b>\n<i>וקוי ה' גו'</i> – ישעי' מ, לא.\n----- הערות וציונים -----\nעיין לעיל סי' לט ובהערות שם."]]],[300010375,"שג\n\n<b>שמעתי</b> ממנו איך לעצור נקביו אם נתעורר לו באמצע תפלה עכ\"פ יעצור &lt;ויתפלל&gt; <span data-k=\"sm\">[מלהתפלל]</span> ויחשוב שיש נקראים קטנים ויש גדולים, כי הקטנים להראותו שהוא בקטנות ולמתקן וכו', וגדולים להתגדל ולהתפאר נתכוין, לכך מראין לו זה שישפיל את עצמו. וזהו שארז\"ל ותתחלחל המלכה שנצרכה לנקבי', והענין וכו'. וזה צריך &lt;לפנות&gt; <span data-k=\"sm\">[לפנים]</span> דהפוסקים כו'.",[["","","----- מקורות ומראה מקומות -----\n<b>סו</b>\"<b>ס תוי</b>\"<b>י רב</b>,<b> א (תשלב</b>,<b> ב סוף אות כז)</b>\n<i>ותתחלחל המלכה</i> – אסתר ד, ד. <i>שארז\"ל כו'</i> – מגילה טו, א.\n----- הערות וציונים -----\n<i>ויתפלל</i> – כן הוא בכל דפוסי הכש\"ט שראיתי והוא ממש היפוך ממש\"כ במקורו. וי\"ל שכונתו שימשיך להתפלל אחרי הכונה המבוארת בכאן, דהיא סגולה שיכול להעמיד עצמו עד שיסיים תפלתו, והוא ע\"פ מש\"כ בשו\"ע או\"ח ריש סי' צב עיי\"ש.\n<i>דהפוסקים כו'</i> – ראה שו\"ע או\"ח סוף סי' ג ובנ\"כ שם, וטושו\"ע סי' צב ונ\"כ שם."]]],[300010376,"דש\n\n<b>מזמור</b> לדוד, אמרו רבותינו כל מקום שנאמר מזמור לדוד מנגן ואח\"כ שורה עליו שכינה, מזמור להביא רוח הקדש לדוד, וכל שנאמר בו לדוד מזמור שרתה עליו שכינה ורוח הקדש ואח\"כ אמר שירה. והנה באמירת ספר תהלים יש לנו ליבוש ולהכלם דאימתי רוח הקודש שורה עלינו קודם האמירה או אח\"כ, יראה לומר בקדושה בטהרה באימה ביראה.",[["","","----- מקורות ומראה מקומות -----\n<b>?</b>\n<i>כל מקום שנאמר כו'</i> – פסחים קיז, א. מדרש תהלים כד, ג.\n----- הערות וציונים -----"]]],[300010377,"שה\n\n<b>&lt;מהבעש\"ט&gt;</b> וכל קרני רשעים אגדע תרוממנה קרנות צדיק, דהיינו כמ\"ש האר\"י ז\"ל בעת אשר שלט האדם באדם לרע לו לברר ניצוצי חיות ממנו, שהוא <span data-k=\"sm\">[היה]</span> הממשלה וחיות הרשעים, וע\"י ששלטו באדם הישר ובירר מהם הניצוצות אז הוסר מהם החיות והממשלה ונתרומם קרנות צדיק. וז\"ש שאל ממני וגו', ור\"ל שיסורי הצדיק הוא כדי שישאל ממנו ית' ויתפלל, שהם קשוטי ויחודי השכינה <span data-k=\"sm\">[כמו ששמעתי </span><i>ממורי</i><span data-k=\"sm\"> יעו\"ש]</span>, ואז ואתנה גוים נחלתיך, שע\"י ברורין יתרומם קרנך כאמור.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י נשא קכו</b>,<b> סע</b>\"<b>ב (תעב</b>,<b> א)</b>\n<i>וכל קרני גו'</i> – תהלים עה, יא. <i>כמ\"ש האר\"י ז\"ל</i> – ספר הגלגולים פ\"ב. פע\"ח שער ק\"ש פ\"ג. <i>עת אשר שלט גו'</i> – קהלת ח, ט. <i>שאל ממני ואתנה גו'</i> – תהלים ב, ח.\n----- הערות וציונים -----\nעיין לקמן סי' שצו."]]],[300010378,"שו\n\n<b>כאשר</b> האדם הוא מדבר באהבה ויראה הלא השכינה משתוקקת לדברים אלו, כמו האם המשתוקקת שידבר בנה דבר של שכל כדי שתחשב בפני בעלה. כך כשהדיבורים באים למעלה מכח האדם מקושטים בזה הכח נולד התפארות גדול, והמלאכים אומרים מי כעמך ישראל גוי אחד בארץ. ולכך עדיף שיאמר תיבה אחת בתפלה באהבה ויראה, כי בזה מעורר שכל המלאכים אומרים שירה להקב\"ה, וגם הוא מעורר כל העולמות, כשהוא עובד להקב\"ה כל העולמות עובדין אותו ית' &lt;כמ\"ש וכל קומה כו' והבן&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>קטע מס</b>'<b> מדל</b>\"<b>י סד (עז)</b>\n<i>מי כעמך גו'</i> – דה\"א יז, כא. <i>וכל קומה כו'</i> – פיוט נשמת כל חי.\n----- הערות וציונים -----\n<i>והמלאכים אומרים כו'</i> – להעיר מזח\"ב קנה, ב."]]],[300010379,"שז\n\n<b>הרוצה</b> לקבל עליו עול מלכות שמים בשלמות יפנה מחשבתו מהרהורים. ואפי' כשהוא אוכל ושותה ישים מחשבתו כדי שיהיה חזק לעבודתו ית', צריך להגביר תענוג הרוחני על תאות הגשמי, ומזה יהיה לו יותר כח מרוחניות המאכל, וזהו מה יפית ומה נעמת אהבה בתענוגים, &lt;פירוש&gt; שיהיה לך אהבה בתענוגים.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י ע (פב)</b>\n<i>הרוצה לקבל כו'</i> – ברכות יד, סע\"ב. <i>מה יפית גו'</i> – שה\"ש ז, ז.\n----- הערות וציונים -----\n<i>כשהוא אוכל ושותה ישים כו'</i> – ראה לעיל סי' רפב ובהערות שם.\n<i>להגביר תענוג רוחני כו'</i> – ראה לקמן סי' שצה-ב ושצה-ג. מדל\"י סי' רסב (ער).\n<i>וזהו מה יפית כו'</i> – להעיר מס' מאור עינים פ' ואתחנן ד\"ה וע\"כ אמרו (סב, ב): וכמאמר הבעש\"ט נבג\"מ ע\"פ מה יפית ומה נעמת אהבה בתענוגים גו' שמה יפה ומה נעים הוא שבכל התענוגים הוא האהבה העליונה שע\"י התעוררות זאת התענוג בטבעו יקל לו לאהוב את הבורא ב\"ה, כי בלאו הכי קשה לפתוח זאת המדה להתחיל לאהבו ית', וע\"י התענוגים שנתעוררה בו זאת האהבה יקל לו, והבן."]]],[300010380,"שח\n\n[<b>ובשם</b> <span data-k=\"sm\">המנוח החסיד מוהר\"י פיסטנר שמעתי, דאמרי]</span> לישרי לן מר, ר\"ל דבר מר כדי שיהיה גילה ברעדה, והשיב וי לן דמיתנן, <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י שלח קלז</b>,<b> א (תקכ</b>,<b> א)</b>\n<i>לישרי לן מר כו'</i> – ברכות לא, רע\"א. <i>גילה ברעדה</i> – ע\"פ תהלים ב, יא.\n----- הערות וציונים -----\nצ\"ע אמאי הביא פירוש זה והשמיט תורת הבעש\"ט הבאה אחריו! ובמקורו תיכף אחרי דברי הרי\"פ: ובזה נבאר ש\"ס דברכות לישרי לן מר אמר להו ווי לן דמיתנן כו', ויש בזה ב' דרכים, א' ע\"פ מה ששמעתי ממורי בענין שבת שיש מצוה באכילה ושתיה ע\"פ משל לבן מלך שהיה בשביה והגיעו כ\"י אביו המלך ורצה לשמוח ולכך הרבה להמוניים מיני משקה שישמחו הם ואז יוכל הוא לשמוח בשמחתו, והנמשל מבואר כי הנשמה א\"א לשמוח ברוחני עד שישמח החומר בגשמי וכו' ודפח\"ח. [וראה בזה לעיל סי' קז ולקמן סי' שצב, ועיי\"ע לעיל סי' רצה]. והכא נמי בענין שמחת חתן וכלה הוא שמחת רוחני, רק כדי לשמח החומר וכו', והנה הם שאמרו לישרי לן מר הבין שצריכין לשמוח ע\"י הגשמי במיני זמר, וז\"ש ווי לן דמיתנן שהוא החומר, כי לולי היו בהם שמחת רוחני לא צריך לזה, וק\"ל."]]],[300010381,"שט\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; <span data-k=\"sm\">[אם האדם חוטא וראוי לעונש אז השי\"ת]</span> הפך לבם לשנוא עמו, <span data-k=\"sm\">[ובזה יובן הקושיא הנ\"ל]</span> כי המצריים היו חוטאים בלא\"ה והיו ראויים לעונש <span data-k=\"sm\">[כמו ששמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> &lt;וז\"ש&gt; דן אנכי, כבר הוא נידון וכו' ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ר</b>\"<b>פ שלח קכח</b>,<b> סע</b>\"<b>ד (תפט</b>,<b> א)</b>\n<i>הפך לבם גו'</i> – תהלים קה, כה. <i>דן אנכי</i> – לך לך טו, יד.\n----- הערות וציונים -----\nעיין לעיל סי' קנב-ב.\n<i>הקושיא הנ\"ל</i> – לפני הפיסקא כתב דהקשה הרמב\"ם (שמנה פרקים פ\"ח. הלכות תשובה פ\"ו) למה נענשו מצרים ששעבדו את ישראל הלא גזר הש\"י וכו' ותירץ כי כ\"א חטא בבחירתו וכו' ויש לתמוה הא בפירוש כתיב בפסוק הפך לבם לשנוא עמו וגו' הרי שסילק הש\"י מהם הבחירה והדרה קושיא למה נענשו.\n<i>דן אנכי</i> – דהוה ליה למימר בלשון עתיד אדון אנכי, אלא דכבר נידון כו'. וראה לעיל סי' רסו (ובשוה\"ג שם)."]]],[300010382,"שי\n\n<b>האמנה</b> הוא הדביקות <span data-k=\"sm\">[כמו ששמעתי </span><i>ממורי</i><span data-k=\"sm\"> זלה\"ה, ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י שלח קכט</b>,<b> א (תפט</b>,<b> ב)</b>\n----- הערות וציונים -----\nכבר הובא לעיל סוף סי' רסז, וכן כמה פעמים בספרי התוי\"י. ולהעיר שזה מושג וביטוי שגור בכתבי המהר\"ל (ראה נתיבות עולם, נתיב האמונה פ\"א ופ\"ב. גבורות ה' פ\"ט ופ\"מ. נצח ישראל פ\"כ, פכ\"ט ופמ\"ז. תפארת ישראל פנ\"ה. ובחידושי אגדות לסנהדרין קי, סע\"ב ומכות כד, א)."]]],[300010383,"שיא\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; איתא בתיקונים כי ג' אבות תקנו חטא אדה\"ר מה שחטא בע\"ז וג\"ע וש\"ד שהוא סוד פגם בג' קוין, לפי מה ששמעתי <i>ממורי</i> &lt;הבעש\"ט&gt; חטא עבודה זרה תיקן אברהם שהוא קו האמצעי תיקון תפארת ישראל והושלך לכבשן האש פסילי אלהיהם תשרפון באש, יצחק תיקן ש\"ד קו שמאל, יעקב תיקן גילוי עריות שהוא קו ימין בסוד ואיש כי יקח את אחותו חסד הוא כו'. ואל תתמה איך אברהם תיקן קו האמצעי ולא קו החסד שהוא מדתו, כי זה סוד משארז\"ל יעקב פדה את אברהם מכבשן האש שהוא ע\"ד הנ\"ל, כי בו כלול הכל שנא' איש תם יושב אוהלים, כתרגומו גבר שלים. וז\"ש אנכי ה' אלקיך, שבו נכללו כל תרי\"ג מצות, וזה סוד כולם בחכמה עשית, רק החסד שבו כלול תפארת ודי בזה.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ס</b>\"<b>פ שלח קלח</b>,<b> סע</b>\"<b>ג (תקכה</b>,<b> ב)</b>\n<i>איתא בתיקונים</i> – ת\"ב קלט, א. זח\"ג קיא, ב. <i>הושלך לכבשן האש</i> – בר\"ר לח, יג. <i>פסילי אלהיהם גו'</i> – עקב ז, כה. <i>ואיש כי יקח גו'</i> – קדשים כ, יז. <i>קו החסד שהוא מדתו</i> – זח\"ג שב, א. <i>יעקב פדה כו'</i> – בר\"ר סג, ב. <i>איש תם גו'</i> – תולדות כה, כז. <i>אנכי ה\"א</i> – יתרו כ, ב. <i>שבו נכללו כל תרי\"ג מצות</i> – זח\"ב פה, ב. וראה שם ער, ב. <i>כולם בחכמה עשית</i> – תהלים קד, כד.\n----- הערות וציונים -----\nלהעיר מס' מגלה עמוקות ס\"פ לך לך. וראה הגה' החיד\"א לזח\"ב קמא, ב, וכסא מלך לתקו\"ז שם."]]],[300010384,"שיב\n\n<b>&lt;פעם</b> נאמר דרשו את ה' בהמצאו קראוהו בהיותו קרוב, וארז\"ל דקאי על עשי\"ת. ופעם נא' ובקשתם משם את ה\"א ומצאת כי תדרשנו, משמע כל זמן שתדרשנו, כמ\"ש אשר לו אלקים קרבים אליו כה' אלקינו בכל קראנו אליו. הפי' הוא&gt; דהנה היום בזמן הגלות הוא בקל&lt;ות נענה בתפלה ו&gt;להשיג רוח הקודש יותר מבזמן הבית, כמשל המלך כשהוא בבית מלכותו א\"א להתקרב אליו כ\"כ כמו כשהוא בדרך, שאז יוכל להתקרב אליו כל מי שירצה, אפי' בן כפר שאינו הגון לבוא לפני המלך בבית מלכותו, ובדרך בפונדק שלו יכול לבוא לפניו ולדבר עמו. כך היום בגלות, כשהאדם מחשב בדביקות הש\"י ב\"ה אזי <span data-k=\"sm\">[מיד]</span> שורה עמו ושוכן אצלו. בכן ראוי לאדם שיתרחק עצמו מן התאוות ומחשבות זרות בכדי שלא יפרד ממנו ית', רק יעשה כל מעשיו לשמו ית'. וזהו הרחק משכן רע, ר\"ל ממי ששוכן אצלך הרחק הרע.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י עז (פח)</b>\n<i>דרשו ה' גו'</i> – ישעי' נה, ו. <i>דקאי על עשי\"ת</i> – ר\"ה יח, א. <i>ובקשתם משם גו'</i> – ואתחנן ד, כט. <i>אשר לו אלקים קרבים גו'</i> – ואתחנן ד, ז. <i>הרחק משכן רע</i> – אבות פ\"א מ\"ז.\n----- הערות וציונים -----\n<i>היום בזמן הגלות הוא בקל כו'</i> – ענין זה הובא בנועם אלימלך פ' וישב (ד\"ה או יאמר וישב – הב', בביאור שם זבולון), וכן בס' עץ הדעת טוב, מאמרים לער\"ה (ד\"ה השיבנו), בשם הרה\"מ.\n<i>וזהו הרחק משכן רע כו'</i> – גם ענין זה הובא בשם הרה\"מ בס' אור המאיר ר\"פ נח."]]],[300010385,"שיג\n\n<b>אין</b> דיבור בלא מחשבה, כי מקודם הוא חושב מה שידבר. והנה כשחושב קודם התפלה מה שידבר ולפני מי ידבר, בוודאי תפול עליו יראה ובושה שיהיה ירא מהדיבורים עצמם כשנותן אל לבו שהעולם הדיבור היא השכינה כביכול מדברת בו, והיא כלולה מכל המדות יראה ואהבה והתפארות וכן כולם כידוע, ואיך לא יהיה לו יראה ובושה כשידע שמעורר השכינה וכל המדות כביכול. וזהו עושי דברו, שעושים מדיבור מעשה.",[["","","----- מקורות ומראה מקומות -----\n<b>קטע ממדל</b>\"<b>י עח (פט)</b>\n<i>הדיבור הוא השכינה</i> – זח\"ג רכח, א. זח\"א קמה, א. ת\"ז ב, ב. <i>עושי דברו</i> – תהלים קג, כ.\n----- הערות וציונים -----\n<i>אין דיבור בלא מחשבה כו'</i> – ראה לעיל סי' רעט הדיבור הוא כלי למחשבה, ובצוה\"ר סי' קח לבוש למחשבה.\n<i>שהעולם הדיבור כו'</i> – ראה לעיל סי' רפד-א ושא-ב<i>-ג</i>, ולקמן סי' ת-א<i>-ב</i> ותיא.\n<i>והיא כלולה כו'</i> – ראה זח\"ב קנח, א. זח\"ג רל, ב. תקו\"ז תס\"ט קח, סע\"א.\n<i>וזהו עושי דברו כו'</i> – ראה לעיל סי' רלד."]]],[300010386,"שיד\n\n<b>&lt;ועתה</b> ישראל מה ה\"א שואל מעמך כ\"א ליראה כו' לאהבה כו' ולדבקה בו. פי'&gt; כמו<i>[ftnref_1_סח]</i> השר, אפי' הוא גדול שבכל שרי מלוכה, בעומדו לפני המלך הוא בעיניו כמו קטן ואינו רוצה שיעשו לו שום כבוד מחמת גדלו ושררותו כמו שעושים לו כשהוא בביתו בפ\"ע, כי אז עושים לו כבוד ובושים ויראים ממנו. אמנם כשהוא לפני המלך, הוא וכל מדותיו נתבטלו מפני יראתו ובשתו מפני המלך. &lt;וז\"ש מה ה' שואל מעמך, פי' שתהי' במדריגת מה ע\"י לדבקה בו&gt;.\n*\n<b>בספר</b> קיצור חובת הלבבות זכור שתקות אנוש רמה.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י פ (צא)</b>\n<i>ועתה ישראל גו'</i> – עקב י, יב. <i>לאהבה גו' ולדבקה בו</i> – עקב יא, כב. <i>שתקות אנוש רמה</i> – אבות פ\"ד מ\"ד.\n----- שולי הגליון -----\n[ftn_1_סח]) <i>במקורו</i>: בדבר שהוא במדריגות אי\"ן לא שייך שבירה, כי השבירה שייך בדבר שהוא מדה או כלי, נמצא אם אדם מחזיק את עצמו לאי\"ן מחמת דביקותו בבורא ית', כמו (<i>כבפנים</i>).\n----- הערות וציונים -----\n<i>במדריגות אי\"ן לא שייך שבירה</i> – ראה מדל\"י סי' קכג (קלב) ורלב (רמו).\n<i>כמו השר כו'</i> – ראה לקמן סי' שצא. ורג\"כ לעיל סי' רצב-ב.\n<i>שתהיה במדריגת מה</i> – ראה לעיל סי' לא ושצא. ורג\"כ סי' קע ורצב-ב."]]],[300010387,"שטו\n\n<b>ופלגשו</b> ושמה ראומה, פי' <i>הבעש\"ט</i> דקאי על ענוה פסולה, פי' שמתגאה בענוה שלו ורוצה להראות שהוא עניו. וז\"ש ופלגשו, ענוה פסולה הנק' פלגש, ושמה ראו מה, פי' ראו שאני במדריגות ובחינת מה. ותלד את טבח, עי\"ז היצה\"ר טובח אותו.\n<b>ועל</b> ענין ענוה פסולה הנ\"ל משל <i>מבעש\"ט</i> זלה\"ה, לא' שהיו לו כל המעלות ומדות משובחות, אלא שהיה בעל גאוה גדול. ואמרו לו העולם, הרי יש לו כל המעלות משובחות, אלא שיש לך חסרון זה שאתה בעל גאוה, התלמד עצמך להיות עניו ושוב לא יחסר לך שום מעלה. ועשה כן, והתלמד להיות עניו כו'. ופעם א' הקניטו אדם א', אמר לו, שוטה שבעולם מה אתה חשוב לנגדי, כיון שאני עניו ג\"כ א\"כ לא יחסר בי שום מעלה כו'. והיוצא מזה כו'.",[["","","----- מקורות ומראה מקומות -----\n<b>?</b>\n<i>ופילגשו ושמה ראומה ותלד </i>. .<i> את טבח</i> – וירא כב, כד. <i>טבח </i>. .<i> טובח</i> – בר\"ר ספנ\"ז.\n----- הערות וציונים -----\n<i>ופלגשו </i>. .<i> טובח אותן</i> – ראה לעיל סי' לא ובהערות שם. וראה ג\"כ לעיל סי' רלח ולקמן סי' שצג.\n<i>משל מבעש\"ט זלה\"ה</i> – לא מצאתי מקור המשל, אבל בבפ\"י פ' חיי שרה לה, ריש ע\"ד (קעז, ב) – לפני סי' לא הנ\"ל – הביא משל דומה: ששמעתי במלך אחד ששאל מהרופאים מה יעשה שיחיה לעולם, ונתנו לו הרפואה שיתרחק מהגאוה ויכנס במדת ענוה ושפלות, וכאשר ידע שהוא עניו אז הרגיש שהוא עצם הגאוה וכו' יעו\"ש. משל זה הובא הרבה פעמים בספרי התוי\"י, ובצ\"פ פ' בשלח נ, סע\"ד (קפד, ב) הביאו (בתוספת) מפורש בשם הבעש\"ט. ולהעיר שבתוי\"י, פ' נשא קיט, ריש ע\"ב (תמו, ב), ושם פ' תצא קצא, רע\"ג (תרצו, א) מביא משל זה בשם ס' כפתור ופרח."]]],[300010388,"שטז\n\n<b>מהבעש\"ט</b> זלה\"ה. מה נורא המקום הזה אין זה כי אם בית אלהים וזה שער השמים. וקשה, דבשלמא אם היה אדם עומד לנגדו והיה אומר אין זה בית אלהים כ\"א בית אכסניא, היה שייך לומר בלשון זה אין זה כ\"א בית אלהים, ולא כמו שאתה אומר, אבל כיון ששום אדם לא היה עומד לנגדו להכחישו, מהו הלשון אין זה כ\"א בית אלהים, הוי ליה למימר מה נורא המקום הזה ודאי זה בית אלהים. ופי' ע\"פ הגמרא מכריז ר' ינאי חבל על דלית ליה דרתא ותרעא לדרתא עביד, ופי' דהתורה הוא בית שער ליראה. והנה ידוע שיעקב היה נטמן בבית עבר י\"ד שנה ועסק בתורה קודם שהלך לחרן, והנה כל הי\"ד שנה לא הרגיש יראה כזו שהרגיש כאן בהר המוריה, מקום בית המקדש, על כן אמר כך, מכח שאני רואה מה נורא המקום הזה אני גוזר ואומר אין זה כ\"א בית אלהים, זהו עיקר הבית והדרתא, כמו ביתי בית תפלה, וזה, פי' תלמודי שבידי מבית עבר, הוא שער השמים לבד, ותרעא לדרתא.",[["","","----- מקורות ומראה מקומות -----\n<b>?</b>\n<i>מה נורא גו'</i> – ויצא כח, יז. <i>מכריז ר' ינאי כו'</i> – שבת לא, ב. יומא עב, ב. <i>דהתורה הוא כו'</i> – פרש\"י ליומא שם. <i>שיעקב היה נטמן כו'</i> – מגילה יז, א. <i>ביתי בית תפלה</i> – ישעי' נו, ז.\n----- הערות וציונים -----\n<i>דהתורה הוא בית שער ליראה</i> – ראה לעיל סי' קנט.\n<i>לא הרגיש יראה כזו כו'</i> – להעיר מפדר\"א פל\"ה השכים יעקב בפחד גדול."]]],[300010389,"שיז\n\n<b>מעשה</b> בחסיד גדול א' שנסע אל <i>הבעש\"ט</i> זלה\"ה להיות אצלו ביו\"כ. ובערב יו\"כ, מחמת שלא נזדמן להם לקנות ביום האתמול שחת ותבן ומספוא ושבולת בשביל הסוסים, ולא אכלו הסוסים כל יום האתמול וכל הלילה, ע\"כ הוצרכו בבוקר לעמוד חוץ לעיר ביער א' לרעות הסוסים, ונחו עצמם מעט לישן. וכשעמדו ראו שהיה צאת הכוכבים, והיה עדיין רחוק פרסה לעיר, והוצרך החסיד להיות ביוה\"כ ביער ובשדה, כי לא היה יכול לילך שם ברגליו. והיה החסיד בצער גדול מאד, והתפלל בהכנעה רבה. אחר כך, מוצאי יוה\"כ, נסע החסיד לעיר, וקבלו הבעש\"ט זלה\"ה בסבר פנים יפות מאוד ובשמחה רבה, והיה מדבר תנחומין על לבו, ואמר לו שתפלתו הועילה להעלות כל התפלות של עם שבשדות.",[["","","----- הערות וציונים -----\nראה לקמן סי' שפה ובהערות שם."]]],[300010390,"שיח\n\n<b>וירד</b> מצרימה אנוס על פי הדבור. מהרב מ' דוב בער, דברית הלשון פוגם ברית המעור, וז\"ש וירד מצרימה, היינו בקליפות, אנוס ע\"י קרי, והוא בא לו ע\"פ הדיבור שפגם ברית הלשון.",[["","","----- מקורות ומראה מקומות -----\n<b>ס</b>'<b> אמתחת בנימין</b>,<b> הגדה</b>\n<i>וירד מצרימה</i> – כי תבוא כו, ה. <i>אנוס ע\"פ הדיבור</i> – הגדה של פסח. <i>דברית הלשון </i>. .<i> ברית המעור</i> – ס\"י פ\"ו מ\"ד.\n----- הערות וציונים -----\n<i>ברית הלשון </i>. .<i> ברית המעור</i> – רג\"כ ס\"י פ\"א מ\"ג.\n<i>דברית הלשון פוגם כו'</i> – עיין ר\"ח שער הקדושה פי\"א. ועיין לקו\"י ו, רע\"א (סוף סי' צז) ואו\"ת פ' משפטים סוף סי' ק."]]],[300010391,"שיט\n\n<b>הנחמדים</b> מזהב ומפז רב ומתוקים מדבש ונופת צופים גם עבדך נזהר בהם בשמרם עקב רב. וקשה, מ\"ט הוא ממשל התורה לזהב ופז ודבש כו'. עוד קשה, מהו הגם עבדך, דגם משמע טפלה, והא דוד קרא לנפשיה חסיד, כד\"א שמרה נפשי כי חסיד אני, ואיך יאמר גם עבדך נזהר בהם. וסיפיה דקרא יותר קשה, בשמרם עקב רב, דפי' דשמרם בשביל רב השכר, הלא התנא אסר זה באמרו אל תהיו כעבדים המשמשין את הרב ע\"מ לקבל פרס.\n<b>וי\"ל</b> ע\"פ דאי' בספרים אהא דישמחו במלכותך שומרי שבת וקוראי עונג <span data-k=\"sm\">[כו']</span> ישבעו ויתענגו, ומקשה הלא בעניני עסקי עוה\"ז התענוג הוא קודם השביעה, והל\"ל יתענגו וישבעו. ופי' דיש בעסקי עוה\"ז תענוג בלא שביעה לעולם, ושביעה<i>[ftnref_1_סט]</i> ואחר השביעה שוב אין תענוג. פי' בענין עסק קבוץ ממונות והון רב יש תענוג, מה שהוא עשיר יותר יש לו תענוג יותר מעשרו, אבל אין לו שביעה כד\"א אוהב כסף לא ישבע כסף. ואכילת תענוגי מעדני עוה\"ז אחר השביעה שוב אין לאדם תענוג, כי נפש שביעה תבוס נופת ואכול דבש הרבות כו'. וכ\"ז בעסקי עוה\"ז. אבל בלימוד התורה הוא כך, מי שהוא אינו חכם גדול בתורה אם יבקשו ממנו לפרש הלכה עמוקה וקשה, תחלה הוא מר לו כמרז\"ל ע\"פ שפתותיו שושנים נוטפות מור א\"ת מור כו', לסוף מתענג. אבל אם הוא חכם גדול בתורה, אפי' בתחלת העיון יש לו תענוג מפני שיכול לפלפל בחכמה ולמצוא ראיות ופירושים מכל הצדדים.\n<b>והנה</b> השבת לא ניתן לתענוג אכול ושתו לבד, אלא לעסוק בתפלה ותורה, כדפירש ר\"מ אלשיך ע\"פ וקראת לשבת ענג, ול\"ק וקראת לאכילה ושתיה ענג, דא\"כ מי שהוא עני דקיי\"ל עשה שבתך חול כו' א\"כ מהו הענג שלו, אלא הענג שלו יהי' מהשבת בעצם, דהבית דהנר שבת דולק בו לפני האדם, או ביום אור היום, הוא רומז לבית מושב אור פני הספירות ממש, שהוא קודש קדשים, וחוץ לבית, התחום שבת אלפיים באמה סביב, הוא תחום חותם, רושם אור הקדוש, וכל רוגזין וכל דינין וכל פולחנין קשין הם חוץ לתחום. וגם סוד הנשמה יתירה, כמ\"ש בסידור האריז\"ל ע\"פ ישמח משה במתנת חלקו, שנותנין לו במתנה בכל שבת האלף חלקי אור, בסוד תוס' נשמה יתירה, ועי\"ז, כי עבד נאמן קראת [לו], להחזיר לישראל אותן הכתרים עדים שהתנצלו בחטא עגל, וזהו כליל תפארת אשר בראשו נתת לו כו' ע\"ש. ע\"כ ארז\"ל ע\"פ שבת וינפש, כיון ששבת [וי] אבדה נפש, פי' כמו שהעשיר מרגיש יותר בצער העוני יותר מן עני בתולדתו, כן הצדיק שהיה לו נשמה יתירה ואור גדול וקדוש בשבת מרגיש יותר בצאת השבת מה נאבד ממנו, יותר מההדיוט. ע\"כ עיקר התענוג להצדיק יהיה מהשבת, ועסק התורה ותפלה בקדושה ובטהרה בשבת.\n<b>וז\"ש</b> ס' נועם אלימלך אהא דאמר ר' יוחנן &lt;אמר רב&gt; [משום רבי יוסי] כל המענג את השבת נותנין לו נחלה בלי מצרים, וקשה מ\"ט ל\"ק כל המענג עצמו בשבת. אלא מהו שבת שמא דקב\"ה, ופירוש כל המענג להקב\"ה, שנקרא שבת, ע\"י עסק תורה ותפלה שלו בכוונה גדולה. כמו שכתב הפרדס כי בהיות הבל פיו של אדם כח מתאצל מנשמתו, אם כן כפי שיעור נשמתו תהי' שיעור תפלתו, והנה בשבת שיש באדם תוס' נשמה יתירה ממקום גבוה א\"כ יש כח בתפלתו לעלות ולהעלות עמה גם התפלות של חול. ועי\"ז מענג להקב\"ה, שנקרא שבת, ע\"י תורה ותפלה שלו. לזה נותנין לו נחלה בלי מצרים.\n<b>והנה</b> השבת ניתן לישראל כדי שיהיו פנוין לעסוק בתורה, כמרז\"ל אמרה תורה כו' א\"ל קב\"ה זווג א' יש לי ושבת שמה. וז\"ש ישמחו במלכותך שומרי שבת וקוראי עונג, ומה יהי' העונג האמיתי לענג בו את השבת, ישבעו ויתענגו מטובך, פי' ע\"י התורה שמטבעה מה שאדם שבע ממנה יותר יש לו תענוג אז יותר.\n<b>וז\"ש</b> הנחמדים, פי' דברי תורה נחמדים מזהב ופז רב. כי זהב ופז אע\"ג דיש תענוג להעשיר מהם, מ\"מ יש חסרון שאין בהם שביעה, משא\"כ דברי תורה. ומתוקים מדבש ונפת צופים, שאחר השביעה שוב אין לו תענוג, כמ\"ש בדבש פן תשבענו והקיאתו, משא\"כ בתורה נא' כי נעים כי תשמרם בבטנך. גם עבדך נזהר, פי' כמ\"ש השל\"ה בשם (מהר\"ם) [מה\"ר שמואל יודא] פדאוה ז\"ל דנזהר י\"ל לשון זוהר הרקיע, כי כל התחכמות האנושיות אינם מזככים את האדם, לא גופו ולא נשמתו, כ\"ש חכמת הפילסופיא אשר עלי' נא' כל באיה לא ישובון לא ישיגו אורחות חיים, כי נפת תטופנה כו' ואחריתה מרה כלענה, כי שחה אל מות ביתה כו', אבל חכמת התורה הקדושה מזככת הגוף והנשמה. כי ע\"כ אדה\"ר קודם חטאו ארז\"ל עקיבו היה מכהה גלגל חמה, כי חמה נבראת לשמש העולם והוא נברא לשמש את קונו, וע\"י מה היה אור זהרו, ע\"י עסקו בתורה, כמו משה רבינו ע\"ה שנא' בו כי קרן עור פניו.\n<b>כי</b> מ\"ש ויטע ה' אלקים גן בעדן מקדם וישם שם את האדם אשר יצר [. . .] ויצו ה' אלקים על האדם מכל עץ הגן אכול תאכל ומעץ הדעת טוב ורע כו'. כי אע\"פ דאין מקרא יוצא מידי פשוטו, ששם אותו הקב\"ה בגן עדן שבארץ, אעפ\"כ פי' בזוהר הקדוש כי גן רומז לג\"ן סדרים שבתורה. ולפי הזוהר הכי פרושא, ויטע ה' אלקים גן, פי' הגן סדרים שבתורה, הוא בעדן מקדם, פי' גם הקב\"ה שהוא קדמונו של עולם היה לו עדן ותענוג ושעשועים מזאת התורה שקדמה לעולם, כמ\"ש ואהיה אצלו אמון ואהיה שעשועים יום יום, פי' רז\"ל אלפים שנה קודם שנברא העולם נבראת התורה, וישם שם את האדם אשר יצר, פי' הקב\"ה היה מלמדו תורה, כמ\"ש לעבדה ולשמרה, לעבדה זו מצת עשה ולשמרה זו מל\"ת, ויצו ה' אלהים על האדם לאמר, פי' אמר לו ולמדו האיך יהי' שמיעתו ולמודו בתורה, כי האומר ד\"ת יש לו לומר דברים שילמוד השומע מהם עצה וחכמה והשגה איך לעבוד את הש\"י, והשומע ד\"ת לא יאמר זה הפשט היה טוב וזה הפשט לא היה טוב כל כך, נמצא הולך מאת הלימוד בלי שום לימוד ליראת הש\"י, כ\"א בטוב ורע, וע\"ז התורה חוגרת שק ואומרת עשוני ככנור שמנגנין בו בבית משתאות. וז\"ש הקב\"ה לאדה\"ר, ויצו ה' אלהים על האדם לאמר מכל עץ הגן, פי' מכל אותן התורות שאלמדך תראה אכול תאכל, שיהיה לך אכילת הנפש, לרעבון הנפש השוקקה לעבודתו ית', כמ\"ש נמצאו דבריך ואוכלם ויהי דברך לי לששון, ונאמר ויאכילני את המגילה כו', אבל ומעץ הדעת טוב ורע, פי' שתשים דעתך לבד לומר זה יהי' פשט טוב מה שאין כן זה, לא תאכל ממנו כי ביום אכלך ממנו מות תמות, פי' תתקשר באלנא דמותא, כי זהו מפיתוי הנחש הן במלמד<i>[ftnref_2_ע]</i> הן בשומע. והנה ע\"כ בג\"ע הי' אדה\"ר ועזרו מלובש בזיווא דנהורא, כי הי' &lt;עשה ע\"י&gt; מרכבה לקדושה עליונה.\n<b>וענין</b> זה אפרש לך על פי מה שפ\"ר מאז\"ל<i>[ftnref_3_עא]</i> על פסוק ועשו לי מקדש ושכנתי בתוכם ככל אשר אני מראה אותך את תבנית המשכן כו' וכן תעשו, והק' חדא דהל\"ל ועשו לי בית להיות מקדש. עוד קשה ושכנתי בתוכם, בתוכו הל\"ל. עוד קשה מהו הדיוק ככל אשר אני מראה אותך, וגם מאי קאמר תבנית המשכן. עוד קשה וא\"ו דוכן תעשו, הל\"ל כן תעשו. ובסוף מלאכת המשכן נאמר וירא משה את כל המלאכה והנה עשו אותה כאשר צוה ה' כן עשו ויברך אותם משה, ופרש\"י, [אמר להם] ויהי נועם ה' אלהינו עלינו ומעשה ידינו כוננה עלינו גו', יהי רצון שתשרה שכינה במעשה ידיכם. אמנם, דהנה במלאכת המשכן, שהיא מלאכה קדושה חשובה נוראה, יתמה שכל כל אדם איך הי' מבוא לדור ההוא שלא היו אומנים בדבר לעשותה. דהנה אם יהיה למלך כלי כסף מצוייר בתכלית הדקות בשכל גדול, אם יראהו לאומן חכם גדול ויתפשהו בציור שכלו אפשר יעשה כמוהו, משא\"כ אם יראה המלך הכלי למי שאינו אומן, ויצוהו שילך הוא ויאמר להאומן כלי כזה ראיתי עשה כמותו, שבודאי שזה הרואה, כיון שאינו אומן, יחסיר ויעדיף בספרו ציורו להאומן, וגם האומן יחסיר ויעדיף כיון שלא ראה הכלי. כ\"ש אם לא יראה המלך כלי כלל, כ\"א כלי מצוייר על נייר, ויאמר לו שיספר ציורו להאומן, אפשר שיצא הכלי מקולקל. והנה כן פה. משרע\"ה לא הי' אומן, וגם לא הראה לו משכן וכלים בממש, כ\"א כמ\"ש במדרש דהקב\"ה הראה למרע\"ה אש אדומה אש לבנה אש ירקרקת אש תכלת וא\"ל עשה לי משכן, א\"ל משה להקב\"ה רבש\"ע מנין לי כל האשיות הללו, א\"ל וראה ועשה כתבניתם, פי' תכלת וארגמן ותולעת שני ושש.\n<b>כי</b> הנה בנין המשכן ע\"כ נכתב בתורה ונשנה, אע\"ג די\"ל מנפ\"מ מאי דהוה הוה, אלא הוא ללמוד אותנו שכל גדול לעבודת הבורא ית\"ש איך יוכל אדם לעשות א\"ע מרכבה לקדושה עליונה. כי כל מה שגילה לנו הזוהר וכתבי האריז\"ל מבנין העולמות העליונים והשמות של פרקי המרכבה, ושל ראיה שמיעה ריח דיבור חג\"ת נהי\"מ והמוחין עליונים, הוא שהאדם בעשותו מצוה או לומד תורה או מתפלל יעשה עצמו מרכבה לקדושה עליונה, גוף לנפש ונפש לרוח ורוח לנשמה ונשמה להקב\"ה, כמ\"ש כי כל פה לך יודה עד וכל קומה, פי' וכל השיעור קומה, לפניך תשתחוה, כדפי' השל\"ה ז\"ל ע\"פ עין תחת עין כו' יד תחת יד רגל תחת רגל, פי' כי הנה עין האדם נק' עין, וכן יד ורגל, והרי מצינו אותן הכינויים בהבורא ית', כמ\"ש הנה עין ה' אל יראיו, אזניו אל שועתם, היד ה' תקצר, ועמדו רגליו ביום ההוא. והרי אין לו ית' דמות הגוף. ופירש כי כמו המכיר את ראובן וכתב שלו, ואם מראין לו חתימת ראובן אומר זהו בודאי חתימת ראובן, כאלו הי' ראובן עומד לפניו, אע\"פ שראובן הוא אדם ברמ\"ח אברים והכתב הוא אותיות, אעפ\"כ ע\"י הכתב וחותמו נדמה לו כאלו ראובן עומד לפניו, כן באלו המדות יש למעלה מדה עליונה שהוא משגיח על כל העולם להיטיב, ונקרא עין, וח\"ו אין שם שום דמות עין שלנו. אך האדם כשמקדש עיניו שנחתם בו, כמ\"ש תתהפך כחומר חותם, הוא לראות בתורה ואותיותיה הקדושים, אז עין שלו מרכבה למדה עליונה שנקרא עין. וכן יש מדה עליונה המאזין תפלות ומקשיב תחנות, וכשאדם מקדש אזניו לשמוע ד\"ת אז הם אזניו מרכבה למדת אזן העליון. וכן יש מדה עליונה הנותנת לעולם השפע אלקי שנקרא בדרך משל יד, וכשאדם מקדש ידיו לעשות עמהן מצות מעשיות וצדקות אז ידיו הם מרכבה למדה עליונה הנק' יד. וז\"ש ע\"כ הקפידה התורה בחובל בחבירו ומחסר ממנו אבר לשלם חמשה דברים שהם נזק צער רפוי שבת ובשת, ופי' ואמר כי שמא זה האדם הנחבל הי' מקדש אבריו, להיותו מרכבה עליונה לקדושה עליונה, עין שלו מרכבה תחת עין יד תחת יד.\n<b>והנה</b> [זה] ענין בנין המשכן, ע\"כ הי' צריך בצלאל לידע צירוף אותיות שבהן נבראו שמים וארץ, כי בנין המשכן היה, שהיו מעתיקים פה במשכן הזה משכן ובנין כל העולמות, כמעתיק כתב מכתב שמעתיק אות באות, כן היו מעתיקים מקדש העליון במשכן הזה. ע\"כ נעשה המשכן בחכמה בתבונה ובדעת, כמו בנין העולם שנאמר בו ה' בחכמה יסד ארץ כונן שמים בתבונה בדעתו כו', ויש מלאכה שהיו נעשי' במעשה, ויש על ידי מחשבה כמ\"ש ולחשוב מחשבות, והמנורה שהוא סוד נעלם לא הי' יכול אפילו משה רבינו ע\"ה לעשותה, כמ\"ש ס' הקנה פר\"ש לי מעשה המנורה שלימה ומקשה כו'.\n<b>וכל</b> זה הי' להראות לעם בני ישראל כי כמו שיכולין להעתיק מקדש העליון וכל צרופי השמות במשכן הזה, שהוא מדברים דוממים וגשמיים עצים ואבנים וזהב וכסף ונחשת, כ\"ש האדם, שהוא עיקר משכן ה', כי היכל ה' המה, וכמ\"ש ויטוש משכן שילה אהל שכן באדם, וכמ\"ש לא בחרתי בעיר [גו'] ואבחר בדוד, כ\"ש שיוכל האדם לעשות עצמו מרכבה לקדושה עליונה להעתיק בעצמו ובאבריו כל העולמות וצירופי שמות רוחניות עליונה. וכל זה הי' ללמד דעת לבני ישראל.\n<b>וז\"ש</b> ועשו לי מקדש, פי' איני אומר יעשו לי בית להיות מקדש, אלא ועשו לי תיכף המקדש העליון יעתיקו הם, כי ושכנתי בתוכם, פי' יהי' שריית שכינה על עושי המלאכה, שתיכף שיקחו דבר לעשותו יכוונו לעשות כתבניתו העליון, כי ראה מופת על זה ככל אשר אני מראה אותך, פי' אני מראה אותך ולא את עושי המלאכה, אלא שאתה תלמדם. ומה אני מראה אותך, לא משכן ממש, כ\"א את תבנית המשכן כו' ותראה נפלאות, וכן ממש תעשו בלי שום חסרון, אע\"כ שיהי' שריית שכינה על עושי המלאכה. וז\"ש וירא משה את כל המלאכה והנה עשו אותה כאשר צוה ד' דייקא, כן עשו, ויברך אותם משה ואמר להם זה השכל. וה\"פ ויהי נועם, פי' השכינה שנקרא נועם של ד' אלהינו, ודאי הי' שורה עלינו, והראי' ומעשה ידינו כוננה עלינו, שנעשה בתכלית נכון כהוייתו בעולמות העליונים, ע\"כ יהי רצון שתשרה שכינה במעשה ידיכם, פי' בנין זה המשכן שהעתקתם פה כל מקדש העליון וכל ציור העולמות, הוא ללמדכם דעת לכל ימות עולם שבכל עת שתרצו לעשות מצוה תעשו עצמיכם מרכבה לקדושה עליונה להעתיק בעצמיכם שתשרה שכינה בכם, שאתם מקדש והיכל ד', תהיו נעשים מרכבה להשכינה בעשותכם המצות.\n<b>וז\"ש</b> דוד המלך ע\"ה גם עבדך נזהר בהם, פירוש, אינו אומר גם על עצמו, אלא ה\"פ, כי עד עתה דיבר משבחי התורה הקדושה, תורת ד' תמימה כו' עד הנחמדים מזהב כו', ועתה אמר גם, עוד מעלה נסתרת יש להתורה, ומהו, עבדך נזהר בהם, לשון זהר הרקיע, פי' התורה מזככת הנשמה והגוף, בשמרם, ע\"י שאני שומר התורה בקדושה, עקב רב, פי' אפילו העקב יכול להיות רב, כמו עקיבו של אדם הראשון שהי' מכהה גלגל חמה.",[["","","----- מקורות ומראה מקומות -----\n<i>הנחמדים גו' גם עבדך גו'</i> – תהלים יט, יא-יב. <i>שמרה נפשי גו'</i> – תהלים פו, ב. <i>אל תהיו כעבדים כו'</i> – אבות פ\"א מ\"ג. <i>דישמחו במלכותך כו'</i> – עמידה דשבת. <i>אוהב כסף גו'</i> – קהלת ה, ט. <i>נפש שביעה גו'</i> – משלי כז, ז. <i>אכול דבש גו'</i> – שם כה, כז. <i>שפתותיו שושנים גו'</i> – שה\"ש ה, יג. <i>א\"ת מור כו'</i> – שבת ל, ב. <i>כדפר\"מ אלשיך</i> – תורת משה, תצוה לא, יג. <i>וקראת לשבת ענג</i> – ישעי' נח, יג. <i>עשה שבתך חול כו'</i> – שבת קיח, א. <i>ישמח משה כו' </i>– עמידה שחרית דשבת. <i>שבת וינפש</i> – כי תשא לא, יז. <i>כיון ששבת וי כו'</i> – ביצה טז, א. <i>ס' נועם אלימלך</i> – ר\"פ שמות. <i>דאמר ר' יוחנן כו'</i> – שבת קיח, סע\"א. <i>שבת שמא דקב\"ה</i> – זח\"ב פח, ב. <i>הפרדס</i> – פרדס רמונים שט\"ז שלהי פ\"ה. <i>כמרז\"ל אמרה תורה כו'</i> – מדרש הובא בטור או\"ח סי' רצ. <i>פן תשבענו גו'</i> – משלי כה, טז. <i>כי נעים כי גו'</i> – משלי כב, יח. <i>כמ\"ש השל\"ה</i> – מס' שבועות ע' מעלת עושיה ומקיימה (מא, ג). <i>זוהר הרקיע</i> – דניאל יב, ג. <i>חכמת הפילוסופיא אשר עליה נאמר</i> – שו\"ת הרא\"ש כלל נה שלהי אות ט, הובא בשל\"ה שם במס' שבועות (לא, סע\"ד). <i>כל באיה גו'</i> – משלי ב, יט. <i>כי נפת גו' כלענה</i> – משלי ה, ג-ד. <i>כי שחה גו'</i> – משלי ב, יח. <i>עקיבו היה מכהה כו'</i> – זח\"א קמב, ב. <i>והוא נברא לשמש את קונו</i> – קידושין פב, א. <i>כי קרן גו'</i> – כי תשא לד, כט. <i>ויטע ה' גו'</i> – בראשית ב, ח. <i>ויצו ה' גו' ומעץ הדעת גו'</i> – בראשית ב, טז-יז. <i>דאין מקרא יוצא כו'</i> – שבת סג, א. <i>גן רומז לג\"ן סדרים שבתורה</i> – תקו\"ז תי\"ג כט, ריש ע\"ב. שם תכ\"ח עב, ב. סתמ\"ב פב, א. זח\"א (מדה\"נ) קד, ב. <i>ואהיה אצלו גו'</i> – משלי ח, ל. <i>אלפים שנה קודם כו'</i> – בר\"ר ח, ב. <i>לעבדה ולשמרה</i> – בראשית ב, טו. <i>לעבדה זו מ\"ע ולשמרה זו מל\"ת</i> – זח\"א כז, א. <i>התורה חוגרת שק כו'</i> – סנהדרין קא, א. <i>נמצאו דבריך גו'</i> – ירמי' טו, טז. <i>ויאכילני את גו'</i> – יחזקאל ג, ב. <i>באלנא דמותא</i> – זח\"א לה, ב. <i>מלובש בזיווא דנהורא</i> – זח\"א לו, ב. זח\"ב רכט, ב. זו\"ח שה\"ש סט, א. <i>ועשו לי מקדש גו' ככל אשר גו'</i> – תרומה כה, ח-ט. <i>וירא משה את כל המלאכה גו'</i> – פקודי לט, מג. <i>ויהי נועם גו'</i> – תהלים צ, יז. <i>דהקב\"ה הראה למרע\"ה כו'</i> – במ\"ר יב, ח. <i>כי כל פה כו'</i> – פיוט נשמת כל חי. <i>כדפי' השל\"ה ז\"ל</i> – של\"ה תולדות אדם בית נאמן. <i>עין תחת עין גו'</i> – משפטים כא, כד. <i>הנה עין ה' גו'</i> – תהלים לג, יח. <i>אזניו אל שועתם</i> – תהלים לד, טז. <i>היד ה' תקצר</i> – בהעלתך יא, כג. <i>ועמדו רגליו גו'</i> – זכרי' יד, ד. <i>תתהפך כחומר חותם</i> – איוב לח, יד. <i>בחובל בחבירו כו' לשלם כו'</i> – ב\"ק פג, ב. <i>לידע צירוף אותיות כו'</i> – ברכות נה, א. <i>בחכמה בתבונה ובדעת</i> – כי תשא לא, ג. ויקהל לה, לא. <i>כמו בנין העולם</i> – חגיגה יב, א. <i>ה' בחכמה גו' בדעתו גו'</i> – משלי ג, יט-כ. <i>ולחשוב מחשבות</i> – ויקהל לה, לב. <i>והמנורה </i>. .<i> לא הי' יכול כו'</i> – תנחומא שמיני ח. שם בהעלתך ג. <i>היכל ה' המה </i>– ע\"פ ירמי' ז, ד. <i>ויטוש משכן גו'</i> – תהלים עח, ס. <i>לא בחרתי בעיר גו'</i> – מ\"א ח, טז. <i>תורת ה' תמימה גו'</i> – תהלים יט, ח-יא. <i>עקיבו של אדה\"ר כו'</i> – זח\"א קמב, ב.\n----- שולי הגליון -----\n[ftn_1_סט]) <i>אולי צ\"ל</i>: ויש שביעה.\n[ftn_2_ע]) <i>נ\"א</i>: בל[ימוד] תלמוד.\n[ftn_3_עא]) <i>כן הוא בכל דפוסי ס' כש\"ט שראיתי</i>,<i> וצ\"ע</i>.<i> ונראה לי שצ\"ל \"שפ' רמאז\"ל\"</i>,<i> כלומר שפירש ר\"מ אלשיך ז\"ל</i>,<i> שבספרו תורת משה דק ברוב הדיוקים הנזכרים כאן</i>.\n----- הערות וציונים -----\n<i>דפי' דשמרם בשביל רב השכר</i> – ראה פרש\"י עה\"פ.\n<i>אלא לעסוק בתפלה ותורה</i> – ראה ירושלמי שבת פט\"ו ה\"ג. ילק\"ש ומדה\"ג ר\"פ ויקהל. טושו\"ע או\"ח סי' רצ ובנו\"כ שם. וראה זח\"ג קעד, רע\"א ובהג' החיד\"א שם. וראה לקמן סי' תב, ובהוספות סי' רלז.\n<i>וכל רוגזין וכל דינין כו'</i> – ראה זח\"ב קלה, ריש ע\"ב. וראה שם פח, סע\"ב. זח\"ג רמג, רע\"א ושם רפח, ב. וראה מדרש תהלים צב, ה.\n<i>כמ\"ש בסידור האריז\"ל כו'</i> – בסידור הר\"ש שם. וראה פע\"ח שער השבת פ\"ח. חסד לאברהם מעיין ב נהר מט.\n<i>מרגיש יותר בצאת השבת כו'</i> – להעיר מס' זכרון זאת להחוזה, בהשמטות לפ' תשא: שמעתי שדקדק הרב האיש האלקים קדוש ר\"י הבעש\"ט למה אנו אומרים זה בתחלת השבת שבת וינפש כדרש וי אבדה נפש, די לזה בשעתה במוצ\"ש, וידוע מה שתירץ הוא ז\"ל להוסיף לנו אהבה ושמחה משבת קודש בזכרנו כי אח\"כ תפסוק הנשמה היתירה הגדולה של שבת כאשר האריך במשל ומליצה. וכ\"כ בשפת אמת ר\"פ תשא (סד\"ה וכתבו).\n<i>השבת ניתן כו' לעסוק בתורה כו'</i> – להעיר מזח\"ב פח, סע\"ב וזח\"ג קעד, רע\"א, ולעיל ד\"ה אלא לעסוק.\n<i>דנזהר י\"ל לשון זוהר הרקיע</i> – ראה צוה\"ר סי' א (לעיל בריש הספר, צוואה אות א). לקמן בהוספות סי' צו ובהערות שם.\n<i>חכמת התורה הק' מזככת כו'</i> – ראה צוה\"ר סי' כט. וראה זח\"ג פ, סע\"ב ושם קנג, א.\n<i>כמ\"ש לעבדה ולשמרה כו'</i> – ראה תיב\"ע ות\"י עה\"פ. פדר\"א פי\"ב. ספרי פ' עקב פיס' מא. ועיין פרדס רמונים להרמ\"ק של\"א פ\"ו.\n<i>שילמוד השומע מהם עצה כו'</i> – ראה ע\"ז יז, ריש ע\"ב ופרש\"י שם. ספרי האזינו סוף פי' שכב. זח\"א יא, א. זח\"ב פב, סע\"ב ושם צו, סע\"ב. זח\"ג נג, ב ושם רב, ריש ע\"ב ורס, רע\"א. רמב\"ם סוף הלכות שחיטה וסוף הלכות תמורה.\n<i>והשומע ד\"ת לא יאמר כו'</i> – להעיר מעירובין סד, א כל האומר כו'.\n<i>מלובש בזיווא דנהורא</i> – ראה בר\"ר ספ\"כ. תקו\"ז סתנ\"ח צב, ב.\n<i>שפ\"ר מאז\"ל</i> – ראה מה שכתבתי כאן בשוה\"ג, והוא בתורת משה להרמ\"א תרומה כה, ח-ט.\n<i>יעשה עצמו מרכבה כו'</i> – ראה לעיל סי' קעד ולקמן סי' שנ.\n<i>כדפי' השל\"ה ז\"ל</i> – בשם ס' עבוה\"ק לרמא\"ג (ח\"ג פכ\"ו) וס' הפרדס להרמ\"ק (שכ\"ב פ\"ב), מיוסד על ס' שערי אורה לרי\"ג שער א עיי\"ש.\n<i>שהי' מעתיקים פה במשכן הזה כו'</i> – ראה זח\"ב נט, ב (ר\"מ), ושם רלא, ב ורלה, ב (תוס'). ולהעיר ממדרש תדשא, בראשית ב. רבינו בחיי לתרומה כה, ח-ט. דרשות ר\"י אבן שועיב, פ' תרומה. פרדס רמונים של\"א פ\"ח.\n<i>והמנורה כו' אפילו משה רבינו ע\"ה כו'</i> – ראה תו\"ש פ' תרומה כה, לא אות קצח ובהערות שם."]]],[300010392,"שכ\n\n<b>שנו</b> חכמים בלשון המשנה, ברוך שבחר בהם ובמשנתם, ר' מאיר אומר כל העוסק בתורה לשמה זוכה לדברים הרבה, ולא עוד אלא שכל העולם כולו כדאי הוא לו כו'. קשה מ\"ט קתני שנו חכמים בלשון המשנה, דאם הוא משנה ה\"ל להתחיל כמו כל המשניות. עוד קשה מה שייך כאן ברוך שבחר בהם ובמשנתם, דזה ה\"ל למיתני או בתחלת כל המשניות, ריש מס' ברכות, או בסוף כל המשניות. עוד קשה מה שייך לכאן ר' מאיר אומר כו'. עוד קשה דקאמר זוכה לדברים הרבה, ולא מפרש מה הם הדברים הרבה. וקאמר ולא עוד אלא שכל העולם כולו, הוא כפל לשון, כל העולם וכולו, וקשה דהל\"ל כל העולם לחוד, או העולם כולו. וכן תמהו המדקדקים בנוסח תפלת ר\"ה, גם כל העולם כולו חל מפניך כו'.\n<b>י\"ל</b> דלכאורה יקשה לכל הלומדי תורה הלומדים הגמרא והמשנה הקדושה ורואים דעות שונות במשנה, תנא זה מתיר וזה אוסר, זה מכשיר וזה פוסל, ויקשה הא התורה הקדושה ניתנה למשה רבינו ע\"ה מסיני מפי הגבורה, א\"כ כמו שהקב\"ה ב\"ה וב\"ש הוא אחד יחיד ומיוחד כן הוה ליה להיות בתורה דיעה אחת, ומאין ולאין הם כל אותן הדיעות בגמרא ובמשניות, וח\"ו תיפוק מיניה חורבה שיעלה על לב אדם לומר דהתורה נשתכחה מישראל ע\"כ כל תנא אמר לפי סברתו שלמד מן הי\"ג מדות שהתורה נדרשת, וח\"ו יבואו לומר שאין התורה ברורה בידינו. אבל האמת אינו כן, כי באמת כמו שהמשנה שנויה אצלינו בצורתה בלשונה כן היא שנויה אצל הקב\"ה במרום, באותו הלשון עם אותן התנאים הקדושים, כמאמר רז\"ל במדרש כשעלה משה למרום מצאו להקב\"ה שהיה דורש במס' פרה ואומר ר' אליעזר אומר עגלה בת שנתה ופרה בת שתים וחכמים אומרים כו', אתמה מרע\"ה כו' א\"ל הקב\"ה זהו ר\"א בן הורקנוס שמכריע כל חכמי ישראל בכף מאזנים, אמר משה רבינו ע\"ה יהי רצון שיצא מחלצי, אמר לו הקב\"ה ודאי שיצא מחלצך, הה\"ד ושם האחד אליעזר. כי זהו חלק תורתו מחלק נשמתו, כמרז\"ל התורה קדמה לעולם כמ\"ש ואהיה אצלו אמון ואהיה שעשועים יום יום, שהם אלפים שנה קודם שנברא העולם היתה התורה הקדושה שעשועים לפניו ית'. ומהו התורה, הם הם נשמותיהם של ישראל, כי ישראל ר\"ת יש ששים רבוא אותיות לתורה, ויש ששים רבוא אדם לישראל, כי תשא את ראש בני ישראל לפקודיהם, פי' כי תשא כשתרצה למנות א\"ת, ר\"ת אותיות תורה, רא\"ש, ר\"ת ששים רבוא אותיות, וכך הם בני ישראל לפקודיהם.\n<b>וזה</b> שאמרו רז\"ל נמלך הקב\"ה בנשמותיהם של צדיקים כשברא העולם, כי המה היוצרים יושבי נטעים עם המלך במלאכתו, וייצר ה' אלהים את האדם, פי' במדה כל היצירות נמלך ה' אלהים את האדם, עם הנשמות של צדיקים. ועל כן אנו אומרים בערבית אוהב עמו ישראל, ובשחרית הבוחר בעמו ישראל באהבה, ומהו האהבה, כי שמע ישראל ד' אלהינו, פי' ד' אלהינו ה' אחד, כשהיה יחיד בעולמו היה מיוחד אלקותו עלינו.\n<b>וענין</b> זה פי' במג\"ע משה קיבל תורה מסיני, משה ר\"ת מחלוקת שמאי הלל. פירוש, שלא תאמר מחמת תלמידי שמאי והלל שלא שמשו כל צרכן מחמת זה רבתה מחלוקת, כ\"א מחלוקת זה קיבל משה מסיני. כי הלל מימין משה, ע\"כ הוא מצד החסד, ע\"כ ב\"ה תמיד לקולא. שמאי משמאל משה, ע\"כ ב\"ש הם תמיד לחומרא. ומה דחשיב במס' עדיות מקולי ב\"ש ומחומרי ב\"ה, מפני שמדת החסד כלול ממדת הדין, וכן מדה\"ד כלול מחסד. פי' כי הלל כולל כל הנשמות של ישראל מצד החסדים, ושמאי כולל כל הנשמות מצד מדת הגבורה, ומשה כולל כולם מצד מדת הרחמים. נעשה אדם בצלמנו, נעשה ר\"ת נמלך עם שמאי הלל, והם הם בעצמם מצד אברהם יצחק יעקב, אברהם הוא מצד מדת החסד, יצחק מצד פחד יצחק, מדה\"ד, יעקב כולל מצד מדת הרחמים, כמ\"ש בזהר משה מלגאו יעקב מלבר.\n<b>וזהו</b> שאומרים וקרא זה אל זה ואמר קדוש קדוש קדוש ה' צבאות מכה\"כ. דעכ\"א ג\"פ קדוש ה' צבאות, פי' בס' הקנה דא\"ל המלאך דצבאות הוא ר\"ת צירוף בן ארבעים ושתים תיבות, פי' ע\"ד שפי' מהר\"מ אלשיך ע\"פ אורך היריעה האחת שמונה ועשרים באמה ורוחב ארבע באמה ע\"ש. וע\"ד משל, כי כמו הרב הרוצה להסביר לתלמידו שכל גדול עמוק שהמציא בתלמודו, והנה עמקות השכל הוא ניצוץ אחד של אור המאיר בכל ההלכה, אך הרב א\"א לו להסביר לתלמידו השכל העמוק הזה בתחלת העיון, אלא תחלה מעמידו בפשט ההלכה ודקדוקיה ופלפולי' בהרחבה ובדיבור רחב עד שנפתחים שערי העליון והאמת והצדק בלב התלמיד, אז יוכל להסביר לו גם שכל העמוק בדבורים מעטים עד שמבין ניצוץ השכל העמוק בדיבור א' לבד. כן הקב\"ה ב\"ה וב\"ש, מפני שלא באפשר לשום נברא להשיג שכל של ניצוץ נקודה הראשונה, שהוא יוד של שם הוי' ב\"ה, כמ\"ש בזהר דהוא דחילו דכולא, ע\"כ נעשה מילוי ומלוי מלואים, שעי\"ז נבנו עולמות התחתונים ובהרחבה גדולה. וכן הוא באותיותיה של תורה הנארגים כולם על שם הוי' ב\"ה, ששרשם י' של שם, שהוא הדביקות האמיתי, שע\"י ההרחבה מושג אח\"כ ניצוץ הקדוש הראשון. וז\"ש קדוש ראשון נגד מדת חסד לאברהם, קדוש ב' נגד מדת הגבורה דיצחק, קדוש ג' נגד מדה\"ר דת\"ת ישראל, ה' הוי' פשוט, צבאות פי' מן ה' הפשוט ירד למילוי ומילוי המילוי שהם מ\"ב אותיות שע\"י יבנו כל העולמות. כי פשוט הוא ד' אותיות הוי', ומלא הם יוד אותיות המילוי, ומלא דמלא הם כ\"ח אותיות, הם מ\"ב אותיות. ארך היריעה, של נוטה שמים כיריעה, הם שמונה ועשרים באמה, ורוחב הם ד' באמה. וז\"ש ע\"י ה', וצבאות של צירוף בן ארבעים ושתים תיבות, הוא מכה\"כ, ועל ידי עולמות הנגלים מושג גם הנסתר, כמו שכתוב ע\"פ בן פורת יוסף בן פורת עלי עין ע\"ש.\n<b>וטעם</b> הדיעות השונות במשנה, כדפי' במג\"ע בשם השערי אורה, דע\"כ נק' התורה תורת אמת, וכן משפטי ה' אמת, וכן דיין הדן דין אמת, דפסק הרמב\"ם בהל' סנהדרין דברוצח, או שאר חייבי מיתות, אף על גב דמטין על פי שנים לחוב, דדיני נפשות בכ\"ג, י\"ב מזכין וי\"א מחייבין זכאי, י\"א מזכין וי\"ב מחייבין כו' מוסיפין דיינים עד ע\"א, ולבסוף ל\"ו מזכין ול\"ה מחייבין זכאי, ל\"ה מזכין ול\"ו מחייבין, או אחד אומר איני יודע, דנין אלו כנגד אלו עד שיראה אחד מן המחייבין דברי המזכין. ופסק הרמב\"ם דאם לא ראו לו שום זכות מתחלה, וכל הסנהדרין אמרו חייב, הרי הוא זכאי, אע\"ג דברובא לחובה לחוד הוי חייב כ\"ש באמרו כולם חייב. ופי' ע\"פ השערי אורה, דע\"כ נק' משפט ה' משפט אמת, ולא משאר לשונות כגון משפט ישר או נכון, אלא להורות כמ\"ש הנביא ראיתי ה' צבאות וכל צבא השמים עומדים עליו מימינו ומשמאלו, ומקשי בגמרא וכי יש ימין ושמאל לפניו, אלא אלו מיימינים לזכות ואלו משמאילים לחובה, וקשה דבשלמא בבני אדם שדיעותם קצרות להבין ולידע האמת בתחלה ע\"כ צריך מיימינים ומשמאילים, מזכין ומחייבין, כדי שיתקיים הדין ע\"פ רוב דיעות, אבל להקב\"ה ב\"ה וב\"ש, שהוא מגיד מראשית דבר אחריתו, וא\"כ למה ליה מיימינים ומשמאילים, יאמר תיכף כך הוא הדין הנכון, אלא הקב\"ה ב\"ה וב\"ש מראה לנו ברחמיו שאין דינו לבאי עולם בחק ובלי טעם, אלא נתברר הדין ע\"י ויכוח של מיימינים ומשמאילים, ע\"כ נק' משפטי ד' אמת, כי כל האלפא ביתא מן א' עד ת' הם צבאות ומרכבות קדושות עליונות, ולהורות כי כל הצבאות ומרכבות מן א' עד מ', שהוא אמצע האלפא ביתא, הוי מיימינים לזכות, וכל הצבאות ומרכבות מן מ' עד ת' היו משמאילים לחובה, ונגמר הדין ע\"י מדה הממוצעת במדה\"ר וע\"י ויכוח, ע\"כ נק' משפט אמת. ע\"כ להורות לנו שתורתינו הקדושה היא אינה חוק בלי טעם, אלא הכל נתברר ע\"י ויכוח, ע\"כ הכתיב לנו התנא רבינו הקדוש בקבלה עד משרע\"ה מפי הגבורה שמות התנאים והחכמים וחלוקי הדיעות בהמשנה, לומר וללמד לנו שהיא תורת אמת, וכל דין מדיני המשנה נתברר ע\"י ויכוח. ע\"כ פסק הרמב\"ם דבאמרו כל הסנהדרין חייב הוא זכאי, כיון שלא נתברר הדין ע\"י ויכוח אפשר שכולם טעו.\n<b>וז\"ש</b> שנו חכמים בלשון המשנה, פי' למדו ותנו ושנו חכמים ושמות התנאים בלשון המשנה, זה מתיר וזה אוסר, זה מטמא וזה מטהר, ואל יקשה לך הלא כמו שהקב\"ה הוא אחד כן ה\"ל להיות דיעה אחת במשנה, אלא ע\"כ צ\"ל ברוך שבחר בהם ובמשנתם, פי' הקב\"ה בעצמו לומד המשנה כן עם שמות התנאים, שזהו חלק תורתם וזהו חלק נשמתם ושרשם שבמרכבה העליונה, וכמ\"ש בשם הקדושים שם התנא הוא חיות התנא והדין שאומר הוא השכל שלו, והשם הוי' פי' באיזה ענין הוא מדבר, אם באהבה או ביראה או רחמנות או בניצוח או בהודיה או בהתקשרות או איזה ממשלה, יכוין שם הוי' מנוקד בניקוד ספירה ההיא, והוא מקשר החיות עם המוחין. וכשלומד בדחילו ורחימו הוא מקשר עצמו להתנא ולומד אצלו, פירוש, לשרשו ואורו שבמרכבה עליונה, כמ\"ש בזוהר כי תנאים בהיפוך אתוון הם אתנים, כמ\"ש והאתנים מוסדי ארץ. עכ\"א ר' מאיר אומר כל העוסק בתורה לשמה, ומה שמצוה להזכיר שם התנא, כ\"ש העוסק בתורה לשמה, דע\"כ נק' תורה, דהיא מורה דרך לעבודת ד' דעמק הלכה.\n<b>והנה</b> בענין פסק ההלכה, מה שאומרים הלכה כר' מאיר או הלכה כר' שמעון, וכן בגמרא ג' שנים נחלקו ב\"ש וב\"ה אלו אמרו הלכה כמותינו ואלו אמרו הלכה כמותינו יצאה ב\"ק ואמרה אלו ואלו דברי אלהים חיים והלכה כב\"ה, א\"כ נראה לכאורה דברי ב\"ש הם לבטלה, ואיך אמר דאלו ואלו דברי אלהים חיים. ופירש מהרמ\"א ז\"ל, ואוסיף נופך, וגם להסביר ע\"ד משל ומליצה, דלכאורה יקשה, דמי לנו גדול מר\"א בן הורקנוס שבו מכריע כל חכמי ישראל, והקב\"ה אמר הלכה משמו קודם בואו לעולם, ומרע\"ה ביקש שיצא מחלציו, והרי אנחנו רואים דאין הלכה כר\"א ברוב התלמוד, ובנדה אמרו הלכה כר\"א בארבע ע\"ש, או [בארבע] בסדר טהרות כו', וא\"כ וכי ח\"ו הי' תורתו של ר\"א לבטלה כיון שאין הלכה כמותו. וכן יש להקשות על ב\"ש דהוי מחדדי טפי כו', וכן בפלוגתא דר' עקיבא ור' ישמעאל, דר\"ע דריש בכל התורה רבוי ומיעוטי ור' ישמעאל דריש כללי ופרטי, והלכה כר\"ע, ואפ\"ה רגילות לפרש בכלל ופרט משום דהיא דרשה שגורה, כמ\"ש התויו\"ט בב\"מ פ\"ד משנה ט' ע\"ש, ובשבועות פ\"ג משנה ה', וא\"כ וכי ח\"ו דברי התנא שאין הלכה כמותו יהיו לבטלה.\n<b>אלא</b> אפתחה במשל פי, ויהיה מובן כל זה בסייעתא דשמיא. דהנה מלכותא דארעא כעין מלכותא דרקיע, והנה אצל מלך בשר ודם יש לו עבדים השוכנים חוץ לחצר המלך, ויש עבדים שהם בחצר המלך, ויש לו שרים גדולים, וכל אחד מן השרים ממונה על איזה שירות לשרת את המלך עצמו, יש מנעילו, ויש מלבישו מלבוש מיוחד, ויש שנותן הכתר בראש המלך. והנה יש עוד מינוי אחר, דהיינו להדליק נרות בפלטין המלך. והנה טרקלין של מלך הוא מקום רחבת ידים, כמרז\"ל טרקלין עשר על עשר, והנה רוב הנרות שמדליקין השרים בטרקלין לפני המלך גורם תענוג ושעשוע וחדוה למלך, וכמ\"ש בש\"ע א\"ח סי' רס\"ג סעי' ח' לענין נר שבת, ב' או ג' בעלי בתים אוכלים במקום א' י\"א שכ\"א מברך על מנורה שלו וכתב המג\"א הטעם דכל מה דמתוסיף אורה יש שלום בית ושמחה יתירה להנאת אורה בכל זויות וזויות, א\"כ גם השר הזוכה להדליק נרות בזויות טרקלין ג\"כ גורם שעשוע ושמחה להמלך. אך הזוכה להדליק נרות נגד שער המלך, ובשער של מלך יש מחיצה של זכוכית לבנה ובהירה, א\"כ מהאור הגדול הזה הזורח לחוץ נהנים אפי' כל עבדי המלך אשר בחצר המלך וגם חוץ לחצר, כ\"ש שמגיע מזה תענוג ושעשוע וחדוה להמלך אשר עבדיו נהנים מגודל אורו. והנה אותן הי\"ג מדות שהתורה נדרשת בהן, מקל וחומר, פי' שלמדין חומרא להכא מהתם, או לקולא, וכגון ומה תמיד שאינו ענוש כרת דוחה את השבת פסח שענוש כרת אינו דין שדוחה את השבת, נמצא נותן מה שבמקרא של תמיד גם בפסח, הוא כמדליק נר שאינו דולק בנר דולק, כ\"ש גזירה שוה, דיש גז\"ש מופנה מצד אחד ויש מופנה משני צדדים, כמו דאמרינן גז\"ש נאמר מועדו בתמיד ונאמר מועדו בפסח מה מועדו האמור בתמיד דוחה את השבת אף מועדו האמור בפסח דוחה את השבת, נמצא אותו המקרא שיש בו מופנה הרי הוא בדרך משל כמו נר דולק, דע\"כ נק' מופנה ע\"ש אור העודף ויוצא בראשו, ולומד מזה את המקרא שאינו מופנה הואיל ושוה לו בגזירה שוה, הרי הוא מוסיף אור גדול וקדוש למעלה בשרשם שבמרכבה עליונה, כ\"ש במופנה משני צדדים ע\"י התקרבות ובטישות האורות זב\"ז נולד למעלה אור גדול וקדוש. ע\"כ לא גמיר אינש גז\"ש אא\"כ גמיר לה מרביה, כי רב ר\"ת ר' ראשית חכמה ב' בינה, וכן נר ר\"ת נ' שערי בינה ר' ראשית חכמה. וכן היקש, ארז\"ל אין משיבין על ההיקש. וזה השכל י\"ל באדה\"ר, שארז\"ל במוצאי שבת ניתן בו דיעה מעין דוגמא של מעלה ולקח ב' אבנים והקישן זב\"ז ויצא מהן אור, פי' ע\"ד רמז, דאותיות התורה נק' אבנים, ועשה היקש בלימוד התורה, כענין מקשה תיעשה המנורה, דא לדא נקשן, וגרם אור גדול וקדוש למעלה מהיכל מלך מלכו של עולם. וע\"כ נק' ריבוי ומיעוט, וריבוי פי' בס' הקנה ריבוי האור הבהיר הנדלק והמתנוצץ לכל צד, וכל דבר שהיה בכלל הא\"ס ויצא מן הכלל ללמד גבורתו ויכלתו כו', עמ\"ש בפירוש הי\"ג מדות.\n<b>והנה</b> זהו הנמשל, דכל תנא או אמורא, אע\"פ שאין הלכה כמותו, אעפ\"כ ע\"י לימוד תורתו בקדושה ובטהרה ע\"י המדות שהתורה נדרשת בהן גורם אור גדול וקדוש ושעשוע וחדוה למלך הכבוד בהיכל עליון. אך התנא שזכה שתהיה הלכה כמותו, הרי הוא בנמשל כמו השר שזכה להדליק נרות ואורות גדולות נגד שער היכל המלך, ששם דרך חלוני השער הולך האור הגדול והקדוש ומתפשט בכל העולמות. וע\"כ נקרא הלכה על שם הליכת האור, כדא' ה\"ד שיקול הדעת, דהוא דבר שנחלקו בו תנאים או אמוראים או גאונים, וסוגיין דעלמא אזלא כחד מנייהו, סוגיין דעלמא היינו הליכת האור. וע\"כ נא' בדוד וה' עמו, וארז\"ל שהלכה כמותו בכל מקום, פירוש שהוא רמז למדת המלכות, והבן.\n<b>וז\"ש</b> ארז\"ל ג' שנים נחלקו ב\"ש וב\"ה, אלו אמרו הלכה כמותינו, פי' סוגיין דעלמא הליכות האור, ואלו אמרו הלכה כמותינו, יצאה ב\"ק ואמרה אלו ואלו דברי אלהים חיים, פי' ב' הכתות ע\"י עסקם בתורה כנ\"ל, בק\"ו ובגז\"ש ובהיקש כו', גרמו אור גדול וקדוש למעלה, אבל והלכה כב\"ה, פי' הליכת האור מעולם לעולם שעל ידו נוכל אנחנו לילך לדביקות ועבודת הבורא ית\"ש הוא כב\"ה. כ\"ש בשאר תנאי דפליגי אהדדי, אע\"ג דהלכה כחד מנייהו, כתב רבנו הקדוש במשנה במסכת עדיות פ\"א משנה ה', ולמה מזכירין דברי היחיד בין המרובין הואיל ואין הלכה אלא כדברי המרובין, שאם יראה בית דין את דברי היחיד ויסמוך עליו, שאין ב\"ד יכול לבטל דברי ב\"ד חבירו עד שיהיה גדול ממנו בחכמה ובמנין כו', ועיין בתיו\"ט.\n<b>עי\"ל</b> ענין הלכה, דעכ\"א הלכה כר\"מ, דבכתבי האריז\"ל הריעו לה' כל הארץ הוא ר\"ת הלכה. וקשה, מנפ\"מ אם הריעו לה' כל הארץ הוא ר\"ת הלכה אם לאו, י\"ל דקשה מ\"ט אומרים לשון הלכה כר\"מ או הלכה כר\"ש, ולמה אין אומרים הנכון או הישר או הצדק כר\"מ או כר\"ש. אך ענין פירוש הלכה פירשו בגמרא בסוף נדה, תני דבי אליהו כל השונה הלכות בכל יום מובטח לו שהוא בן העה\"ב, שנאמר הליכות עולם לו, אל תקרי הליכות אלא הלכות. נמצא הלכה הוא נגזר מן הליכה, פי' כי כל התורה ומצותיה והלכותיה הם עצות גדולות וקדושות איך לבוא לדביקות הש\"י, נמצא כיון דהלכה הוא כהאי תנא, א\"כ דבר קדוש הם הליכה לעבודת הבורא ית'. א\"כ השונים ההלכות יש להם להיות גדולים וקדושי עליון, שהרי הם עוסקים בהליכת עולם לעבודת הבורא ית'. ומ\"ט אנחנו רואים קצת השונים הלכות שאינם על מדריגה זו, אך התנאי הוא כמ\"ש הפוסקים דאין התורה נקנית במי שלומד מתוך עדונין, אלא במי שממית עצמו עליה. וז\"ש האריז\"ל הריעו, ל' תרועם בשבט ברזל, פי' כשמשבר, לה', בשביל ה', כל הארץ, כל הארציות הגופניות, אז הוא ר\"ת הלכה, פי' אז הוא הליכה לעבודת הש\"י, ר\"ל שלהליכה זו צריך לשבר כל הארציות והחומריות.\n<b>וז\"ש</b> שנו חכמים, שמות התנאים האוסרין ומתירין בלשון המשנה, כי ברוך שבחר בהם ובמשנתם, שזו חלק תורתם וחלק נשמתם, ועמהם נמלך הקב\"ה כשברא העולם, כמ\"ש במג\"ע נעשה אדם בצלמנו, נעשה ר\"ת נמלך עם שמאי הלל, שהם כלל כל הנשמות של ישראל. וז\"ש ר' מאיר אומר כל העוסק בתורה לשמה, פי' ק\"ו הדברים, ומה שמצוה להזכיר שם התנא, כי כל האומר דבר בשם אומרו מביא גאולה לעולם, כ\"ש העוסק בתורה לשמה, דע\"כ נק' התורה תורה, לשון מורה דרך, פי' שמורה לנו הדרך איך נבוא לדביקות הש\"י, זוכה לדברים הרבה.\n<b>וענין</b> לימוד לשמה, כמ\"ש בס' כתר שם טוב אהא דאיתא בגמרא פ' תלמידים היו לו להלל עד קטן שבכולם ריב\"ז כו' לא הניח דבר גדול ודבר קטן דבר גדול מעשה מרכבה. והעולה משם שהלימוד יהיה להיותו מרכבה לו ית' ע\"י התורה, ופי' כי קב\"ה ואורייתא כולא חד, נמצא האומר דבר תורה ומשים בהדיבור ההוא כל כוונתו, והרי הכוונה היא הנשמה, נמצא מקשר נשמתו בחיות אור פנימי של דבר תורה ההוא והרי הוא מרכבה להש\"י, ורבן יוחנן בן זכאי עשה גם מהויות דאביי ורבא מעשה מרכבה. וז\"ש העוסק בתורה לשמה זוכה לדברים הרבה, מיירי משכר עולם הבא, שעל זה נאמר עין לא ראתה כו', ע\"כ סתים וקתני.\n<b>וע\"ד</b> שפירש הפרדס הקדוש אהא דארז\"ל כשעלה משה למרום מצאו לר' עקיבא וכ\"ד אלף תלמידים, והיה ר\"ע דורש כתרי אותיות, א\"ל משה להקב\"ה רבש\"ע הראתני תורתו הראני שכרו, הראהו שהיו סורקין בשרו במסרקות של ברזל ושוקלין בשרו במקולין, א\"ל זו תורה וזו שכרה, א\"ל שתוק כך עלה במחשבה. והקשה הפרדס הקדוש, חדא קשה דמשרע\"ה בקש הראני שכרו ולמה הראהו סריקת בשרו, הלא זה אינו שכרו אלא עונש, ומשרע\"ה אמר כן לו ית', רבש\"ע זו תורה וזו שכרה, א\"ל שתוק כך עלה במחשבה, הרי קשה גם על המחשבה, ומהו הלשון שתוק. ופי' דיש ג\"ע עליון וג\"ע תחתון, והנה יש צדיק שזכאי בדינו ליכנס לג\"ע התחתון, וכשרוצים להעלותו למדריגה יותר עליונה מדקדקים עליו יותר ויותר. ע\"כ הוא היאצ\"ט, שבנו צריך לנדור נדבות להציל אביו מקטרוג, כי כל י\"ב חדש הוא בסוד משפט רשעים כו'. והנה ר\"ע שהיה צדיק גדול וקדוש, ששמו הי' הולך מסוף העולם ועד סופו, ונהרג על קדוש ה', רצה הקב\"ה להעלותו תיכף בשעת מיתתו לג\"ע העליון, שנק' עולם המחשבה, ומה שצדיק אחר אינו זוכה כ\"א כמה שנים אחר מותו. והרי אין צדיק בארץ אשר יעשה טוב ולא יחטא חטא קל, ע\"כ הוצרך לאותן העונשים כדי שיתעלה תיכף כאשר יצאה ב\"ק ואמרה אשריך ר\"ע כו'.\n<b>וז\"ש</b> דמשה רבינו ע\"ה שאל הראיני שכרו, והרי שכרו של צדיק גדול כר\"ע ודאי נאמר עליו עין לא ראתה כו', ולא יתכן להשיב למרע\"ה א\"א לך לראות שכרו, אשר ע\"כ הראהו שסורקין בשרו, כדי שיבין משרע\"ה האמת שע\"כ הוצרך לעונשים האלה כדי שיזכה תיכף לג\"ע העליון שנקרא עולם המחשבה. ולכאורה לא הבין משרע\"ה, עכ\"א זו תורה וזו שכרה, א\"ל שתוק, כי לא הבנת האמת, כי ר\"ע זה כך עלה במחשבה, רצוני להעלותו לעולם עליון ולג\"ע עליון הנק' עולם המחשבה, ע\"כ צריך לכל זה.\n<b>וז\"ש</b> כל העוסק בתורה לשמה זוכה לדברים הרבה, שהוא שכר עולם הבא. ע\"כ לא פירש מה הם הדברים הרבה. ולא עוד אלא שכל העולם כולו כדאי הוא לו, כדפירש מהר\"מ אלשיך ז\"ל ביעקב ששמש בבית עבר י\"ד שנה ולא שכב ועסק בתורה לשמה, והראו לו שכל העולם כולו כדאי הוא לו, ויפגע במקום, פי' מהו החשוב מכל עולם השפל, הר המוריה, ולא רצו להטריחו ללכת הוא להר המוריה אלא נעקר הר המוריה ובא לקראתו, להראות שכל העולם השפל כדאי הוא לו. והחשוב מכל עולם הגלגלים הוא השמש, כי בא השמש, שקרה לו חמה בעונתה כדי שילין שם, להראות שכל עולם הגלגלים כדאי הוא לו. והנה מלאכי אלהים עולים ויורדים בו, להראות שכל עולם המלאכים כדאי הוא לו. ולז\"א כל העולם כולו, שכולל כל העולמות. אלא והנה ה' נצב עליו, לשמרו, כדפי' בזוהר ע\"פ הן בקדושיו לא יאמין ובמלאכיו ישים תהלה, כברא דאבא ואמא רחמין ליה ומסגיאות חביבותא דיליה לא המנין ליה במשרין דלהון אלא אנהו גופייהו נטרין ליה. פי' ע\"ד משל הנ\"ל, דקשיא דהל\"ל הן בקדושיו לא יאמן, בלא י', דיאמין הוא פועל יוצא. עוד קשה, דהל\"ל ובמלאכים ישים תהלה. ע\"כ פי' דהכי קאמר, הן בקדושיו, פי' בצדיקים, לא יאמין, לא יתן הקב\"ה נאמנות לשום מלאך לשמרו, ולא מבעיא מלאכים אחרים, אלא אפי' במלאכיו של הצדיק, שנבראו ע\"י מצותיו, שיש להם שפע ממנו ע\"י, אפ\"ה ישים בהם תהלה ולא יאמינם בשמירת הצדיק, אלא הקב\"ה בכבודו ובעצמו שמרו, כנזכר ביעקב והנה ה' נצב עליו לשמרו.\n<b>וע\"פ</b> הנ\"ל, משני דיעות שיש במשניות, יש לומר על פסוק כל הנחלים הולכים אל הים, פירוש תלמיד חכם נק' נחל, שהוא כמעין המתגבר וכנהר שאינו פוסק. וה\"פ ע\"ד רמז, פירוש חכם זה האומר מותר או כשר מביא ראיה מן התורה, כעין כל הזבחים שנזבחו שלא לשמן כשירים כו' חוץ מן החטאת שנאמר כחטאת כאשם ע\"ש, והאומר פסול מביא ג\"כ ראיה מן התורה. וזה מורה והים איננו מלא, פי' אינו ח\"ו במילואו וטובו, כי אל מקום שהנחלים הולכים שם הם שבים ללכת, שכל אחד מביא לעצמו ראיה מן התורה ומעמיד דבריו. וכי ח\"ו כל הדברים יגיעים, פירוש כמו שנאמר בדברים בטלים הוגעתם ה' בדבריכם, וכי ח\"ו גם דברי תורה כן, ואמר שלמה ח\"ו לא יוכל איש לדבר דבר כזה, אלא כי לא תשבע עין לראות את האורות עליונים שיש בעולם עליון ע\"י ב' הדיעות כו', ולא תמלא אזן משמוע השירה שע\"י שני הדיעות, כי בתורה ב' הדיעות יש להם שורש עליון במדות חג\"ת, וע\"י הויכוח וההכרעה מתברר האמת, מה שהיה הוא שיהיה ר\"ת משה, שהוא מחלוקת שמאי הלל, שניהם נתקבלו מסיני, ומה שנעשה הוא שיעשה ואין כל חדש תחת השמש.",[["","","----- מקורות ומראה מקומות -----\n<i>שנו חכמים כו'</i> – אבות פ\"ו מ\"א. <i>הי\"ג מדות כו'</i> – ריש ספרא. <i>כשעלה משה למרום כו'</i> – במ\"ר יט, א. תנחומא חקת ח. <i>ר\"א בן הורקנוס שמכריע כו'</i> – אבות פ\"ב מ\"ט. <i>ושם האחד אליעזר</i> – יתרו יח, ד. <i>התורה קדמה לעולם</i> – בר\"ר ח, ב. <i>ואהיה אצלו גו'</i> – משלי ח, ל. <i>ישראל ר\"ת כו'</i> – מגלה עמוקות אופן קפו. <i>כי תשא גו' </i>– תשא ל, יב. <i>נמלך הקב\"ה בנשמותיהם כו'</i> – בר\"ר ח, ז. <i>המה היוצרים כו' </i>– ע\"פ דה\"א ד, כג. <i>וייצר ה' גו'</i> – בראשית ב, ז. <i>שמע ישראל גו'</i> – ואתחנן ו, ד. <i>פי' במג\"ע כו' משה ר\"ת כו'</i> – אופן עד. <i>משה קבל כו'</i> – אבות פ\"א מ\"א. <i>תלמידי שמאי והלל כו'</i> – סוטה מז, סע\"ב. <i>הלל מימין כו' שמאי משמאל כו'</i> – זח\"ג רמה, א. שער הגלגולים הקדמה לד. ספר הגלגולים פמ\"ו. <i>במס' עדיות</i> – פ\"ד. <i>ומשה כולל כולם כו'</i> – זח\"ב קיד, סע\"ב. שם קיט, ב. <i>נעשה אדם גו'</i> – בראשית א, כו. <i>נעשה ר\"ת כו'</i> – מג\"ע אופן עד. <i>אברהם יצחק יעקב כו'</i> – זח\"א צו, א. זח\"ב קעו, סע\"א. <i>משה מלגאו כו'</i> – תקו\"ז תי\"ג כט, א. שם תס\"ט קא, ב. <i>וקרא זה גו'</i> – ישעי' ו, ג. <i>פי' בס' הקנה כו'</i> – ראה ס' הפליאה, ד\"ה ועתה צרף שם אלקים, שם ד\"ה אמר לו אדונינו וד\"ה המליך אות ת'. <i>שפי' מהר\"מ אלשיך כו'</i> – תורת משה תרומה כו, ב. <i>דהוא דחילו דכולא</i> – ר' זח\"ג ר\"מ קכב, סע\"ב. זו\"ח רות פד, ב. שם תיק' קא, סע\"ב. <i>בן פורת יוסף גו'</i> – ויחי מט, כב. <i>השערי אורה</i> – שער ה'. <i>תורת אמת</i> – מלאכי ב, ו. <i>משפטי ה' אמת</i> – תהלים יט, י. <i>דיין הדן דין אמת</i> – שבת י, א. <i>בהל' סנהדרין</i> – פ\"ט ה\"א-ב. <i>ראיתי ה' גו'</i> – דה\"ב יח, יח. <i>וכי יש ימין ושמאל כו'</i> – תנחומא שמות יח ומשפטים טו. זו\"ח בראשית יד, ג. ור' ירושלמי סנהדרין פ\"א ה\"א. <i>וכמ\"ש בשם הקדושים</i> – מדל\"י סי' יג (טז) ושם מד (מז). אוה\"א טז, א כשאומר אביי כו'. <i>תנאים בהיפוך כו'</i> – זח\"ב קי, ב. תקו\"ז תכ\"א מו, ריש ע\"ב. <i>והאתנים גו'</i> – מיכה ו, ב. <i>נק' תורה </i>. .<i> מורה דרך כו'</i> – זח\"ג נג, ב. <i>ג' שנים נחלקו כו'</i> – עירובין יג, ב. <i>ופירש מהר\"מ אלשיך</i> – תורת משה שפטים יז, ח-י. <i>דאין הלכה כר\"א כו'</i> – דשמותי הוא, שבת קל, ב. <i>ובנדה אמרו כו'</i> – נדה ז, ב. <i>ב\"ש דהוי מחדדי טפי</i> – יבמות יד, א. <i>דר\"ע דריש כו' ור\"י דריש כו'</i> – סוטה טז, סע\"א ואילך. שבועות כו, א. <i>והלכה כר\"ע</i> – עירובין מו, ב. <i>מלכותא דארעא כו'</i> – ברכות נח, א. <i>טרקלין עשר כו'</i> – ב\"ב צח, ב. <i>וכ' המג\"א</i> – שו\"ע שם אות טו. <i>הי\"ג מדות כו'</i> – ריש ספרא. <i>ומה תמיד כו'</i> – פסחים סו, סע\"א. <i>דאמרינן גז\"ש כו'</i> – פסחים שם. <i>לא גמיר כו'</i> – פסחים שם. <i>אין משיבין על ההיקש</i> – ב\"ק סג, ב. <i>במוצאי שבת ניתן כו'</i> – פסחים נד, א. <i>דאותיות התורה נק' אבנים</i> – ס\"י פ\"ד מי\"ב. תקו\"ז ת\"ע קלב, סע\"א. <i>מקשה תיעשה המנורה</i> – תרומה כה, לא. <i>דא לדא נקשן</i> – דניאל ה, ו. <i>הלכה על שם כו'</i> – ערוך ע' הלך. <i>ה\"ד שיקול הדעת</i> – סנהדרין ו, א. <i>וה' עמו</i> – ש\"א טז, יח. <i>שהלכה כמותו כו'</i> – סנהדרין צג, ב. <i>ג' שנים נחלקו כו'</i> – עירובין יג, ב. <i>דבכתבי האריז\"ל כו'</i> – לקו\"ת ושער הפסוקים תהלים ק. <i>הריעו לה' גו'</i> – תהלים ק, א. <i>תנא דבי אליהו כו'</i> – נדה עג, סע\"א. <i>הליכות עולם לו</i> – חבקוק ג, ו. <i>דאין התורה נקנית כו'</i> – רמב\"ם הל' ת\"ת פ\"ג הי\"ב. טושו\"ע יו\"ד רמו, כא. <i>במי שממית כו'</i> – ברכות סג, ב. <i>תרועם בשבט ברזל</i> – תהלים ב, ט. <i>כמ\"ש במג\"ע</i> – אופן עד. <i>כל האומר דבר כו'</i> – אבות פ\"ו מ\"ו. <i>כמ\"ש בס' כש\"ט</i> – לעיל סי' קעד. <i>פ' תלמידים כו'</i> – סוכה כח, א. <i>קוב\"ה ואורייתא כולא חד</i> – זח\"א כד, א. זח\"ב ס, סע\"א. שם צ, ב. <i>הכונה היא הנשמה</i> – ע\"ח ש\"מ דרוש ב. לקו\"ת להאריז\"ל פ' עקב. <i>עוה\"ב שעל זה כו'</i> – ברכות לד, ב. <i>עין לא ראתה גו'</i> – ישעי' סד, ג. <i>שפירש הפרדס הקדוש</i> – פרדס רמונים של\"ה פ\"ה. <i>כשעלה משה למרום כו'</i> – מנחות כט, ב. <i>כל י\"ב חדש הוא בסוד כו'</i> – מדרש משלי לא, כא. ירושלמי סנהדרין פ\"י ה\"ג. זח\"א רלח, ב. <i>ששמו הי' הולך כו'</i> – יבמות טז, א. <i>ונהרג על קדוש ה'</i> – ברכות סא, א. <i>אין צדיק גו'</i> – קהלת ז, כ. <i>יצאה ב\"ק ואמרה כו'</i> – ברכות סא, ב. <i>כדפירש מהר\"מ אלשיך</i> – תורת משה ר\"פ ויצא. <i>ביעקב ששמש כו'</i> – בר\"ר סח, יא. <i>ויפגע במקום כי בא השמש</i> – ויצא כח, יא. <i>נעקר הר המורי' כו'</i> – רש\"י ויצא כח, יז. <i>שקרה לו כו'</i> – בר\"ר סח, י. <i>והנה מלאכי אלקים גו'</i> – ויצא כח, יב. <i>והנה ה' נצב גו'</i> – ויצא כח, יג. <i>לשמרו</i> – חולין צא, ב, ורש\"י שם ד\"ה נצב. <i>כדפי' בזוהר </i>. .<i> כברא כו'</i> – זח\"ב קיט, סע\"א. <i>הן בקדושיו גו'</i> – איוב טו, טו. <i>[הן בעבדיו גו'] ובמלאכיו ישים תהלה</i> – איוב ד, יח. <i>כל הנחלים גו' והים גו' אל מקום גו'</i> – קהלת א, ז. <i>ת\"ח נקרא נחל</i> – תקו\"ז תי\"א קמח, א. <i>שהוא כמעין המתגבר כו'</i> – ע\"פ אבות פ\"ו מ\"א. <i>כל הזבחים כו' חוץ מן החטאת כו'</i> – זבחים ב, א. שם י, א-ב. <i>כחטאת כאשם</i> – צו ז, ז. <i>כל הדברים יגיעים לא יוכל גו' לא תשבע גו' ולא תמלא גו'</i> – קהלת א, ח. <i>שנאמר בדברים בטלים</i> – שמ\"ר יג, א. <i>הוגעתם ה' גו'</i> – מלאכי ב, יז. <i>מה שהיה גו' ומה שנעשה גו'</i> – קהלת א, ט. <i>ר\"ת משה</i> – זח\"ב קכ, א. תקו\"ז תי\"ח לו, ריש ע\"ב.\n----- הערות וציונים -----\n<i>אחד יחיד ומיוחד</i> – ראה ביאור בטוי זה בתו\"א לאדה\"ז פ' מקץ לב, רע\"ג.\n<i>כשעלה משה למרום כו'</i> – להעיר ממדל\"י סי' צט (קח).\n<i>ישראל ר\"ת כו'</i> – ראה ג\"כ במג\"ע אופן רמח. וראה זו\"ח שה\"ש עד, ד ושם רות פח, ג. ועיין לקו\"ת לאדה\"ז, בהר מג, ד. מדבר קדמות להחיד\"א מערכת יו\"ד אות ו. ועיין מה שהאריך בזה בנצוצי זוהר לזו\"ח עד, ד (במילואים שם ע' קכו, סע\"ב ואילך).\n<i>ומה דחשיב במס' עדיות כו'</i> – ראה תניא, אגה\"ק סי' יג.\n<i>כמו הרב הרוצה להסביר כו'</i> – להעיר מתניא, אגה\"ק סי' טו בביאור בחי' נה\"י.\n<i>וז\"ש קדוש ראשון כו'</i> – ראה פע\"ח שער חזרת העמידה פ\"ג. סידור האריז\"ל בכונות הקדושה.\n<i>וזהו חלק נשמתם כו'</i> – להעיר מזח\"ג כז, ב (ר\"מ) דמסטרא דמדות דקב\"ה אתיתו כו'.\n<i>מקום פירוש שהוא רמז למדת המלכות</i> – ראה זח\"ג רכה, סע\"ב. קהלת יעקב, ערך מקום.\n<i>דבכתבי האריז\"ל הריעו כו'</i> – רג\"כ פע\"ח שער הזמירות פ\"ד, ולקמן בהוספות סי' ע. ועיין סידור עם דא\"ח לאדה\"ז במזמור זה (מג, סע\"ב ואילך). ס' פירוש המילות לאדה\"א מהד\"ב פ' קמב ואילך.\n<i>הלכה הוא נגזר מן הליכה</i> – כנ\"ל מס' הערוך ערך הלך.\n<i>כל התורה כו' עצות גדולות כו'</i> – ראה לעיל בהערות לסי' שיט ד\"ה שילמוד השומע מהם עצה וש\"נ.\n<i>וז\"ש האריז\"ל הריעו ל' תרועם כו'</i> – אין זה בכתבי האריז\"ל הנ\"ל (לקו\"ת, שה\"פ ופע\"ח) אלא פירוש הבעש\"ט המובא לעיל סי' קעב עיי\"ש. ועיי\"ע מזה בסידור עם דא\"ח לאדה\"ז דף מד, סע\"ד ואילך. ולהעיר מלקמן הוספות סי' סח-סט.\n<i>הכוונה היא הנשמה</i> – ראה פרדס רמונים של\"א פ\"ה ופ\"ט.\n<i>וכשרוצים להעלותו למדריגה יותר עליונה כו'</i> – ראה שער הכונות, סדר הקדיש, ד\"ה אמנם קדיש בתראי.\n<i>ע\"כ הוא היאצ\"ט כו'</i> – ראה בס' חיים וברכה למשמרת שלום (להל' שמחות), ערך יא\"צ אות ט ואות טו.\n<i>לג\"ע העליון שנק' עולם המחשבה</i> – ראה זח\"ג רמז, רע\"א. וראה זח\"א כו, א. תקו\"ז תנ\"ג פז, ב ושם תנ\"ה פח, א.\n<i>כך עלה במחשבה רצוני להעלותו כו'</i> – להעיר משער מאמרי רז\"ל, סוף מס' שבת (יב, א): שתוק כך עלה במחשבה, ירצה שתוק כי ע\"י מיתה כזו עלה במחשבה ובמקום העינים. וע\"ע ע\"ה ש\"נ פ\"ה. שער המצות, בסוף ההקדמה. ולהעיר מס' הבהיר סי' טז. וראה או\"ת פ' תצא סוף סי' קה.\n<i>כדפי' בזוהר ע\"פ כו'</i> – להעיר שבזוהר שם לא הוזכרו פסוקים אלו."]]],[300010393,"שכא\n\n<b>הבן</b> יקיר לי אפרים אם ילד שעשועים. למי נפנה, לימין ואין עוזר כו', האם נמכור את עצמינו לעבדים לאו\"ה, ואלו לעבדים נמכרנו החרשתי, אעפ\"כ הנמכר לעקר משפחת גר – או דודו או בן דודו יגאלנו, וקרובי אם אפסו הן אתה נותרת, קרוב ה' לכל קוראיו, גואלי אם פסו הן אתה נשארת, כל שכן שכתבת בתורתך בסוף הצ\"ח קללות והתמכרתם שם לעבדים ולשפחות ואין קונה, ואעפ\"כ עבדים אנחנו כמ\"ש בעלונו אדונים זולתיך, והרי כתוב בתורתך לא תסגיר עבד אל אדוניו אשר ינצל אליך מעם אדוניו עמך ישב בקרבך וגו' בטוב לו לא תוננו, והרי אנחנו נסים היום אליך כמ\"ש ה' עוזי ומנוסי, אליך אנוס לעזרה, מפני כסא כבודך לא תסגירנו לאדון הצר השר הסורר. הנה אנחנו עומדים לפניך, ולפני כסא כבודך נאמר כמ\"ש קנה אותנו ואת אדמתינו בלחם, ונהיה עבדים לך. אנה שולחן אבינו, אוי לבנים שגלו מעל שלחן אביהם, אעפ\"כ ודאי ה' הצדיק, מה נתאונן כו' נחפשה דרכינו ונחקורה ונשובה.",[["","","----- מקורות ומראה מקומות -----\n<i>הבן יקיר גו'</i> – ירמיה לא, יט. <i>ואלו לעבדים גו'</i> – אסתר ז, ד. <i>הנמכר לעקר משפחת גר</i> – בהר כה, מז. <i>או דדו גו'</i> – בהר כה, מט. <i>וקרובי אם אפסו כו'</i> – יוצר לשבת ה' אחר פסח ד\"ה יקוש. <i>קרוב ה' גו'</i> – תהלים קמה, יח. <i>גואלי אם פסו</i> – יוצר הנ\"ל. <i>והתמכרתם שם גו'</i> – כי תבוא כח, סח. <i>בעלונו גו'</i> – ישעי' כו, יג. <i>לא תסגיר עבד גו'</i> – כי תצא כג, טז-יז. <i>ה' עוזי גו'</i> – ירמי' טז, יט. <i>קנה אותנו גו'</i> – ויגש מז, יט. <i>אוי לבנים שגלו כו'</i> – ברכות ג, א. <i>מה נתאונן גו' נחפשה גו'</i> – איכה ג, לט-מ.\n----- הערות וציונים -----"]]],[300010394,"שכב\n\n<b>מעי</b> מעי אוחילה, פי' על בניי יוצאי מעי, קירות לבי הומה לי לבי לא אחריש כי קול שופר שמעה נפשי. דכמו שבעולם הזה תוקעין בשופר, כן בעולם עליון בשופר גדול יתקע, וקול זה השופר שמעה נפשי. לפנים היו נביאים השכם ושלוח, ועתה לא נשאר כ\"א קול שופר שמעה נפשי תרועת מלחמה. שבר על שבר נקרא, לא די לנו בשבר חורבן בהמ\"ק, כמ\"ש מה אעידך כו' כי גדול כים שברך, אלא הגזירות רעות ועניות, כי שודדה כל הארץ פתאום שודדו אהלי רגע יריעותי. אין אדם בטוח בחייו ועושרו כמו לפנים בארץ הקדושה, שהיה איש תחת גפנו, ובפרט הולכי נהרות וימים.",[["","","----- מקורות ומראה מקומות -----\n<i>מעי מעי אוחילה קירות לבי גו' תרועת מלחמה</i> – ירמי' ד, יט. <i>שבר על שבר גו' כי שודדה גו'</i> – ירמי' ד, כ. <i>מה אעידך גו' כי גדול גו'</i> – איכה ב, יג. <i>שהי' איש תחת גפנו</i> – מ\"א ה, ה. מיכה ד, ד. <i>עד מתי אראה נס גו'</i> – ירמי' ד, כא. <i>כנשוא נס גו'</i> – ישעי' יח, ג. <i>וביום שמחתכם גו' ותקעתם גו'</i> – בהעלתך י, י. <i>בחצוצרות וקול שופר גו'</i> – תהלים צח, ו. <i>תורה חדשה כו'</i> – ויק\"ר יג, ג. <i>מחיצה לפנים ממה\"ש</i> – במ\"ר כ, כ. <i>האובדים בארץ אשור גו'</i> – ישעי' כז, יג. <i>כל יושבי תבל גו' כנשוא גו'</i> – ישעי' יח, ג. <i>או\"ה שנק' הרי נשף</i> – ר' איכ\"ר פתיחתא כד. <i>תנו לה\"א כבוד גו'</i> – ירמי' יג, טז. <i>ואת רודפיהם גו'</i> – נחמי' ט, יא. <i>וכתקוע שופר גו'</i> – ישעי' יח, ג. <i>וראיתי את הארץ גו' ראיתי ההרים גו' ראיתי והנה גו'</i> – ירמי' ד, כג-כה. <i>מלאכים יחפזון</i> – פיוט ונתנה תוקף.\n----- הערות וציונים -----"]]],[300010395,"(שכג)\n\n<b>עד</b> מתי אראה נס אשמעה קול שופר, ולא שופר גדול שלעת\"ל, עד מתי אומר בקדושה מתי תמלוך בציון כו'. אראה נס, אימתי אראה כנשוא נס הרים תראו כו'. אימתי אשמעה קול שופר שלע\"ל, וגם קול של חצוצרות, כמ\"ש וביום שמחתכם כו' ותקעתם בחצוצרות כו', ושופר כמ\"ש בחצוצרות וקול שופר הריעו לפני המלך ה'. מתי יבוא משיח, מתי יבנה בהמ\"ק, מתי נשמע תורה חדשה מפי הקב\"ה מחיצה לפנים ממה\"ש, מתי נשמע שופר של משיח, מתי יבואו האובדים בארץ אשור כו'.\n<b>או</b> עד מתי אראה נס, הוא שפורשין בספינה לרוח לפרוש לעמקי ים, וכן אנחנו גלי ים עברו עלינו כו', מתי יקוים כל יושבי תבל גו' כנשוא נס הרים תראו, הם או\"ה שנק' הרי נשף, כמ\"ש תנו לה' אלהיכם כבוד בטרם יחשיך ובטרם יתנגפו רגליכם על הרי נשף, ויפרוש הנס לטורדם במעמקי ים כמ\"ש ואת רודפיהם השלכת במצולות כמו אבן במים עזים, וכתקוע שופר תשמעו, שעי\"ז יבואו האובדים בארץ אשור.",[["","","----- מקורות ומראה מקומות -----\nראה מקבילות לעיל סימן שכב.\n----- הערות וציונים -----"]]],[300010396,"(שכד)\n\n<b>ראיתי</b> את הארץ והנה תוהו ובוהו ואל השמים ואין אורם ראיתי ההרים והנה רועשים וכל הגבעות התקלקלו ראיתי והנה אין האדם. פי' לא יחרדו כמו מלאכים יחפזון כשתוקעין בשופר גם בעולם העליון.",[["","","----- מקורות ומראה מקומות -----\nראה מקבילות לעיל סימן שכב.\n----- הערות וציונים -----"]]],[300010397,"שכה\n\n<b>שלח</b> לו רבן גמליאל גוזרני עליך שתבוא אצלי במקלך ובמעותיך ביום הכפורים שחל להיות בחשבונך. משל למה הדבר דומה, לבעל חוב שהתרו בו שלשים יום שיזמין מעות, ועשו הכרזה ל' יום על קרקעותיו, כדי שיתיירא ויזמין מעות לפרוע לב\"ח, והלך והביא מוניטא דשקרא, ורצה אח\"כ ללות עוד ונתנו לו ג\"כ מוניטא דשקרא. כן אנחנו מכריזין בשופר ל' יום להביא הכסף לשלם בר\"ה וביוה\"כ. וזהו הרמז, שלח לו רבן, רב של כל העולמות, גמליאל, הגומל חסד חסדים טובים, גוזרני כו' שתבוא במקלך, להציל עצמך מיד השטן והמסטינים החוחים והקוצים, לקדם ברועים ובמקלות, ומעותיך, שהם מעש\"ט, ובזמן שבא כמ\"ש וצרת הכסף בידך וקמת ועלית אל המקום, כסף שיש עליו צורה של מעשה, אז באמת חזרו ולקחו שפע גדול ועושר רב כמ\"ש ונתת הכסף בבקר ובצאן ביין ובשכר ובכל אשר תשאלך נפשך. אבל כאשר אומרים לא נכחד מאדוני כי תם הכסף אל אדוני, פי ע\"ד רמז, אין כוסף למצותיו, לא נשאר לפני אדוני בלתי אם גוייתנו ואדמתנו, ועכשיו גלינו מארצינו ונתרחקנו מעל אדמתינו ולא נשאר לנו בלתי גוייתנו, לפשוט צווארינו כיצחק ע\"ג מזבח, ונאמר קנה אותנו ואת אדמתינו בלחם. וכאשר רואים שאין להם כסף לוקחים מוניטא דשקרא, שהם הכ\"ב אותיות התורה שהם מטבע של מלך, ופגמו בכולן, ואומרים הוידוי בדרך א\"ב אשמנו בגדנו כו', זהו הפרעון מוניטא דשקרא, וכשרוצים לחזור וללות נותנים להם ג\"כ מוניטא דשקרא, שהם א\"ב של אשמנו מכל עם בושנו כו' גלה כו' יופי אדמתינו כו' צרות רבות כו' תעינו.",[["","","----- מקורות ומראה מקומות -----\n<i>שלח לו רבן גמליאל כו'</i> – ר\"ה כה, א. <i>מכריזין בשופר ל' יום</i> – פדר\"א פמ\"ו. טור או\"ח ריש סי' תקפא. <i>לקדם ברועים ובמקלות</i> – ע\"פ ב\"מ צג, ב. <i>וצרת הכסף גו' ונתתה הכסף גו'</i> – ראה יד, כה-כו. <i>כסף שיש עליו צורה</i> – ב\"מ נד, א. <i>לא נכחד גו' לא נשאר גו' קנה אותנו גו'</i> – ויגש מז, יט.\n----- הערות וציונים -----"]]],[300010398,"שכו\n\n<b>כי</b> תבוא [גו'] ואמרת אשימה עלי מלך [גו'] שום תשים עליך מלך [גו'] מקרב אחיך תשים עליך מלך. ואנחנו רוצים שאתה תהיה מלכנו ודוד עבדך, כמו שהיום בר\"ה כל באי עולם עוברים לפניך כבני מרון כחיילות של בית דוד, לא תוכל לתת עליך איש נכרי, אין אנחנו רוצים במלכות הרשעה וחיילותיהן, והיה כשבתו על כסא ממלכתו, כי ע' כסאות יש להקב\"ה מעין כסא מלכיות שבעולם, ע\"י שישראל הם בארצם, והם כסאו, ע\"כ ותנשא מלכותך ויכון בחסד כסאך ותשב עליו באמת.",[["","","----- מקורות ומראה מקומות -----\n<i>כי תבוא גו' שום תשים גו'</i> – שפטים יז, יד-טו. <i>בר\"ה כל באי עולם כו'</i> – ר\"ה יח, א. <i>לא תוכל גו'</i> – שפטים יז, טו.\n----- הערות וציונים -----"]]],[300010399,"שכז\n\n<b>וכי</b> תהיין לאיש שתי נשים כו' והיה הבן הבכור כו'. רמז בני בכורי ישראל, יכיר לתת לו פי שנים, כהונה ומלכות, אבל באמת איזה ספר כריתות אמכם [גו'] הן בעונותיכם נמכרתם ובפשעכם שולחה אמכם, ואנחנו הבכור בני אהובה.",[["","","----- מקורות ומראה מקומות -----\n<i>וכי תהיין לאיש גו' יכיר לתת גו'</i> – כי תצא כא, טו. <i>בני בכורי ישראל</i> – שמות ד, כב. <i>אי זה ספר גו'</i> – ישעי' נ, א.\n----- הערות וציונים -----"]]],[300010400,"שכח\n\n<b>אלו</b> ב' ימים דר\"ה הם מפני כי דיני ממונות גומרים בו ביום בין לזכות בין לחובה, דיני נפשות גומרין בו ביום לזכות וביום שלאחריו לחובה. ויותר מזה עושה לנו אב הרחמן שתלויין עד יוה\"כ. ועתה בר\"ה יש לנו דיני ממונות ודיני נפשות, מי יעני ומי יעשר מי יחיה ומי ימות כו', ואנחנו עומדין לפני כסא דין ומשפט, היש לנו טענות, היש לנו זכיות וגמילות חסדים. וכמו שבודקין עדים בשבע חקירות, כן נבדוק עצמינו באיזה שבוע באיזה שנה באיזה חדש בכמה בחדש באיזה יום באיזה מקום עברנו עבירות, כי מודה ועוזב ירוחם.\n<b>אם</b> נמצאו דברי העדים מכוונים פותחין בזכות, כן אב הרחמן אע\"פ שנמצאו דברי המסטינים מכוונים אעפ\"כ פתח לנו לזכות, האם ח\"ו מופלא שבב\"ד יפתח לחובה, כמו בחרבן בהמ\"ק שנ' היה אדני כאויב, נצב ימינו – אלו המיימינים, היו – כצר, ואין חולקין על מופלא שבב\"ד, זה אי אפשר, אבל בקשתינו שלא תשמע דברי המסטינים, העדים זוממין הסובבין הכסא, שהרי אמר אחד מן העדים יש לי ללמד עליו זכות, כמו מליצת הס\"ם ביוה\"כ, וכ\"ש חובה, משתקין אותו, שנ' ועד לא יענה בנפש, יגער ד' בשטן.\n<b>היו</b> מאיימן על העדים שלא כדיני ממונות דיני נפשות [כו'] דמו ודם זרעיותיו [כו'], לפיכך נברא אדם יחידי ללמד שכל המאבד נפש א' מישראל כאלו אבד עולם מלא, וכל המקיים נפש אחת מישראל כאלו קיים עולם מלא. ע\"כ נבקש רחמים אחד בעד חבירו, והדין הוא אם מצאו לו זכות פטרוהו, ואם לאו מעבירין את דינו למחר, וכן לנו בדיננו בר\"ה.\n<b>ואף</b> אם נגמר הדין ח\"ו, שנינו במשנה אחד עומד על פתח ב\"ד והסודרין בידו כו', אמר אחד יש לי ללמד עליו זכות הלה מניף בסודרין והסוס רץ ומעמידו, ואפי' אומר יש לי ללמד על עצמי זכות כו'. נחפשה זכות על חברינו, ועל עצמנו, ונבקשה שיצאו מליצי יושר ויניפו בסודרין, הוא הטלית של ציצית, ואפי' אין לנו זכות כ\"א ק\"ש שחרית וערבית ומצות ציצית והסודרין טלית של מצוה, כ\"ש שישראל יש להם זכות גדול מאוד, ישראל עמך אשר בך מאמין, וקבלת עול מלכות שמים, אין לנו אלוה אחר מבלעדיך, אם שכחנו שם אלהינו ונפרוש כפינו כו' הלא אלהים יחקר זאת.",[["","","----- מקורות ומראה מקומות -----\n<i>דיני ממונות כו' דיני נפשות כו'</i> – סנהדרין לב, א. <i>שתלויין עד יוה\"כ</i> – ר\"ה טז, ב. <i>מי יעני ומי יעשר כו'</i> – פיוט ונתנה תוקף. <i>שבודקין עדים כו'</i> – סנהדרין מ, א. <i>מודה ועוזב ירוחם</i> – משלי כח, יג. <i>אם נמצאו דברי העדים כו'</i> – סנהדרין מ, א. <i>הי' אד' גו'</i> – איכה ב, ה. <i>נצב ימינו כצר</i> – איכה ב, ד. <i>ימינו אלו המיימינים</i> – ירושלמי סנהדרין פ\"א ה\"א. תנחומא שמות יח. שם משפטים טו. זו\"ח בראשית יד, ג. <i>ואין חולקין על מופלא שבב\"ד</i> – רש\"י משפטים כג, ב. <i>אמר אחד מן העדים כו'</i> – סנהדרין מ, א. <i>מליצת הס\"ם ביוה\"כ</i> – פדר\"א פמ\"ו. <i>ועד לא יענה בנפש</i> – מסעי לה, ל. <i>יגער ד' בשטן</i> – זכרי' ג, ב. <i>היו מאיימין כו'</i> – סנהדרין לז, א. <i>אם מצאו לו זכות כו'</i> – סנהדרין מ, א. <i>אחד עומד על פתח ב\"ד כו'</i> – סנהדרין מב, ב. <i>זכות כ\"א ק\"ש</i> – ר' סוטה מב, א. <i>אם שכחנו גו' הלא גו'</i> – תהלים מד, כא-כב.\n----- הערות וציונים -----"]]],[300010401,"שכט\n\n<b>בסוף</b> הסליחות והתחינות אומרים מי שענה לכל הצדיקים והחסידים והתמימים והישרים הוא יעננו, רחמנא דעני לעניי ענינו כו'. פירוש, אנחנו אין אנו לא צדיקים ולא חסידים ולא ישרים אלא רחמנא דעני לעניי ענינו לתבירי לבא ענינו.",[["","","----- הערות וציונים -----"]]],[300010402,"של\n\n<b>כה</b> אמר ד' [צבאות] התבוננו, פירוש מהפרש השנים הקודמות, וקראו למקוננות ותבואינה ואל החכמות שלחו ותבואנה ותמהרנה ותשאנה עלינו נהי ותרדנה עינינו דמעה ועפעפינו יזלו מים כי קול נהי נשמע מציון, משכינתא קדישא דאיתקריאת ציון, איך שדדנו בשנו מאד כי עזבנו ארץ, פי' עזבנו ארץ הקדושה ארץ חפץ, ארץ אשר ד' אלהינו דורש אותה תמיד, כי השליכו משכנותינו, את ירושלים ובית המקדש, ואין אנחנו נגד שער השמים שיעלו תפלותינו והמלאכים מלאכי רחמים מליצי יושר היוצאים מן השופר ומן התקיעה ומן השברים ומן התרועה ומן התקיעה, ומן תקיעה שברים תרועה תקיעה, ומן תקיעה שברים תקיעה, [ומן תקיעה] תרועה תקיעה, אפשר שישארו ולא יוכלו לעלות, ומי יעלה אותם, כמ\"ש כי עוף השמים, פי' ע\"י מה יעופף תפלתו השמים, ע\"י מי, יוליך את הקול, פי' האדם צריך להוליך את הקול, וע\"י מה יוליך הקול, ע\"י ובעל הכנפים, פירוש, על כן אמר הכנפים בה' הידיעה שהוא יראה ואהבה, דחילו ורחימו, שנק' כנפיים וגדפין, וז\"ש ובעל הכנפים הידועים יהי' כשיגיד דבר יהי' בדחילו ורחימו. אליהו הנביא המלאך, האופן, שיוצא ג\"כ מן השופר, קשר\"ק<i>[ftnref_1_עב]</i> גי' אליהו הנביא זכור לטוב, אימתי תבוא לבשרינו, אימתי יבוא משיחנו, אימתי יבנה בהמ\"ק ומזבח, אימתי נשב על שלחן אבינו, אוי לבנים שגלו מעל שלחן אביהם.\n<b>או</b> התבוננו, כי יש מסטינים הסובבים הכסא, ובנפש יקיפו עלינו לבלעינו חיים, כמ\"ש ויהי היום, הוא יום ר\"ה, ויבואו בני אלהים, הם בעלי הדין, להתיצב על ה' ויבוא גם השטן, גם לרבות לילית לפרוש השמלה. והנה אז במצרים נאמר וירא ישראל והנה מצרים נוסע אחריהם ויצעקו בני ישראל אל ה', ועתה השטן השונא הגדול נוסע אחרינו עם חיילותיו לבלעינו חיים, למה תשתקו, נתנפל לפני כסא הכבוד ונשאל מה יהא בסופינו. כי ע\"כ יש חרדה ובכיה ערב יוה\"כ לעת ערב שאז שעה אחרונה של עשרת ימי תשובה, וביוה\"כ לית ליה רשותא לאיסטוני, ע\"כ בא השטן בכל כחו לקטרג על כל אדם, ומזלם חזי, ע\"כ בוכים אנשים ונשים וטף. וראוי לעשות כן בכל שעה מעשרת ימי תשובה, דארז\"ל יפה שעה אחת בתשובה ומעש\"ט בעוה\"ז מכל חיי עוה\"ב, כ\"ש וק\"ו כל שעה ושעה מעשי\"ת.\n<b>והנה</b> היום בר\"ה התחלת עשי\"ת, הנה יהי' עתה אותה השעה הטובה, ושעת מזל, לעשות נחת רוח ליוצרנו ולבכות בכיה של שמחה על שזכינו לעמוד לפני כסא כבודו, לפני המלך היושב על כסא רם ונשא ויכון בחסד כסאו וישב עליו באמת, ולשמח להקב\"ה שמחה גדולה, ועי\"ז יומתקו מעלינו כל הדינים, ועי\"ז נעורר אבינו מלכנו תהא השעה הזאת שעת רחמים ועת רצון לפניך. תמכנו יתדותינו בשופר, כמרז\"ל למה אומרים בר\"ה מלכיות זכרונות ושופרות מלכיות שתמליכוני עליכם זכרונות שיעלה זכרונכם לפני לטובה ובמה בשופר. אין אנחנו יודעים הכוונות כ\"א סתם לכוין לקיים מצותיך, שדי עשינו את שלנו, תקיף עשה את שלך, אל תשב עמנו בדין. ע\"כ נקראים תרועה, לשון נוקש אתרעא לפתוח לנו שערי תשובה.\n<b>או</b> יאמר התבוננו, מקושי פרנסות של שנים אלו משנים קדמונים, ע\"כ ותשאנה עלינו דייקא נהי כו', אע\"ג דאמר בזוהר צווחין הב פרנסה, זה הי' בשנים ההם שפרנסה הי' בשופי, משא\"כ עתה שע\"י מניעות פרנסה א\"א לעבדו ית', להחזיק בנינו לתלמוד תורה, ע\"כ תינוקות של בית רבן התפללו עבור (אביכם) [אבותיכם] ואמותיכם שיזכו לגדלכם לתורה לחופה ולמעשים טובים.",[["","","----- מקורות ומראה מקומות -----\n<i>כה אמר ה' גו' וקראו גו' איך גו' כי השליכו גו'</i> – ירמי' ט, טז-יח. <i>משכינתא קדישא דאיתקריאת ציון</i> – זח\"ג לה, א. <i>ארץ חפץ</i> – מלאכי ג, יב. <i>ארץ אשר גו'</i> – עקב יא, יב. <i>כי עוף השמים יוליך גו' ובעל הכנפים יגיד דבר</i> – קהלת י, כ. <i>הכנפים </i>. .<i> יראה ואהבה כו'</i> – שער היחודים לרח\"ו פי\"א [ונעתק משם בשל\"ה סוף מס' יומא]. תניא פ\"מ. <i>אליהו הנביא המלאך</i> – ר' זח\"א קנא, ב. שם רט, א. זו\"ח רות פד, סע\"ג. <i>אוי לבנים כו'</i> – ברכות ג, א. <i>ויהי היום ויבאו גו'</i> – איוב א, ו. <i>היום הוא יום ר\"ה</i> – תרגום לאיוב שם. זח\"ב לב, ב. <i>והנה מצרים נסע גו' ויצעקו גו'</i> – בשלח יד, י. <i>וביוה\"כ לית ליה כו'</i> – יומא כ, א. <i>יפה שעה א' כו'</i> – אבות פ\"ד מי\"ז. <i>ויכון בחסד כו'</i> – ע\"פ ישעי' טז, ה. <i>למה אומרים בר\"ה כו'</i> – ר\"ה טז, א. <i>לשון נוקש אתרעא</i> – זו\"ח חקת נב, רע\"א. <i>בזוהר צווחין כו'</i> – תקו\"ז ת\"ו כב, א.\n----- שולי הגליון -----\n[ftn_1_עב]) <i>נראה שצ\"ל</i>: קר\"ק.\n----- הערות וציונים -----\n<i>קר\"ק גי' אליהו זכור לטוב</i> – ראה אגרות קודש לאדמו\"ר זי\"ע ח\"ג ע' קצו, כי כן הובא במחזורים. ולהעיר מדבש לפי להחיד\"א מערכת א אות טו\"ב."]]],[300010403,"שלא\n\n<b>מי</b> יעורר את אברהם סבא חסידא קדישא הוא ושרה, את הנפש, גוים ונכרים, אשר עשו, להכניסם תחת כנפי השכינה ע\"י לימוד עמהם תורה ועבודת אלהות, ועתה יראה שהיו לוקחין בניו בני בחוניו ושומטין מתחת כנפי השכינה ללמוד עמהם כתב ולשון וספר פסול של עע\"ז, לטמאות הבל פי תשב\"ר, הבל שאין בו חטא. כי עלה מות בחלונינו, באותן הצדיקים שהיו פותחין חלונות הרקיע בתפלתם, בא בארמנותינו, של היכלות עולמות העליונים, להכרית עולל מחוץ, אשר חכמתו הי' בחוץ תרונה, בחורים מרחובות, מבתי כנסיות ובתי מדרשות מקום שהיו מרחיבין את ההלכות, אשר בנינו כנטיעים מגודלים כו' בנותינו כזויות מחוטבות תבנית היכל. אוריד דמעות עדי יהיו כנחל ויגיעו לקברות שני שרי אציליך, משה ואהרן, בהר ההר, ואשאל היש תורה חדשה בכן נשרפו גויליך.",[["","","----- מקורות ומראה מקומות -----\n<i>את הנפש אשר עשו גו'</i> – לך לך יב, ה. <i>גוים כו' להכניסם כו'</i> – רש\"י עה\"פ. בר\"ר לט, יד. <i>הבל כו' שאין בו חטא</i> – שבת קיט, סע\"ב. <i>כי עלה גו' להכרית גו' בחורים גו'</i> – ירמי' ט, כ. <i>חכמתו </i>. .<i> תרונה</i> – ע\"פ משלי א, כ. <i>אשר בנינו כנטיעים גו'</i> – תהלים קמד, יב.\n----- הערות וציונים -----"]]],[300010404,"שלב\n\n<b>רבש\"ע,</b> התפלל אתה בעד בניך, כמרז\"ל הקב\"ה מתפלל, כי אתה רחמן ואתה צדיק, כמ\"ש צדיק ה' בכל דרכיו וחסיד בכל מעשיו, ונא' אם יש עליו מלאך מליץ, הרי טוב, ואם לאו צריך להיות מליץ, אחד מני אלף, הקב\"ה שהוא אחד מני אלף מן עולם, שנקרא אלף חכמה בינה. וז\"ש משרע\"ה האנכי הריתי את [כל] העם הזה, אבל באמת הם בניך.\n<b>נלמוד</b> ממשרע\"ה, מבשר שלנו, גואל צדק, כי מי לנו גדול במעש\"ט ממנו, ואעפ\"כ כשבא עליו מוטות יד התחנן כשנכספה נפשו לעבור את הירדן לבוא לארץ ישראל לטובת ישראל, ופשט את ידיו כעני בפתח לפני כסא הכבוד, ואמר רבש\"ע אין בי שום זכות, תן לי צדקה ומתנת חנם, כמ\"ש [ב]מוטת ידינו כי ימוך אחיך ומטה ידו עמך והחזקת בו, קחה בידינו כי מטה, ונאמר מה אנו מה חסדינו מה צדקותינו, נפשוט ידינו לפני כסא הכבוד ונאמר אין לנו אפי' מנחת עני, אין בנו לא תורה ולא צדקה ולא ג\"ח, כ\"א בידים ריקניות, מהר יקדמונו רחמיך כי דלונו מאד, אבינו מלכנו ידענו כי אין בנו מעשים, צדקה עשה עמנו למען שמך.",[["","","----- מקורות ומראה מקומות -----\n<i>הקב\"ה מתפלל</i> – ברכות ז, א. <i>צדיק ה' גו'</i> – תהלים קמה, יז. <i>אם יש גו' אחד מני אלף</i> – איוב לג, כג. <i>האנכי הריתי גו'</i> – בהעלתך יא, יב. <i>צדקה ומתנת חנם</i> – ספרי ואתחנן פ' נו. <i>כי ימוך גו'</i> – בהר כה, לה. <i>מה אנו כו'</i> – תפלת רבש\"ע בשחרית מתדב\"א ספכ\"א, ובסוף תפלת נעילה. <i>מהר יקדמונו גו'</i> – תהלים עט, ח.\n----- הערות וציונים -----\n<i>משרע\"ה </i>. .<i> לבוא לא\"י לטובת ישראל</i> – להעיר ממג\"ע פ' ואתחנן, ובאורך באופנים אשר הובאו בילק\"ר פ' ואתחנן."]]],[300010405,"שלג\n\n<b>ע\"כ</b> פותחין עם תינוק ספר ויקרא, כי כל העוסק בתורת עולה כאלו הקריב עולה, נמצא ועתה ישראל כולם ממלכת כהנים, כהני היכא אינון.",[["","","----- מקורות ומראה מקומות -----\n<i>פותחין עם תינוק כו'</i> – תנחומא צו יד. ויק\"ר ז, ג. <i>כל העוסק כו'</i> – מנחות קי, א.\n----- הערות וציונים -----"]]],[300010406,"שלד\n\n<b>ולאשה</b> אמר הרבה ארבה עצבונך והרונך, שיקויים כי חלה גם ילדה ציון את בניה, בעצב תלדי בנים, כמ\"ש ויסעו מבית אל, פי' מבית אל דייקא, מבית המקדש שנחרב. ויהי עוד כברת ארץ לבוא אפרתה, פרש\"י לשון כביר ריבוי מהלך רב, ותלד רחל, השכינה שנקרא בד\"מ רחל רצונה לילד, ותקש בלדתה, שיקוים כי חלה גם ילדה ציון את בניה, כי בגלות בבל היו ע' שנה, נגד ע' קולות שבמזמור יענך ה' ביום צרה, ואח\"כ והמליטה זכר. ועתה כה אמר ה' קול ברמה נשמע, כמה מאות קולות, נהי בכי תמרורים רחל מבכה, לא קאמר בוכה אלא מבכה כל העליונים על בניה, ה' ממרום ישאג [גו'] שאוג ישאג, מתתא לעילא ומעילא לתתא.",[["","","----- מקורות ומראה מקומות -----\n<i>ולאשה אמר גו' בעצב גו'</i> – בראשית ג, טז. <i>כי חלה גו'</i> – ישעי' סו, ח. <i>ויסעו גו' ויהי עוד גו' ותלד רחל גו'</i> – וישלח לה, טז. <i>השכינה שנקרא בד\"מ רחל</i> – זח\"ב כ, ב. זח\"ג רמד, א. <i>בגלות בבל היו ע' שנה</i> – ירמי' כט, י. מגילה יא, ב. <i>ע' קולות שבמזמור יענך</i> – זח\"ב קיט, ב. זח\"ג רמט, ב. <i>כה אמר ה' גו' נהי גו' על בניה</i> – ירמי' לא, יד. <i>ה' ממרום ישאג גו'</i> – ירמי' כה, ל.\n----- הערות וציונים -----"]]],[300010407,"שלה\n\n<b>שאו</b> נס ציונה, לשלוח שם השפלות, העיזו אל תעמודו כי רעה אנכי מביא מצפון ושבר גדול עלה אריה, נסתלק מיכאל שנקרא אריה ממליצתו על ישראל, מסובכו, באיל בסבך בקרניו, כמ\"ש ובעת ההיא יעמוד מיכאל העומד על בני עמך והיתה עת צרה אשר לא נהייתה מהיות גוי עד עת ההיא ובעת ההיא ימלט עמך כל הנמצא כתוב בספר. וקשה לרש\"י, משום דיעמוד מיכאל יהיה עת צרה בתמיה. ע\"כ פרש\"י, ישתתק כאלם שיראה הקב\"ה דן בעצמו ואומר האיך אאבד אומה גדולה כזו בשביל ישראל, והיתה עת צרה בפמליא של מעלה וקטגוריא בת\"ח בזוזי ובזוזי דבזוזי. למה ישתוק, הלא נאמר את ה' האמרת היום וה' האמירך שלא יחליפם באומה אחרת, כמו בימי יחזקאל כשרצו הזקנים להחליפו באלוה אחר השיב הקב\"ה ביד חזקה אמלוך עליכם, כן למה ירצה להחליפנו באומה אחרת, יסתכל ויראה ההפרש שבין ישראל הקדושים בכל מיני קדושות לבין או\"ה.\n<b>ואם</b> הפטרון והסניגור משתתק, המנהג שהרשות ביד בעל דין ללחוש לו זכיותיו. איזה הם הזכיות אשר נלחוש לו, תפלות ברורות, תלמוד תורות ברורות, תשובות ברורות, צדקות זכות וברורות, אין לנו זכות כ\"א מן הקול קול יעקב, קול התורה מתנוקות של בית רבן, הבל שאין בו חטא.\n<b>תשב\"ר</b> בכו בכיה גדולה, והתפללו בעד (אביכם) [אבותיכם] ואמותיכם המגדלכם לתורה ולמעש\"ט, [ואע\"פ שאיני כדאי להתפלל על עצמי, כ\"ש על אחרים, כי איני אומר שאני הטוב ח\"ו, ואפי' הטוב אין מי יקרא בצדק, איש טוב נמשל כחדק, כשמפשפשים במעשיו]<i>[ftnref_1_עג]</i>, בקשו רחמים בעד הטובים שבכם, וזקינים בעלי חשיבות ות\"ח, שלא יהיו נתפסים בעון הדור, ונגידים אשר מהם מתפרנסים רבים שלא יענו ולא יעדרו ח\"ו.\n<b>אב</b> מוליך בניו בימים האלה לבית הכנסת, אפשר שמוליכו כמו אברהם אבינו את יצחק בנו לעקדה, שיהיה נתפס בעונו, ע\"כ עשו תשובה גדולה והתפללו בעד בניכם. בקשו לש\"ץ שיחוס עליכם כי הבל פיכם אין בו חטא, כ\"ש דמעותיכם, אע\"פ שיש במלחמה גבור, אעפ\"כ צריכים העם לעזור לו מכל הצדדים, כן עשו עזר להש\"ץ מכל הצדדים ממזרח וממערב מצפון ומים.",[["","","----- מקורות ומראה מקומות -----\n<i>שאו גו' העיזו גו' עלה אריה מסבכו</i> – ירמי' ד, ו-ז. <i>מיכאל שנקרא אריה</i> – זח\"ג קנד, א. שם ריז, רע\"א. <i>מליצתו על ישראל</i> – פס\"ר ס\"פ שובה. זח\"ב רנד, א. <i>ובעת ההיא יעמוד מיכאל העמד גו'</i> – דניאל יב, א. <i>וקטגוריא בת\"ח כו'</i> – כתובות קיב, ב (הובא ברש\"י לדניאל שם). <i>את ה' האמרת גו' וה' האמירך גו'</i> – תבוא כו, יז-יח. <i>שלא יחליפם כו'</i> – גיטין נז, ב. <i>כמו בימי יחזקאל כו'</i> – תנחומא נצבים ג. <i>ביד חזקה אמלוך גו'</i> – יחזקאל כ, לג. <i>הקול קול יעקב</i> – תולדות כז, כב. <i>קול התורה</i> – בר\"ר סה, כ. <i>תשב\"ר הבל שאין בו חטא</i> – שבת קיט, סע\"ב. <i>אין מי גו'</i> – ע\"פ ישעי' נט, ד. <i>איש טוב כו'</i> – ע\"פ מיכה ז, ד. <i>נתפסים בעון הדור</i> – ע\"פ שבת לג, ב.\n----- שולי הגליון -----\n[ftn_1_עג]) <i>אע\"פ שכן הוא סדר הדברים בכל הדפוסים שראיתי</i>,<i> אינו מובן</i>.<i> ואולי קטע זה ששמתי בחצאי רבוע צ\"ל בשלהי סימן זה</i>,<i> אחרי </i>\"כ\"ש דמעותיכם\".\n----- הערות וציונים -----"]]],[300010408,"שלו-א\n\n<b>תקעו</b> בחדש שופר בכסא, אז מתכסית הלבנה, ושכינתא קדישא הרמוזה כנגדה, כי חק לישראל הוא, כשאז מקבלה חק מזונות בשביל ישראל, הוא משפט ויסורין לאלהי יעקב, כי עתה בגלות תחלה מקבלים שרי או\"ה ואח\"כ ישראל.",[["","","----- מקורות ומראה מקומות -----\n<i>תקעו בחדש גו' כי חק גו'</i> – תהלים פא, ד-ה. <i>אז מתכסית הלבנה</i> – ר\"ה ח, סע\"א. <i>ושכינתא קדישא הרמוזה כנגדה</i> – זח\"ג רפא, סע\"ב. <i>בגלות מקבלים כו'</i> – זח\"ב קנב, ב.\n----- הערות וציונים -----\n<i>עתה בגלות תחלה כו'</i> – ראה זח\"ג רלה, א."]]],[300010409,"שלו-ב\n\n<b>כל</b> מי שלא נבנה ביהמ\"ק בימיו כאלו נחרב בימיו, א\"כ בשנה שנחרב בהמ\"ק איך היו במרירות בר\"ה ויוה\"כ, וכן אנחנו שלא נבנה בהמ\"ק בימינו.",[["","","----- מקורות ומראה מקומות -----\n<i>כל מי שלא נבנה כו'</i> – ירושלמי יומא פ\"א ה\"א.\n----- הערות וציונים -----"]]],[300010410,"שלו-ג\n\n<b>ע\"כ</b> יש בכיה והתעוררות גדול לכל אדם בעי\"כ לעת ערב כי אז בא השטן לקטרג על כל אחד בכח גדול, מפני שהיא שעה אחרונה של עשי\"ת. דביוה\"כ לית ליה רשותא לאיסטוני, ע\"כ נתודה ונפייס התורה שמרדנו בה, כי מודה ועוזב ירוחם.\n<b>כי</b> ע\"כ פתח הקב\"ה התורה בבי\"ת, ולא באל\"ף שהוא לשון ארור, וב' הוא לשון ברכה, נתודה כמה ברכות לא ברכנו בכוונה וגזלנו אבינו שבשמם, כי הנהנה מעולם הזה בלא ברכה מועל וגוזל, ע\"כ פתח התורה בראשית ברא אלהים את השמים ואת הארץ, בראשית הוא לשון ברכה שעיקרו מלך העולם, שמים וארץ הוא עולם.",[["","","----- מקורות ומראה מקומות -----\n<i>דביוה\"כ לית כו'</i> – יומא כ, א. <i>מודה ועוזב ירוחם</i> – משלי כח, יג. <i>פתח הקב\"ה התורה בבי\"ת כו'</i> – אליהו רבה ספל\"א. ספר הבהיר ג. בר\"ר א, י. <i>הנהנה מעוה\"ז כו'</i> – ברכות לה, סע\"א ואילך. <i>בראשית גו'</i> – בראשית א, א. <i>ברכה שעיקרו מלך העולם</i> – ברכות מ, ב. שם תוס' ד\"ה אמר אביי.\n----- הערות וציונים -----\n<i>ע\"כ יש בכיה כו'</i> – הובא לעיל סי' של."]]],[300010411,"שלו-ד\n\n<b>אם</b> יש לך ח\"ו גז\"ד שיש עמו שבועה אנחנו מתירין לך, כמרז\"ל שהתיר לו נדרו.",[["","","----- מקורות ומראה מקומות -----\n<i>שהתיר לו נדרו</i> – ר' ב\"ב עד, א ובשימ\"ק שם.\n----- הערות וציונים -----\n<i>גז\"ד שיש עמו שבועה</i> – ראה ר\"ה יח, א.\n<i>אנחנו מתירין לך כו'</i> – להעיר מביאור כל נדרי בלקו\"ת לאדה\"ז פ' מטות פה, סע\"א. אוה\"ת להצ\"צ פ' מטות ע' א'רפט."]]],[300010412,"שלז\n\n<b>במשנה</b> חציו קשר בסלע וחציו בין קרניו, שלא יכוף השעיר ראשו ולא ידע אם הלבין הלשון ויהיו כל ישראל עצבין. הנה עתה שיש ספק אם הלבין, הנה אנחנו בחשך ועצבות, מי יודע למי חתך הדין ראשו או בניו או פרנסתו, מעכבי פתקין עד אחתימו, יבקשו רחמים, כמה חרב חדה מונחת על צואריהם ואעפ\"כ לא ימנעו עצמן מן הרחמים.",[["","","----- מקורות ומראה מקומות -----\n<i>במשנה חציו קשר כו'</i> – יומא סז, א. <i>מעכבי פתקין כו'</i> – זח\"א רכ, א. זח\"ג ר\"מ צט, א-ב. <i>חרב חדה כו'</i> – ברכות י, סע\"ב.\n----- הערות וציונים -----"]]],[300010413,"שלח\n\n<b>כתיב</b> כי ימוך אחיך ומטה ידו [עמך] והחזקת בו. קחה בידינו כי מטה, אף אם היינו חוטאים הלא מצאנו כי אתה דן את האדם באשר הוא שם, ועתה אני שב ומתודה, אם און פעלתי לא אוסיף.",[["","","----- מקורות ומראה מקומות -----\n<i>כי ימוך גו'</i> – בהר כה, לה. <i>דן את האדם כו'</i> – ר\"ה טז, ב. <i>אם עול גו'</i> – איוב לד, לב.\n----- הערות וציונים -----"]]],[300010414,"שלט-א\n\n<b>רבש\"ע</b> אתה אמרת ליונה אתה חסת על הקיקיון אשר לא עמלת בו ולא גדלתו שבן לילה היה ובן לילה אבד ואני לא אחוס על ננוה העיר הגדולה אשר יש בה הרבה משתים עשרה רבוא אדם אשר לא ידע בין ימינו לשמאלו ובהמה רבה, למה לא תחוס ותרחם עלינו שיש בנו דעת כאדם.",[["","","----- מקורות ומראה מקומות -----\n<i>אתה חסת גו' ואני גו'</i> – יונה ד, י-יא.\n----- הערות וציונים -----"]]],[300010415,"שלט-ב\n\n<b>נאמר</b> באברהם אבינו והאמין בה' ויחשבה לו צדקה, ועתה חלפו כמה זמני הגאולה ואנחנו מאמינים.",[["","","----- מקורות ומראה מקומות -----\n<i>והאמין בה' גו'</i> – לך לך טו, ו. <i>חלפו כמה זמני הגאולה</i> – תקוזו\"ח צה, ב.\n----- הערות וציונים -----\nע\"פ פרש\"י עה\"פ (וראה מדרש משלי פ\"ו ופי\"ד), ודלא כפי' הרמב\"ן (ע\"פ זח\"ג קמח, א)."]]],[300010416,"שמ\n\n<b>כתיב</b> כי תקנה עבד עברי שש שנים יעבוד ובשביעית יצא, ובמכרוהו ב\"ד בגניבתו הכתוב מדבר. ואף אנחנו אם נמכרנו לעבדים, כלו כמה שמיטין ולא יצאנו לחירות. ואם אדוניו יתן לו אשה כו' ואם אמור יאמר העבד אהבתי את אדוני ואת אשתי, והנה כן הס\"ם נתן לנו, ונשים משלו בנו, לילית הרשעה בחטא הוצאת שז\"ל, וכמ\"ש כי ינצו אנשים [גו'] וקרבה אשת האחד [גו'] והחזיקה במבושיו כו', האם אנחנו אומרים אהבתי את אדוני ואת אשתי ח\"ו, אין אנחנו אוהבים את הצר הצורר הזה ואת השפחה בישא, אנחנו אוהבים אותך כמ\"ש ואהבת את ה' אלהיך בכל לבבך ובכל נפשך ובכל מאדך.",[["","","----- מקורות ומראה מקומות -----\n<i>כי תקנה גו'</i> – משפטים כא, ב. <i>ובמכרוהו בי\"ד כו'</i> – מכילתא ר\"פ משפטים. קידושין יד, ב. <i>אם אדוניו גו' ואם אמר גו'</i> – משפטים כא, ד-ה. <i>ונשים משלו בנו</i> – ע\"פ ישעי' ג, יב. ראה זח\"ג יט, ב. <i>לילית כו'</i> – זח\"א יט, ב וד\"א שם. <i>כי ינצו גו'</i> – כי תצא כה, יא. <i>ואהבת גו'</i> – ואתחנן ו, ה.\n----- הערות וציונים -----"]]],[300010417,"שמא-א\n\n<b>כה</b> אמר ה' התבוננו וקראו כו' ותרדנה עינינו דמעה. דאיתא בתיקונים אית היכלין דנגונא דלא מתפתחין אלא בנגונא כד\"א ויהי כנגן המנגן, ואית היכלא דדמעה דלא מתפתחא אלא בדמעה כד\"א ותפתח ותראהו והנה נער בוכה ותחמול עליו [גו']. ותפלה בדמעה הוא מרוצה להקב\"ה, כמ\"ש בזוהר עד דלא יכול למרחש בשפוותי'. והנה כמו בחורבן בהמ\"ק דא\"ל קב\"ה לירמיה לך וקרא לאבות ומשה היודעים לבכות, כן אנחנו נלמוד.\n<b>כמרז\"ל</b> לא הי' דוד ראוי לחטוא אלא שאם יחטא יחיד כו'. והנה כמו דוד, אע\"פ שארז\"ל כל האומר דוד חטא טועה כו', אעפ\"כ התענה כ\"ב שנה, ובכל יום אמר אפר כלחם אכלתי כו' וכוס דמעות ושקויי בבכי מסכתי. ואנחנו העוברים לפני כסא הכבוד היום כבני מרון, שארז\"ל כחיילות של בית דוד, נלמוד מאדוננו דוד לבכות ולשוב מחטאים. וכן רבים, ילמדו מעושי העגל דור המדבר שהם רבים, ועשה אהרן להשיב רבים מהעון קשר ידו בברזל וסיבב מחנה ישראל וצעק ובכה עד שחזרו כולם בתשובה ובכו עמו כמ\"ש במדרש כו', וכן אנחנו נהי' מקיש אתרעא דדמעה לשוב מחטאינו.",[["","","----- מקורות ומראה מקומות -----\n<i>כה אמר ה' גו'</i> – ירמי' ט, טז-יז. <i>דאיתא בתיקונים</i> – תי\"א כו, ב. <i>ויהי כנגן גו'</i> – מ\"ב ג, טו. <i>ותפתח ותראהו גו'</i> – שמות ב, ו. <i>כמ\"ש בזוהר כו'</i> – זח\"ב כ, א. <i>דא\"ל קב\"ה לירמי' כו'</i> – איכ\"ר פתיחתא כד. <i>לא הי' דוד כו'</i> – ע\"ז ד, סע\"ב. <i>כל האומר דוד כו'</i> – שבת נו, א. <i>התענה כ\"ב שנה כו'</i> – אליהו רבה פ\"ב. <i>אפר כלחם גו' ושקוי גו'</i> – תהלים קב, י. <i>העוברים לפני כו' כחיילות כו'</i> – ר\"ה יח, א. <i>וכן רבים ילמדו כו'</i> – ע\"ז ד, סע\"ב ואילך. <i>ועשה אהרן להשיב כו' כמ\"ש במדרש</i> – אליהו רבה פי\"ג.\n----- הערות וציונים -----"]]],[300010418,"שמא-ב\n\n<b>ידי</b> נשים רחמניות בשלו ילדיהן, בשלו בגדלות, כד\"א ואעבור עליך ואראך והנה עתך עת דודים כו' ואת ערום ועריה.",[["","","----- מקורות ומראה מקומות -----\n<b>?</b>\n<i>ידי נשים גו'</i> – איכה ד, י. <i>ואעבור עליך גו'</i> – יחזקאל טז, ח. <i>ואת ערם גו'</i> – יחזקאל טז, ז.\n----- הערות וציונים -----\n<i>בשלו הגדלות כד\"א ואעבור גו'</i> – להעיר ממדל\"י סי' קכד (קלג) וריב (רכא)."]]],[300010419,"שמב\n\n<b>&lt;מהבעש\"ט,</b> איכה ישבה בדד&gt;. <span data-k=\"sm\">[דכתבתי בשם </span><i>מורי</i><span data-k=\"sm\">]</span> כי השכינה נקרא &lt;אשא תכלא&gt; <span data-k=\"sm\">[אש אוכלה]</span> וצריך לחברה לאשא חיוורא <span data-k=\"sm\">[וכו' יעו\"ש]</span>. &lt;וז\"ש&gt; <span data-k=\"sm\">[ובזה יובן איכה ישבה בדד העיר, ר\"ל]</span> איך ה' ישבה בדד השכינה עיר דוד ה' אחרונה, שלא היה &lt;ביחוד&gt; <span data-k=\"sm\">[בחיבור]</span> עם דודה, עם יה\"ו, <span data-k=\"sm\">[מה שהיתה תחלה רבתי עם, ר\"ל רבתי בדיעות לחבר ע\"י הדעת בין הקצוות, ועתה היתה כאלמנה, גלמודה מבעלה, וזה גרם מה שהיו רבתי בגוים שרתי במדינות, כשידעו ליחד קוב\"ה ושכינתיה שהיה רבתי בדיעות, ומעתה שנשארה בדד גרם להם שהיו למס]</span>.\n<b>בכה</b> תבכה בלילה, ר\"ל שנשארה בלילה בלי חיבור היום, <span data-k=\"sm\">[זה גרם בכיה כפולה בגשמי וברוחני, למעלה ולמטה, כאמור]</span>, עד לבסוף השיבנו ה' אליך ונשובה <span data-k=\"sm\">[חדש ימינו כקדם]</span> &lt;נשוב ה', חדש ימינו כקדם&gt; <span data-k=\"sm\">[ר\"ל כאשר יהיה ה' אחרונה בחיבור ג' אותיות ראשונות, ומה שהיה איך ה' ישבה בדד ועתה השיבנו הוי\"ה על ידי שנשובה, אח\"כ יחדש ימינו כקדם]</span>. והבן והשם יכפר.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י דברים קסו</b>,<b> סע</b>\"<b>ב (תריב</b>,<b> א)</b>\n<i>איכה ישבה גו' היתה למס</i> – איכה א, א. <i>השכינה נק' כו' </i>– זח\"ג לג, א. שם לד, א. <i>אש אוכלה</i> – ואתחנן ד, כד. <i>וצריך לחברה לאשא חיוורא</i> – זח\"א נא, ע\"א ושם ע\"ב. <i>איכה </i>. .<i> איך ה' ישבה בדד</i> – תקו\"ז תס\"ט קיא, ב. <i>השכינה עיר דוד ה' אחרונה</i> – ר' זח\"א עד, ב. ושם רנו, ב ורנז, א. <i>עם יה\"ו</i> – זח\"א נא, א. <i>רבתי בדיעות</i> – איכה רבה א, ד. <i>בכה תבכה גו'</i> – איכה א, ב. <i>השיבנו ה' גו'</i> – איכה ה, כא.\n----- הערות וציונים -----\nראה כתונת פסים בהעלתך לה, א בשם הבעש\"ט כי השכינה נקרא אש אכלה המכלה הכל כשאינה ביחוד למעלה עם אש חוורא (ראה זח\"א נא, א-ב; זח\"ג קי, ב ומ\"מ ואוה\"ח שם. ושם ר\"מ קעה, סע\"א). ועיין מה שהבאתי לעיל בהערות לסי' קלה ד\"ה ענין רומח.\n<i>ר\"ל איך ה'</i> – דרש איכה נוטריקון לאיך ה' כמ\"ש בתקו\"ז שם. ולהעיר עוד מתקו\"ז תי\"ט מב, סע\"א ושם תס\"ב צד, סע\"א.\n<i>רבתי עם ר\"ל רבתי בדיעות</i> – באיכ\"ר שם נדרש על רבתי בגוים. ולהעיר שבמהדורת רש\"ב: רבתי עם רבתי בחכמה . . רבתי בגויים אלא רבתי בדיעות."]]],[300010420,"שמג\n\n<b>&lt;מהבעש\"ט.</b> ויהי ערב ויהי בוקר&gt; והענין <span data-k=\"sm\">[דשמעתי </span><i>ממורי</i><span data-k=\"sm\"> זלה\"ה]</span> &lt;כי&gt; יתרון האור נמשך מן החושך וכו' ודפח\"ח. <span data-k=\"sm\">[ויש בכל זה יתרון האור הנמשך מן חשך של עצמו או מחשך של זולתו. וזה ביאור פסוק ויהי ערב ויהי בוקר יום אחד וכו']</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י דברים קסו</b>,<b> ג (תריב</b>,<b> ב)</b>\n<i>ויהי ערב גו'</i> – בראשית א, ה. <i>יתרון האור גו'</i> – קהלת ב, יג.\n----- הערות וציונים -----\nראה לעיל סי' קפח ורמז."]]],[300010421,"שדמ\n\n<b>הנה</b> אדונים קשים שלנו הם עלינו בכעס, אם גם אתה תהיה עלינו ח\"ו בכעס אם כן מי יקרבינו, כמרז\"ל ע\"פ ודבר ה' אל משה פנים אל פנים ושב אל המחנה, ומדרשו דבר ה' אל משה שישוב אל המחנה, א\"ל אני בכעס ואתה בכעס א\"כ מי יקרבם.",[["","","----- מקורות ומראה מקומות -----\n<i>ודבר ה' אל משה גו'</i> – כי תשא לג, יא. <i>ומדרשו כו'</i> – רש\"י עה\"פ ע\"פ ברכות סג, ב. ותנחומא כי תשא כז.\n----- הערות וציונים -----"]]],[300010422,"שמה\n\n<b>איה</b> שמחת בית השואבה, אמר רשב\"ג<i>[ftnref_1_עד]</i> כו' לא ראינו שינה בעינינו, ואיך אנחנו ישינים כמה מאות שנים, עורו ישינים כו'.",[["","","----- מקורות ומראה מקומות -----\n<i>אמרו על רשב\"ג כו'</i> – סוכה נג, א.\n----- שולי הגליון -----\n[ftn_1_עד]) <i>בגמרא שם</i>: אמרו על רשב\"ג כשהי' שמח שמחת בית השואבה כו' אמר ר' יהושע בן חנניה כשהיינו שמחים שמחת ביה\"ש לא ראינו כו'.\n----- הערות וציונים -----"]]],[300010423,"שמו\n\n<b>נאמר</b> במנחת עני אשה ריח ניחוח, אין בנו לא תורה ולא צדקה ולא גמילות חסדים, אלא בידים ריקניות כעני בפתח דופק, הלא בצערינו השכינה מצטערת, אר\"מ בזמן שאדם מצטער שכינה מה הלשון אומרת קלני מראשי [כו'] אם כן המקום מצטער על דמם של רשעים ק\"ו על דמם של צדיקים.",[["","","----- מקורות ומראה מקומות -----\n<i>נאמר במנחת עני כו'</i> – ויקרא ב, א-ב ורש\"י שם. מנחות קי, א. <i>אר\"מ בזמן כו'</i> – סנהדרין מו, א.\n----- הערות וציונים -----"]]],[300010424,"שמז<i>[ftnref_1_עה]</i>\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; כל המענג את השבת, ר\"ל ש' בת כו', ע\"י תענוג שבת שיש במלכות הנק' בת וקשרה אל ג' אבהן הנק' ש'. וז\"ש אז תתענג על ה', נותנין לו נחלת יעקב בחיר שבאבות, <span data-k=\"sm\">[שהוא בגמר]</span> ש' משולש.",[["","","----- מקורות ומראה מקומות -----\n<b>[קטעים מסי</b>'<b> ערב דלעיל וש</b>\"<b>נ]</b>\n<i>כל המענג כו'</i> – שבת קיח, א-ב. <i>ש' בת</i> – זח\"א כג, ב. זח\"ב רד, א. <i>במלכות הנק' בת</i> – זח\"ג רנו, ב. תקו\"ז ת\"ע קלג, ב. ראה זח\"ב פה, ב. <i>ג' אבהן הנק' ש'</i> – זח\"א ב, ב. שם כג סע\"ב. זח\"ב רד, א. <i>אז תתענג גו'</i> – ישעי' נח, יד. <i>יעקב בחיר שבאבות</i> – בר\"ר עו, א.\n----- שולי הגליון -----\n[ftn_1_עה]) <i>זהו קטע מסי' ערב לעיל</i>,<i> עיי\"ש</i>.\n----- הערות וציונים -----\nזהו קטע מסי' ערב דלעיל, עיי\"ש."]]],[300010425,"שמח\n\n<b>והענין</b> פי' הידיעה והשארית חפשית הבחירה, ע\"פ אני ה' לא שניתי.\n<b>דיש</b> לתרץ הקושיא שהקשו כל הראשונים, וז\"ל, למה לא ברא הקב\"ה את העולם קודם ה' אלפים שנה, דהרי פעולה טובה מהעדר, ולמה נשתנה רצונו מלא רוצה אל רוצה בעת שברא לבד לא קודם, דהרי אינו ית' בעל שינויים. והתירוץ על זה, דהוא ית' אינו דומה לפועל בשר ודם, שהחכמה שיש לו עתה לא היה לו מקודם, אלא חכמתו היא קנינית, וגם הוא בעל חסרון. מלה\"ד, דמפני דצריך מקום לדור, ע\"כ כשקנה חכמה לבנות לו בית תיכף בונה לעצמו בית. אבל הוא ית' חכמתו עצמיית לא קנינית, וגם אינו בעל חסרון, ויש לומר דהרצון לברוא העולם לא נתחדש לו זה הרצון בעת בריאתו העולם, אלא כמו שהוא קדמון כן הי' רצונו, ומקדמת דנא הי' ברצונו לברוא העולם בעת שברא אותו, לא קודם לכן, ואח\"כ כשברא העולם נברא בעתו ובזמנו כמו שהיה ברצונו הקדום לברוא אותו בעת הזאת דווקא, א\"כ לא היה שינוי רצון.\n<b>והראיה,</b> דהרי עולם שכולו שבת שיהיה לעתיד לבא, וצדיקים יושבים ועטרותיהם כו', ונשגב ה' לבדו ביום ההוא, ודאי מעלתו גדולה מן מעלת העולם כשהוא עתה, ופעולה טובה כזו גם כן טובה מהעדר, ולמה לא הקדימו הקב\"ה אלא שיבוא בעתו ובזמנו, כמו שדרך השבת לבוא דוקא אחר ששת ימי החול. וכן הוא בענין בריאתו של עולם, דאע\"פ שידע דפעולה טובה מהעדר, אעפ\"כ רצונו היה מנגד לידיעה, כי מקדמת דנא היה רצונו לברוא העולם דוקא בעת הזאת שיהיו ימי המעשה, וקודם לכן היה בדרך משל עולם שכולו שבת ונמשך אחר הרצון. ולא תקשה הלא פעולה טובה מהעדר, כי הקב\"ה אינו בעל חסרון שיצטרך הפעולה ההיא לטובתו. וז\"ש את הכל עשה יפה בעתו גם את העולם. וז\"ס עמוק והמשכיל יבין.\n<b>והנה</b> כן ברא הקב\"ה את העולם, דלא יקשה אדם איך שייך שכר לצדיק ועונש לרשע הלא יודע א-ל ויש דיעה בעליון, שצפה והביט עד סוף כל הדורות וידע שזה יהיה צדיק, א\"כ מוכרח הוא להיותו צדיק ולא יתכן לו שכר, וגם ידע שזה יהיה רשע ולא יתכן לענוש כיון שלא היה יכול לשנות ידיעתו ית\"ש. וי\"ל, אף שיש לו ית' ידיעה, מ\"מ הרצון שלו ית' שייטיבו מעשיהם, כי ע\"כ צוה לנו כל התורה ומצותיה, והרצון בעצמו מנגד לידיעה מתחלת המחשבה, ויוכל אדם להמשך אחר רצון הש\"י וציוויו ולא אחר הידיעה, שהרצון יכריח הידיעה כיון שאין חפץ לרצון ה' בידיעה זו ובמעשה זה, והידיעה היא שלא לרצון. ואם ירצה אדם ייטיב מעשיו כמו שהוא הרצון של הש\"י, ולא יוריד וישלשל לעצמו הידיעה, כי הידיעה של רע הוא הרע בעצם שהיא הסט\"א, שנבראת לנסיון הצדיקים, כמ\"ש כי מנסה ה' אלקיכם אתכם, כי העוה\"ז הוא עולם הנסיון, שהנשמה נשלחת שם להיותה בנסיון בעוה\"ז דאם יעשה החטא הרי יטה אחר הידיעה, ואם לא יעשה הרי יטה אחר הרצון והציווי המנגד לידיעה, שע\"ז נאמר אשה ריח נחוח לה', נחת רוח לפני שאמרתי ונעשה רצוני, והבן היטב.",[["","","----- מקורות ומראה מקומות -----\n<b>?</b>\n<i>אני ה' לא שניתי</i> – מלאכי ג, ו. <i>הקושיא כו' הראשונים</i> – רס\"ג, אמו\"ד מ\"א פ\"ד. מו\"נ ח\"ב פי\"ג ופ\"ל. ע\"ח ש\"א ענף א. שומר אמונים, ח\"ב סי' יד ואילך. <i>דהוא ית' אינו דומה כו' עצמיית לא קנינית</i> – רמב\"ם הל' יסוה\"ת פ\"ב ה\"י. <i>עולם שכולו שבת כו'</i> – תמיד פ\"ז מ\"ד. <i>וצדיקים יושבים כו'</i> – ברכות יז, א. <i>ונשגב ה' גו'</i> – ישעי' ב, יא. <i>את הכל עשה גו'</i> – קהלת ג, יא. <i>דלא יקשה אדם איך כו'</i> – רמב\"ם הל' תשובה פ\"ה. <i>יודע א</i>-<i>ל ויש כו'</i> – ע\"פ תהלים עג, יא. <i>כי מנסה ה' גו'</i> – ראה יג, ד. <i>אשה ריח גו' נחת רוח לפני כו'</i> – ספרי שלח פיס' קז.\n----- הערות וציונים -----\n<i>למה לא ברא כו'</i> – הקושיא הובאה ג\"כ בקונ' פירוש עשר ספירות לר\"ע מגירונה סי' ח, וביאורו בס' דרך אמונה לרמא\"ג פ\"ז. של\"ה, תולדות אדם בית ה', בהג' ד\"ה מצאתי שאלה ששאל הרר\"י. עיין בבפ\"י בראשית יז, א (פח, א) [בהמשך להמובא לעיל סי' יא], ולקו\"י יד, סע\"א (סי' קמה), מש\"כ בזה. ולהעיר מהוספות למדל\"י-או\"ת סי' נב, ומה שהאריך בזה בלקו\"ש ח\"י ע' 176 ואילך (במילואו באג\"ק ח\"ב ע' רמד).\n<i>כמו שהוא קדמון כן היה רצונו כו'</i> – דהוא ורצונו אחד (תניא פ\"מ בהג' ד\"ה ושם מאיר). וראה דרך מצותיך להצ\"צ, שרש מצות התפלה פ' ז\"ך. ועיין של\"ה, תולדות אדם בית ה', בד\"ה הרי שלש עליות (ד, א) בענין הו\"א ושמ\"ו עצם אחד, שמ\"ו בגי' רצון כו', ומה שהביא שם מפ\"ר להרמ\"ק ומפלח הרמון להרמ\"ע.\n<i>איך שייך כו'</i> – רג\"כ רמב\"ם, שמנה פרקים פ\"ח ומו\"נ ח\"ג פ' כ-כא. ועוד. ועיין ביאור ענין ידיעה ובחירה בפלח הרמון להרמ\"ע שי\"ח פ\"א."]]],[300010426,"שמט-א\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; במקום גילה שם תהא רעדה. &lt;פי' מוהר\"י בעש\"ט זלה\"ה&gt; <span data-k=\"sm\">[להבין זה, נראה לי דשמעתי </span><i>ממורי</i><span data-k=\"sm\"> זלה\"ה]</span> כי בגשמי מקום שיש יראה אין גילה ובמקום גילה אין יראה, כ\"א בעבודת ה' נמצא במקום יראה יש אהבה &lt;וגילה&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ס</b>\"<b>פ בחקותי קטז</b>,<b> ג (תלה</b>,<b> ב)</b>\n<i>במקום גילה כו'</i> – ברכות ל, סע\"ב.\n----- הערות וציונים -----\nראה לעיל סי' לו."]]],[300010427,"שמט-ב\n\n<b>וזהו</b> גם בענין ערובי חצירות בשבת, דפי' האריז\"ל עירוב הוא צירוף ע\"ב רי\"ו, שהם חסד וגבורה. וידוע דחסד הוא בחי' אהבה, וגבורה בחי' יראה, ולעבודת הש\"י צריך אדם לערוב בו המדות האלה, וכמו שהיה בבריאת העולם כמו שכ' בראשית ברא אלהים, בתחלה עלה במחשבה לברוא העולם במדת הדין ראה שאין העולם מתקיים שיתף מדת הרחמים והקדימו למדה\"ד שנ' ביום עשות ה' אלהים ארץ ושמים. פי' ע\"ד שכ' בפע\"ח בשם ה' גדלי' בשם הרב ז\"ל, דבתחלה היה בחינת יראה בספירות, ע\"כ לא רצה העילה לרדת ממדריגתו להשפיע להעלול שלא תתפגם קדושתו, וכן לא רצה העלול התחתון לעלות לעליון שלא יתבטל ממציאותו. וזהו בחי' עלה במחשבה לברוא במדה\"ד, היינו במדת יראה, ואחר התיקון היה שנבראו במדת אהבה, שהעילה תרד ותשפיע והעלול יעלה ויקבל, וז\"ש ביום עשות (רמז אהבה ויראה) ה' אלהים ארץ ושמים, שיתף מדה\"ר, דהיינו בחי' אהבה, והקדימו למדה\"ד שהוא בחי' יראה, דאעפ\"כ צ\"ל בחינת יראה שלא יעלה העלול למעלה ממדריגתו, וכן שלא לרדת העליון למטה יותר מהראוי, והם ע\"י שם מ\"ב ושם ע\"ב, שלא יעלה ולא ירד כל אחד חוץ מתחומו כ\"א עד תחום הראוי לו.\n<b>ע\"כ</b> קורה דמבוי שהיא למעלה מכ' אמה ימעט, וכן מלמטה מעשרה טפחים הקורה או לחיין שאמרו גבהן לא פחות מי' טפחים. וכן לפי' הנ\"ל שהעילה תרד והעלול יעלה אמרינן פי תקרה יורד וסותם, וגוד אסיק מחיצתא.\n<b>וזהו</b> ענין העירוב, דקודם שעירבו ונשתתפו צ\"ל בחינת יראה לחוד, דהיינו שלא להכניס מהמבוי לחצירות ומהחצירות לבתים, דכיון דהחצירות והמבוי הם רשות לכל החבירים צריכים אנו לחשבו כרה\"ר, וחלקו של כל יחיד לעצמו שהוא ביתו הוא בלבד רה\"י, ע\"כ צריך להיות בחי' יראה מלהכניס מהמבוי ומהחצירות לבתים, דה\"ל כמערב חול בקדש, ושלא להוציא מהבתים לחצרות ולמבוי דה\"ל כמוציא קדש לחול, דשמא יטעה ויוציא גם לרה\"ר גמורה. אבל אם ערבו ונשתתפו, שהרמ\"ז הוא כלומר שכולנו מעורבים ואוכל אחד לכולנו, וכמו שאנחנו שוים במקום זה שנשאר לכולנו כך כולנו שוין בכל מקום שאחז כל אחד לעצמו, והרי כולנו רשות אחד, ובמעשה זה לא יבואו לטעות ולדמות שמותר להוציא מרה\"י לרה\"ר גמורה. וגם ברמז עירוב הוא ע\"ב רי\"ו, בחינת אהבה משותף לבחינת יראה, אזי מותר להכניס מהמבוי לחצירות ולבתים, ומהבתים לחצר ולמבוי, אבל בחינת היראה צ\"ל שלא להוציא לחוץ מהמבוי לרה\"ר גמורה.",[["","","----- מקורות ומראה מקומות -----\n<b>?</b>\n<i>דפי' האריז\"ל כו'</i> – שער המצות, בשלח דרוש ג. <i>ע\"ב רי\"ו שהם חו\"ג</i> – תקו\"ז תכ\"א נה, ב. <i>דחסד כו' וגבורה כו'</i> – תקו\"ז י, ב. <i>בראשית ברא גו'</i> – בראשית א, א. <i>בתחלה עלה כו'</i> – בר\"ר יב, טו. זח\"ג שב, ב. רש\"י לבראשית ב, ד. <i>ביום עשות גו'</i> – בראשית ב, ד. <i>קורה דמבוי כו'</i> – עירובין ב, א ורש\"י שם. <i>וכן מלמטה כו'</i> – עירובין ה, א. רמב\"ם, הלכות שבת פי\"ז הי\"ד. <i>לחיין שאמרו כו'</i> – עירובין יד, ב. <i>פי תקרה</i> – עירובין כה, סע\"א. <i>וגוד אסיק כו'</i> – עירובין פט, סע\"א. <i>דכיון דהחצירות </i>. .<i> הוא בלבד רה\"י</i> – רמב\"ם הל' עירובין פ\"א ה\"ה. <i>דשמא יטעה </i>. .<i> גמורה</i> – שם ה\"ד. <i>שאנחנו שוים </i>. .<i> לרה\"ר גמורה</i> – שם ה\"ו.\n----- הערות וציונים -----\n<i>ולעבודת הש\"י צריך כו'</i> – ראה לעיל סי' קכז-א ובהערות שם. תניא, אגה\"ק סי' יג."]]],[300010428,"שנ\n\n<b>וע\"פ</b> ויראו את אלהי ישראל, השיגו, ותחת רגליו, פירוש על ידי מה [יוכל] להיות מרכבה אל אלהי ישראל, כמעשה לבנת הספיר, אם מזכך חומרו כמעשה לבנת הספיר, שיהיה עירוב ושתוף גוף ונפש, וגם עושה כמעשה לבנת הספיר שמפוצץ הפטיש, כד\"א וכפטיש יפוצץ סלע, ובמס' שבת דף פ\"ח ע\"ב פי' התוספות הסלע ספיר מפוצץ הפטיש, וכן ברמז יפוצץ היצר הרע, אם ברזל הוא מתפוצץ, ועי\"ז יזכה שיהיה כעצם השמים לטוהר, כמ\"ש והמשכילים יזהירו כזוהר הרקיע כו'.",[["","","----- מקורות ומראה מקומות -----\n<b>?</b>\n<i>ויראו גו' ותחת רגליו כמעשה גו' וכעצם גו'</i> – משפטים כד, י. <i>להיות מרכבה כו'</i> – ר' סוטה יז, א. פס\"ז עה\"פ. מדרש מעשה מרכבה פ\"ג. <i>וכפטיש גו'</i> – ירמי' כג, כט. <i>היצה\"ר אם ברזל כו'</i> – קידושין ל, ב. <i>והמשכילים יזהירו גו'</i> – דניאל יב, ג.\n----- הערות וציונים -----\n<i>ויראו </i>. .<i> השיגו ותחת כו'</i> – ר\"ל ע\"י ויראו גו' השיגו ענין ותחת רגליו כו'.\n<i>להיות מרכבה כו'</i> – ראה סוטה יז, סע\"א לכסא הכבוד שנאמר ויראו גו' וכתיב (יחזקאל א, כא) כמראה אבן ספיר דמות כסא. ובפס\"ז עה\"פ, ותחת רגליו זה כסא הכבוד. רג\"כ מדרש מעשה מרכבה פ\"ג.\n<i>להיות מרכבה כו'</i> – ראה לעיל סי' קעד ובהערות שם."]]],[300010429,"שנא\n\n<b>צופיה</b> הליכות ביתה, פי' צופיה הנשמה הליכות ביתה, פירוש הליכות ותנועות של עולם העליון שהוא ביתה, איך שם היא התנועה של מלאכי מעלה במהירות גדול לעבודת הש\"י, כמרז\"ל ע\"פ ועוף יעופף מיכאל ברגע א' גבריאל בשתים טסים כל העולם, ע\"כ גם היא ראוי, ולחם עצלות לא תאכל.",[["","","----- מקורות ומראה מקומות -----\n<b>?</b>\n<i>צופי' גו' ולחם גו'</i> – משלי לא, כז. <i>ועוף יעופף</i> – בראשית א, כ. <i>מיכאל כו' גבריאל כו'</i> – זח\"א מו, ב. ברכות ד, סע\"ב.\n----- הערות וציונים -----\n<i>עולם העליון שהוא ביתה</i> – להעיר מכד הקמח לרבנו בחיי, ערך גר. צוה\"ר סוף סי' פד."]]],[300010430,"שנב\n\n<b>ויקח</b> לו יעקב מקל לבנה [לח], רמז לאור המחיה העולמות, כמ\"ש ע\"פ בכל הארץ יצא קום כי תחלת הצמצום הוא קו, כי כל קו יש לו ימין ושמאל, כי מהרוחב יבואו ימין ושמאל, ומהגובה מעלה ומטה, ומהאורך פנים ואחור. וזהו יש מאין, יש ר\"ת ימין ושמאל, וזה הקו הוא הקו שבאמצע האלף, וכל זמן שהי' ישר הוא רחמים, יוי גי' הוי\"ה, וכשנתעקם הוא דין, כמ\"ש בכתבי האריז\"ל ובתיקונים. וכן בחרבן בהמ\"ק, חשב ה' להשחית חומת בת ציון ע\"כ נטה קו. וקו הנ\"ל נקרא בדרך משל מקל לבנה, רומז לאור עליון המחיה העולמות, לבנה ר\"ת ל\"ב נתיבות החכמה, לח, הנותן שפע חיות ולחלוחית וחיות בכל העולמות.\n<b>ויפצל</b> בהן פצלות, ע\"ד רמז התחיל להפריד הקליפות לבושין וכסויין מכל העולמות, ע\"כ אמר לבנות, פי' לגלות האור פנימי שנק' לב\"ן, וז\"ש מחשוף הלבן, הלבן ר\"ת ל\"ב נתיבות החכמה, וז\"ש אשר על המקלות, על דייקא, להוריד שפע אור לובן עליון.\n<b>ויצג</b> את המקלות אשר פצל ברהטים בשקתות המים, פי' מקום שרהטים ורצים שפע העליון שנקרא שקתות המים של ירידת שפע אור עליון, אשר תבאן הצאן, פי' ישראל שנקראים צאן מרעיתי אדם, מפני ששרשם הם מאותיות התורה, ונשמתם הם מטעמים ונקודות, צאן ר\"ת צירוף אותיות נקודות, וז\"ש לשתות לנוכח הצאן, נגד שרשי הנשמות שלמעלה בעולם עליון, ועי\"ז מחשוף הלבן, נתגלה לו ל\"ב נתיבות החכמה, ר\"ת הלבן, ועולמות עקודים נקודים וברודים שבמחשבה.\n<b>ותלדן</b> הצאן עקודים נקודים, ע\"ד רמז ה\"פ, דקשה מ\"ט מקדימין במבטא הנקודה קודם לאות, כגון קמץ אלף ול\"ק אלף קמץ, אלא מפני שאות בלי נקודה אין לו תנועה, וגם אין להם לאותיות חיבור כ\"א ע\"י הנקודות שהם התנועות, וז\"ש ותלדן הצאן עקודים, פי' ע\"י מה עקודים האותיות יחדיו, נקודים, ע\"י הנקודות הם הצאן, ר\"ת צירוף אותיות נקודות, על ידי הנקודים שהם הנקודות מצטרפות האותיות.",[["","","----- מקורות ומראה מקומות -----\n<b>?</b>\n<i>ויקח לו יעקב גו'</i> – ויצא ל, לז. <i>בכל הארץ יצא קום</i> – תהלים יט, ה. <i>הקו שבאמצע האלף</i> – תקו\"ז יט, ב. <i>יוי גי' הוי\"ה</i> – תקו\"ז ז, רע\"א ושם ריש ע\"ב. שם טו, ב. <i>חשב ה' גו'</i> – איכה ב, ח. <i>ויפצל גו' מחשף </i>. .<i> על המקלות</i> – ויצא ל, לז. <i>ויצג גו' אשר תבאן הצאן לשתות גו'</i> – ויצא ל, לח. <i>ישראל שנקראים צאן כו'</i> – בר\"ר עה, ו ויב. זח\"ב כא, רע\"א. <i>צאן מרעיתי אדם</i> – יחזקאל לד, לא. <i>ותלדנה הצאן גו'</i> – ויצא ל, לט.\n----- הערות וציונים -----\n<i>הקו שבאמצע האלף</i> – להעיר ממאמרי אדה\"ז תקס\"ז ע' רעח ואילך."]]],[300010431,"שנג\n\n<b>ולך</b> ה' חסד כי אתה תשלם לאיש כמעשהו. וקשה כיון דאינו משלם כ\"א כמעשהו של אדם, אם כן מהו החסד. ועיין פירושו בס' כתר שם טוב חלק א'<i>[ftnref_1_עו]</i>.",[["","","----- מקורות ומראה מקומות -----\n<i>ולך ה'</i> . . <i>כש\"ט חלק א</i>: <b>לעיל סי</b>'<b> קצא וש</b>\"<b>נ. </b><i>עוד י\"ל וכו'</i>: <b>?</b>\n<i>שכתבו המפרשים ע\"פ כו'</i> – מפרשי הסידור ביהי כבוד. רבנו בחיי פ' נשא ו, כד, ובכד הקמח ע' מציאות ה'. וראה זח\"א כד, ב. שם לד, א. <i>טפחות גו'</i> – תהלים לט, ו. <i>חמשים שנה נקרא אצלו עולם</i> – מכילתא משפטים כא, ו. אליהו רבה ספ\"ו. <i>ימי שנותינו גו'</i> – תהלים צ, י. <i>אין קצבה כו'</i> – מוסף דר\"ה לפני קדושה. <i>כי אלף גו'</i> – תהלים צ, ד. <i>יומו של הקב\"ה כו'</i> – מדרש תהלים צ, יב. בר\"ר ח, ב. <i>דשיתא אלפי כו'</i> – ר\"ה לא, א. <i>אין מלך בלי עם</i> – רב\"ח וישב לח, ל, ובכד הקמח ר\"ה-ב. <i>שהוא ע\"י התורה</i> – זח\"א ה, סע\"א. שם כד, ב. ועוד. <i>שקדמה לעולם</i> – פסחים נד, א. בר\"ר ח, ב. <i>שהיתה כלי אומנתו כו'</i> – בר\"ר א, א. <i>ואהי' אצלו גו' ואהי' שעשועים גו'</i> – משלי ח, ל. <i>המלך המרומם כו' המשובח כו'</i> – ברכת יוצר. <i>וכמ\"ש בע\"ח</i> – ע\"ח ש\"א פ\"א. <i>פקודא כו' ואית כו'</i> – זח\"ג רנז, ב. <i>דאי לא הויין כו'</i> – זח\"ב מב, ב. <i>מלא כל גו'</i> – ישעי' ו, ג. <i>וז\"ש קודם זה</i> – ביהי כבוד. <i>ישמחו השמים גו'</i> – דה\"א טז, לא. <i>עולם חסד יבנה</i> – תהלים פט, ג. <i>וכל העם נצב גו'</i> – יתרו יח, יד. <i>כמרז\"ל ע\"פ כו'</i> – שבת י, א (ושם ע\"פ יתרו יח, יג). <i>ולך ה' גו'</i> – תהלים סב, יג.\n----- שולי הגליון -----\n[ftn_1_עו]) <i>סימן קצא</i>.\n----- הערות וציונים -----"]]],[300010432,"(שנד)\n\n<b>עי\"ל</b> על פי מה שכתבו המפרשים ע\"פ ה' מלך ה' מלך ה' ימלוך לעולם ועד, והקשו דהרי פרושו הוא היה הוה ויהיה, וא\"כ הול\"ל מלך בקמץ קודם כענין היה הוה ויהיה.\n<b>ותירצו</b> דהנה אדם לקוצר שנותיו, כמ\"ש טפחות נתת ימי, יום א' נקרא לו זמן, כ\"ש שבוע או חדש או שנה, כ\"ש ז' שני שמטה, אך חמשים שנה נקרא אצלו עולם, דלפי קוצר שנותיו, כמ\"ש ימי שנותינו בהם ע' שנה כו'. אבל הקב\"ה כשם שהוא א\"ס כך הם שנותיו, כד\"א אין קצבה לשנותיך ואין קץ לאורך ימיך כו', ע\"כ אמרו קדמונינו כי אלף שנים בעיניך כיום אתמול כו' יומו של הקב\"ה אלף שנה, וידוע מארז\"ל דשיתא אלפי שני הוי עלמא וחד חרוב, נמצא דהמלכות של עתה הוא זמן קצר נגד הא\"ס דאין קצבה לשנותיו, ושיתא אלפי שני שיעמוד העולם הוא מלכותו של עתה הם כמו שיתא יומי, משא\"כ מלך בקמץ שהוא היה, וימלוך שהוא יהיה שהוא לעולם ועד, ומלת לעולם ועד קאי אשניהם, אמלך וימלוך, ע\"כ אסמכינהו להדדי.\n<b>עוד</b> תירצו, דהרי לכאורה קשה איך יצוייר תואר מלכות קודם בריאת עולם, דהרי אין מלך בלי עם. ופירשו דהקב\"ה אינו משער המצטרף, כענין אב ובן אדון ועבד, שלא יצוייר תואר אב אלא כשיש לו בן, ותואר אדון אלא כשיש לו עבד, אבל הקב\"ה ית' כשעלה ברצונו הפשוט לברוא העולם, שהוא ע\"י התורה שקדמה לעולם, שהיתה כלי אומנתו של הקב\"ה כמ\"ש ואהיה אצלו אמון, והתורה רושם אלהות והעולם רושם, ואף על פי שהיה עדיין במחשבה ובכח היה הוד והדר ועוז וחדוה ושעשוע, כד\"א ואהיה שעשועים יום יום, והיה המלך המרומם לבדו מאז, אע\"פ שהיה עדיין בכח, ולא יצא עדיין מן הכח אל הפועל, הי' מדת מלכות במחשבה, והיה השעשוע בעצמותו על שהוא פועל חכם ויכול לעשות הכל, כל יכול, לברוא עולם גדול כזה וצדיקים וחסידים ושרפי מעלה ואופנים וחיות הקדש, אבל המשובח והמפואר והמתנשא בשבח בפועל מימות עולם, וכמ\"ש בעץ חיים פקודא כו' ואית למנדע דאיהו איקרי חכם בכל מיני חכמות ומבין בכל מיני תבונות כו' אלא קודם דברא עלמא אתקרי בכל אינון דרגין על שם בריין דעתידין להבראות דאי לא הויין בריין בעלמא אמאי אתקרי רחום דיין אלא על שם בריין דעתידין כו' דאי לא אתפשט נהוריה על כל בריין איך ישתמודעון ליה ואיך יתקיים מלא כל הארץ כבודו. פירוש, שקודם בריאת עולם היה הקב\"ה נקרא חכם דיין רחום, רק שהי' בכח ע\"ש העתיד, אבל עתה הוא בפועל אחר שהאציל העולמות, ואין הדבר שלם אם אינו ג\"כ בפועל עכ\"ל ע\"ש.\n<b>וז\"ש</b> ה' מלך בסגול, פי' שהוא מלך עתה בפועל, מזה אנחנו יודעים ה' [מלך] בקמץ, פי' היה קודם הבריאה, וימלוך פי' יהיה לעולם ועד. וז\"ש קודם זה, ישמחו השמים ותגל הארץ ויאמרו בגוים ה' מלך, פי' מדחזינן שהקב\"ה ייחס לעצמו תואר מלכות גם קודם הבריאה על ששיער במחשבתו הקדושה שהוא יכול לברוא עולם כזה, והיה שעשוע וחדוה לפניו כו', שמע מיניה דהעולם הוא פעולה חשובה ונכבדת, ע\"כ ישמחו השמים ותגל הארץ בשביל זה.\n<b>והנה</b> העולם נקרא עולם חסד יבנה, והצדיק אמרו רז\"ל דהרי הוא כאלו נעשה שותף להקב\"ה במעשה בראשית, כמרז\"ל ע\"פ וכל העם נצב עליך מבקר עד ערב, וכי ס\"ד תורתו מתי נעשית, אלא כל דיין הדן דין אמת לאמיתו אפילו שעה א' מעלה עליו הכתוב כאלו נעשה שותף להקב\"ה במ\"ב כו'. וז\"ש ולך ה' החסד, פי' אע\"פ שאתה ה' בעצמך ובכבודך בראת העולם, שנאמר עולם חסד יבנה, אעפ\"כ כי אתה תשלם לאיש הצדיק כמעשהו, כאלו עשה וברא ויצר עמך בשותפות את העולם.",[["","","----- מקורות ומראה מקומות -----\nראה מקבילות לעיל סימן שנג.\n----- הערות וציונים -----\n<i>ע\"פ ה' מלך כו'</i> – כידוע אין זה אלא צירוף ג' פסוקים, ולהעיר שכבר הובא בס' הבהיר (סי' קיא וקכז), ובזהר (זח\"א (כד, ב) לד, א) בלשון דכתיב, ועיימש\"כ שם בהג' אור בהיר ונצו\"ז. וראה לקו\"ש חי\"ד ע' 227 ואילך.\n<i>איך יצוייר תואר מלכות קודם בריה\"ע כו'</i> – ראה עטרת ראש לאדה\"א פ\"ה ואילך. סה\"מ תש\"ג ד\"ה אדון עולם.\n<i>עולם חסד יבנה</i> – ר\"ל בלי אתדל\"ת. ראה מו\"נ ח\"ג פנ\"ג. ע\"ח ש\"ח ספ\"ו. תניא, אגה\"ק סי' ה.\n<i>נעשה שותף להקב\"ה</i> – ראה זח\"א ה, א."]]],[300010433,"שנה\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; בראשית, ות\"י בחכמה <span data-k=\"sm\">[וכו']</span>, שהוא אות א', בזה ברא אלהים א\"ת <span data-k=\"sm\">[השמים]</span>, כי כל <span data-k=\"sm\">[כ\"ב]</span> אותיות הם לבושים זל\"ז. כי א' נתלבשה תוך אות ב', כי ב' ב' אלפין, ג' ג' אלפין <span data-k=\"sm\">[כמו ששמעתי </span><i>ממורי</i><span data-k=\"sm\"> זלה\"ה]</span>. וראשית הבריאה הי' ע\"י אות א' שהוא חכמה &lt;כמ\"ש ואאלפך חכמה&gt;, וברא הכל ע\"י חכמה כמ\"ש כולם בחכמה עשית, כי נתפשטו האותיות מלמעלה למטה, ובזה ברא כל הנבראים ע\"י כ\"ב אותיות מא' עד ת'. וכל הנברא ע\"י אות שהוא קרוב למאציל הוא יותר עליון, עד כי הנברא מאות ת', שהוא אות אחרון, בריה זו הוא שפל בריה מכל הנבראים, כ\"א שיקרב אדם את עצמו להש\"י ויוכלל מן אות ת' לאות ש' בסוד תשר\"ק עד שיקרב אל אות א' ששם אלופו של עולם. וזש\"ה מבטן שאול שועתי אליך וגו'.\n<b>הרי</b> רוחניותו יתברך בתוך אות א', ונתעטף בו וברא אור מן אות א' והוא אור אצילות, ואח\"כ נתעטף עם אות א' <span data-k=\"sm\">[בתוך]</span> אות ב' וברא עולם הבריאה כמ\"ש בכנפי יונה <span data-k=\"sm\">[יעו\"ש]</span>. ואחר כך חזר ונתעטף עם אות ב' בתוך אות ג' וברא עולמות למטה מעולם הבריאה, עד שנתעטף באות ת' וברא עולמות תחתונים שנק' מלכות שבמלכות.\n<b>וז\"ש</b> בראשית, בחכמה, שהוא א', ברא אלהים את השמים, שהוא כ\"ב אותיות מן א' עד ת', ובתוכו רוחניותו ית' שנק' שמים, שנתעטף ונתלבש הקב\"ה בתוך כ\"ב אותיות אלו וברא את הארץ שהוא כל ענייני חומר הארץ, שהוא ע\"י ד' מאות לבושין מן א' עד ת' שהוא ארץ תחתית שאין למטה ממנו. ואח\"כ חזר הקב\"ה ונסתתר בכמה כסויין ובכמה קליפין דאינון תוהו ובוהו וחשך &lt;ותהום&gt; <span data-k=\"sm\">[וכו']</span>, כמ\"ש בתיקונים. וז\"ש והארץ היתה תוהו ובהו &lt;כו'&gt; <span data-k=\"sm\">[וחושך וגו']</span>, ר\"ל לאחר שנתלבש בד' מאות לבושין שהיא אות ת', ובאלו הלבושין ברא הארץ, חזר ונסתתר בכמה קליפין [. . .].\n<b>וזש\"ה</b> והארץ היתה תוהו ובוהו וגו', כי צפה וראה שיהיו דורות רשעים וגנז אור הנ\"ל ונסתתר מן חייביא בכמה קליפין <span data-k=\"sm\">[וכו']</span>, אבל לגבי צדיקייא שנקראו אלהים, כמ\"ש במשה ראה נתתיך אלהים לפרעה, וכן יעקב ויקרא לו א-ל אלהי ישראל, וכיוצא בשאר צדיקייא, לא אסתתר מהן הקב\"ה, לכך ויאמר אלהים יהי אור ויהי אור, ר\"ל מיד כשעולה במחשבה של אנשי הדעת שנק' אלהים שהקב\"ה שנקרא אור מסתתר שם אז נתפרדו <span data-k=\"sm\">[כל פועלי און]</span> ונתגלה אורו ית', וז\"ש ויהי אור, והבן והש\"י יכפר.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ר</b>\"<b>פ בראשית ז</b>,<b> א (כב</b>,<b> ב)</b>\n<i>בראשית ברא גו'</i> – בראשית א, א. <i>ות\"י בחכמה</i> – ת\"י שם. ספר הבהיר ג. זח\"א ג, ב. שם קמה, א. <i>בחכמה שהוא אות א'</i> – ר' זח\"א כו, ב. זח\"ב קלו, סע\"ב. <i>א\"ת </i>. .<i> כל כ\"ב אותיות</i> – זח\"א טו, ב. שם כט, ב. תקו\"ז רתנ\"א פו, ב. אליהו רבה פי\"ח. <i>כל כ\"ב אותיות הם כו'</i> – זח\"א לג, רע\"א. <i>ואאלפך חכמה</i> – איוב לג, לג. <i>כולם בחכמה עשית</i> – תהלים קד, כד. <i>אות א' </i>. .<i> אלופו ש\"ע</i> – זח\"ג לא, א. חגיגה טז, א. <i>מבטן שאול גו'</i> – יונה ב, ג. <i>כמ\"ש בתיקונים</i> – תכ\"ו עא, סע\"ב. <i>והארץ היתה גו'</i> – בראשית א, ב. <i>צפה וראה כו'</i> – ר' חגיגה יב, א. <i>וגנזו אור הנ\"ל כו' אבל לגבי צדיקייא כו'</i> – זח\"ב רכד, סע\"ב. <i>ראה נתתיך גו'</i> – וארא ז, א. תנחומא וארא ח. שמ\"ר ח, א. <i>ויקרא לו גו'</i> – וישלח לג, כ. מגילה יח, א. בר\"ר עט, ח. <i>לא אסתתר מהן הקב\"ה</i> – ר' זח\"א מז, א. זח\"ב רכד, סע\"ב. <i>ויאמר אלקים יהי אור גו'</i> – בראשית א, ג.\n----- הערות וציונים -----\nחלק מסימן זה כבר הובא לעיל סי' פו.\n<i>א\"ת</i> – ר\"ל נוטריקון לכ\"ב אותיות מא' עד ת' כמבואר במקורות אשר צויינו במ\"מ.\n<i>כי א' נתלבשה תוך אות ב' כו'</i> – עיין לעיל סי' קצ. ורג\"כ לעיל סי' מה וקס."]]],[300010434,"שנו\n\n<b>&lt;אשר</b> יעשה אותם האדם וחי בהם היינו לזכך חומרו כמו חנוך ואליהו שנעשו מלאכים חיים ונעשו מחומר צורה&gt;<i>[ftnref_1_עז]</i>, והנה יש בחינה שאחר עלותו למעלה חוזר ויורד כדי להעלות מדריגות התחתונים בסוד רחצתי את רגלי <span data-k=\"sm\">[איככה אטנפם, וכאשר כתבתי מזה במ\"א]</span>. וז\"ס רצוא ושוב, ונק' קטנות וגדלות <span data-k=\"sm\">[וקטנות שני]</span>, ובכל ירידה צריך אזהרה איך לחזור ולעלות שלא ישאר ח\"ו, וכמו ששמעתי <i>ממורי</i> שיש כמה שנשארו <span data-k=\"sm\">[וכו']</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ר</b>\"<b>פ וירא יז</b>,<b> ב (נט</b>,<b> א)</b>\n<i>אשר יעשה גו'</i> – אחרי יח, ה. <i>כמו חנוך ואליהו כו'</i> – זח\"ג סח, ב. <i>כמ\"ש הרמב\"ן</i> – בפירושו לפ' אחרי יח, ד. <i>רחצתי גו'</i> – שה\"ש ה, ג. <i>רצוא ושוב</i> – יחזקאל א, יד.\n----- שולי הגליון -----\n[ftn_1_עז]) <i>במקורו</i>: תכלית בריאת אדם בחומר וצורה כדי לזכך חומרו ושיהיה נעשה מן חומר צורה. וז\"ש אשר יעשה אותם האדם וחי בהם, כמ\"ש הרמב\"ן שיש בזה כמה מדריגות ובחינות, מדריגות חנוך ואליהו שהיו מזככים כ\"כ חומרם שנעשו מלאכים חיים וקיימים וכו' יעו\"ש.\n----- הערות וציונים -----\n<i>חנוך</i> – ראה תיב\"ע ומדרש אגדה בראשית ה, כד.\n<i>אליהו</i> – ראה זח\"א קנא, ב ושם רט, א.\n<i>שהיו מזככים כ\"כ כו'</i> – ראה ע\"ח של\"ט פ\"א כי זהו מעלת הצדיקים לזכך גופם ולעשותן צורה וזהו הטעם שאין מיתה נזכר בצדיקים וראיה לדבר מאליהו ז\"ל וכו' עיי\"ש.\n<i>ויש בחינה כו'</i> – מכאן עד הסוף כבר הובא לעיל סי' צ."]]],[300010435,"שנז\n\n<b>&lt;ממוהר\"נ</b> קסוויר להוכיח&gt; <span data-k=\"sm\">[שמעתי בשם מוהר\"ר נחמן קאסוויר שהוכיח]</span> לבני אדם שאינם מקיימין שויתי ה' &lt;לנגדי תמיד&gt; גם בעסקו בסחורה ומשא ומתן. וכי תימא האיך אפשר זה <span data-k=\"sm\">[וכו']</span>, הא בהיותו בבית הכנסת ומתפלל אפשר לו לחשוב בכל מיני סחורות ומשא ומתן, ה\"ה &lt;ה\"נ&gt; <span data-k=\"sm\">[איפכא נמי]</span> אפשר &lt;בעסקו במשא ומתן לקיים שויתי ה' כו'&gt; <span data-k=\"sm\">[ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י וירא יז</b>,<b> ד (סא</b>,<b> א)</b>\n<i>שויתי ה' גו'</i> – תהלים טז, ח.\n----- הערות וציונים -----\nלהעיר מדאיתא בתוי\"י פ' שופטים קפו, ב (תרעט, א) ששמעתי שהחסיד מוהרר\"ן קסויר נתן לאיש א' מידי שבוע בשבוע סך קצוב עבור כשיהיה בין אנשים להזכירו ברמז שלא שכח שם הוי' שיהי' נגדו תמיד ודפח\"ח. ורג\"כ בשבחי הבעש\"ט (ע' קמט) העובדא דפגישת הר\"ן עם הבעש\"ט."]]],[300010436,"שנח\n\n<b>בגמרא</b> כל תפלה שאין בה מתפלת פושעי ישראל אינה תפלה כו', כמו בי\"א סממני הקטורת. וקשה, וכי ס\"ד שיחפשו דוקא אחר פושעי ישראל להיותן אצל התפלות, דבאם לאו כו'. ופי' דה\"פ, ע\"פ משל למה הדבר דומה, דעץ לח אינו יכול להיות דולק כשהוא לבדו, אבל כשמדליקין עשרה עצים יבשים א\"כ גם כשישים עמהם עץ א' לח ידלוק ג\"כ כמו היבשים. והנה בנדון זה ג\"כ, כשיש עשרה צדיקים המתפללים בדביקות עצום ובהתלהבות גדול, גם כשבאים פושעי ישראל אזי מתלהב לבבם להתפלל בכונה גדולה ובדביקות עצום. וזהו הפירוש כל תפלה שאין בה מתפלות פושעי ישראל, פירוש שע\"י התפלה שלהם יעוררו גם את הפושעי ישראל שיתפללו, כשאין פועלים זה אין תפלתם תפלה.",[["","","----- מקורות ומראה מקומות -----\n<b>?</b>\n<i>בגמרא</i> – כריתות ו, ב (ושם: כל תענית).\n----- הערות וציונים -----\n<i>בגמרא כל תפלה כו'</i> – בגמרא נאמר כל תענית. ברם ראה רש\"י ורב\"ח לשמות לו, לד (וכן רש\"י מנחות כז, א ד\"ה הרצאה) בתעניותינו ותפילותינו. ורב\"ח ציין למנחות כז, א כל אגודה שאין בה כו'. וראה גור אריה לשמות שם (וכן בחידושי אגדות שלו לכריתות שם), ובספר החיים לאחיו הרר\"ח ח\"ד פ\"ז, שדייקו ענין התעניות דוקא.\n<i>כשיש עשרה צדיקים כו'</i> – להעיר שזהו לשיטת פי' המהרש\"א בכריתות שם. ועיין מש\"כ במראית העין להחיד\"א שם. ולהעיר מאגרת השמד להרמב\"ם, קרוב לסופו, שהביא בשם חז\"ל שלא ידור אדם בעיר שאין בה עשרה צדיקים (נ\"א חסידים) כו'."]]],[300010437,"שנט\n\n<b>איש</b> אחד צדיק הי' חולה זמן רב, וכשהי' עובר דרך שם הבעש\"ט נתנו לו פדיון, וביקש ממנו תלמידו מהבעש\"ט שיבקש רחמים עליו שיעמוד מחליו איש זה כי הוא איש צדיק, וגם העולם מתרעם עליו שקיבל פדיון ואינו מועיל. ואמר לו הבעש\"ט, יהי' עדיין חולה ויהי' שוכב על ערש דוי. והפציר בו תלמידו לרבו הבעש\"ט כו', וא\"ל הבעש\"ט זלה\"ה, הנה אגלה לך שיש ביער כמה רקים ופוחזים ורוצים להרוג כמה אנשים מערים של ישראל, וזה האיש ע\"י יסוריו הוא מגין עליהם, וכי כבר נשלחו אנשי מלחמה לבקש אותן הרוצחים, ואחר שלשה ימים כשיביאו לעיר אותן הריקים ופוחזים אסורים בכבלי ברזל אז יעמוד זה האיש בריא כאולם. וכן הי', שתיכף כשהביאו לעיר אותן הפוחזים והיו רצים כל אנשי העיר לראותם, עמד גם זה האיש תיכף מחליו ג\"כ.",[["","","----- הערות וציונים -----\nלהעיר מב\"מ פה, א. ירושלמי כלאים פ\"ט ה\"ג. בר\"ר לג, ד."]]],[300010438,"שס\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt;. בכל יום בת קול יוצאת מהר חורב ומכרזת כו' . . . שהקשה <span data-k=\"sm\">[</span><i>מורי</i><span data-k=\"sm\"> זלה\"ה]</span> ממה נפשך, אם א\"א לשמוע הכרוז א\"כ הכרוז למה, ואם אפשר מאי טעמא &lt;לא נשמע&gt; <span data-k=\"sm\">[אין שומע]</span> וכו' . . . ששמעתי <i>ממורי</i> <span data-k=\"sm\">[זלה\"ה]</span> ביאור המשנה עין רואה ואוזן שומעת כו', &lt;ופי'&gt; מצד שהוא עין ראוי לראות מסוף העולם ועד סופו, ואוזן ראוי לשמוע הכרוזין של מעלה, רק שעונותינו מבדילין מצד שהנשמה בגלות יצה\"ר וג' קליפות של ערלה מסבבין הראיה והשמיעה, וצריך שישבר הקליפות ואז יכול לשמוע ולראות. <i>ומורי</i> זללה\"ה יוכיח שראה מרחוק ושמע הכרוזין כאשר נתברר לאמיתו, וא\"כ אפשר ואפשר לשמוע ולראות כו'.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ וארא כה</b>,<b> א (ק</b>,<b> א)</b>\n<i>בכל יום כו'</i> – אבות פ\"ו מ\"ב. <i>עין רואה כו'</i> – אבות פ\"ב מ\"א.\n----- הערות וציונים -----\nראה לעיל סי' קמו ורנה, ובהערות שם.\n<i>ביאור המשנה עין רואה כו'</i> – ראה לעיל סי' קעה."]]],[300010439,"שסא\n\n<b>איש</b> אחד חכם גדול ובקי בכל הש\"ס ופוסקים הי' בעיר שהי' הבעש\"ט דר שם, ולא הי' נשמע לדברי הבעש\"ט ולא האמין בהשגתו הגדולה, והבעש\"ט הי' חושק מאוד לקרבו אליו. והנה פעם א' למד זה החכם הלכה עמוקה ודיבור תוספות א' ולא הבין את דברי התוספות, ונתקשה מאד בעיון גדול כמה שבועות להבין את דברי התוספות ולא עלתה בידו, ונצטער מאד ע\"ז. והנה בלילה אחד ראה בחלומו והנה מעלין אותו לעולמות עליונים, וראה שמעלין אותו היכל לפנים מהיכל עד שכהו עיניו מלראות גודל האורות עליונים והי' סוגר עיניו, עד שהכניסוהו להיכל פנימי א' וא\"ל פתח עיניך. ופתח עיניו וראה הרבה חכמים גדולים וצדיקים יושבים ועוסקים בתורה, והבעש\"ט זלה\"ה יושב בראש כולם. וא\"ל הבעש\"ט זלה\"ה, למה אתה מתקשה כ\"כ להבין את דברי התוס', הלא הפשט הוא כך וכך וכו'. ובבוקר כשניעור משנתו, לקח הגמרא והי' מעיין בדבור התוספות הנ\"ל וראה שהפשט הוא ברור כשמש כאשר א\"ל הבעש\"ט זלה\"ה. והנה אעפ\"כ הי' סובר שמא הוא חלום לבד. והנה כשבא שבת קדש הלך על סעודה ג' להבעש\"ט זלה\"ה, ותיכף כשבא לבית הבעש\"ט א\"ל ברוך הבא, וא\"ל היית מעיין בפשט התוס' אשר אמרתי לך אם פשט זה הוא אמיתי כו'. ומזמן ההוא והלאה הי' משמש את הבעש\"ט ז\"ל ונעשה חסיד גדול. כל זה שמעתי מאנשי אמת.",[["","","----- הערות וציונים -----\nלהעיר מהסיפורים בשבחי הבעש\"ט עם \"למדן מופלג ורצון הרב היה מאד לקרבו\" (ע' נט), ועם הר\"מ קעדס (ע' קכא). וכן העובדא עם \"רב גדול שהבעש\"ט רצה להתקשר עמו\", הובא בקונ' מאירת עינים בריש ספר בעל שם טוב, אות טו."]]],[300010440,"שסב\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[דשמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> זלה\"ה פי' המשנה כל תורה שאין עמה מלאכה כו'. וביאר דיש ג' מיני דיבור שהם ג' מיני זווג, א' זווג המלך ומטרוניתא, ב' זווג בן המלך וזוגתו, ג' זווג דעבד ושפחה כו'. והנה הדיבור בתורה ובתפלה שהוא הזווג קוב\"ה <span data-k=\"sm\">[ושכינתיה]</span> שישמש באבר חי, דהיינו עם המוחין שהם י\"ה חו\"ב דחילו ורחימו, יהיה נמשך ע\"י אות ו' על הדיבור שהוא ה' כו' יעו\"ש.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ וארא כד</b>,<b> רע</b>\"<b>ג (צז</b>,<b> ב)</b>\n<i>כל תורה כו'</i> – אבות פ\"ב מ\"ב. <i>י</i>-<i>ה חו\"ב</i> – זח\"ג קנג, ב. <i>דחילו ורחימו</i> – זח\"ג קכג, ריש ע\"ב. תקו\"ז ת\"י כה, ב. <i>נמשך ע\"י אות ו'</i> – ר' זח\"ב קלג, ב. <i>הדיבור שהוא ה'</i> – זח\"א קמה, א.\n----- הערות וציונים -----\n<i>שמעתי </i>. .<i> קוב\"ה ושכינתיה</i> – כ\"ז כבר הובא לעיל סי' ריג-א וראה שם בהערות.\n<i>שישמש כו'</i> – ראה לעיל סי' טז ובהערות שם. ועיין כתונת פסים פ' בהעלתך לו, א: ששמעתי ממורי פי' המשנה וכל תורה שאין עמה מלאכה סופה בטלה וגוררת עון וכו', והענין כי מבשרי אחזה אלוה, דיש ברית הלשון וברית המעור, זה מוליד בגשמי וזה ברוחני, ומובא בכתבים משחז\"ל ראו אשה מדברת וכו', הרי שבדבור יש זווג וכו', פה גי' מילה, וכמו שבזווג גשמי אין הזווג כ\"א באבר חי וחשק בשמחה משא\"כ בעצבות גורם ח\"ו סכנה להילד, ואחר שהזריע טיפת הזרע מהמוח ונסתלק המוחין שוב אין לשמש כ\"א אחר זמן, ככה בזווג הרוחני שהוא הדבור בתורה ותפלה ע\"י המוחין מדו\"ר (מכונה לנשיקה) שנמשך מחו\"ב שהם אותיות י\"ה נמשך אל הפה שהוא מ\"ל האחרונה [נראה שר\"ל: מלכות ה' אחרונה] ע\"י ו' שהוא ההמשכה, נמצא עסק התורה ותפלה עם המוחין נק' משמש באבר חי להזריע ואחר התפלה ועסק התורה שנסתלקו המוחין ובא הקטנות שכיח כעס וספורי לשון הרע ודברים בטלים, ועצה יעוצה בעת שנסתלקו המוחין יעסוק במלאכה וניצול מעון, וז\"ש וכל תורה שאין עמה מלאכה גוררת עון וכו' ודפח\"ח. (וראה מזה לקמן בהערות לסי' שעח).\n<i>נמשך ע\"י אות ו'</i> – ראה בהערות לסי' מו-א ד\"ה נמשך שהוא ו'."]]],[300010441,"שסג\n\n<b>&lt;מבעש\"ט&gt;</b> איזהו חכם הלומד מכל אדם, אפי' מאדם רע שרואה דבר עבירה בו ולומד ממנו, שמצד אחדות יש בו שמץ מנהו ג\"כ וצריך לתקן עצמו משמץ זה שבו, ואז גורם טהרה לזולתו &lt;כו', וז\"ש&gt; <span data-k=\"sm\">[וכנ\"ל]</span> זאת תורת המוציא רע מרעתו ביום טהרתו של עצמו <span data-k=\"sm\">[וק\"ל]</span>. וכמדומה ששמעתי סגנון זה <i>ממורי</i> <span data-k=\"sm\">[זלה\"ה]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ וארא כו</b>,<b> סע</b>\"<b>ד (קו</b>,<b> ב)</b>\n<i>איזהו חכם כו'</i> – אבות פ\"ד מ\"א. <i>זאת [תהי'] תורת המצורע</i> – מצורע יד, ב. <i>המוציא רע</i> – ראה ערכין טו, ב.\n----- הערות וציונים -----\nראה לעיל סי' פט, קטז ושב-א. ולקמן בהוספות סי' קעו ובהערות שם.\n<i>שמצד אחדות יש בו כו'</i> – ראה בהערות לסי' נד."]]],[300010442,"שסד\n\n[<b>לעולם</b> <span data-k=\"sm\">יעסוק בתורה שלא לשמה, לשון צווי, כדי שאם יעסוק אח\"כ לשמה אז מתו\"ך שלא לשמה בא לשמה, כאשר]</span> שמעתי בשם <i>מורי</i> שיעלה הפנימיות &lt;של&gt; שלא לשמה <span data-k=\"sm\">[וכו']</span> ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ בא לא</b>,<b> סע</b>\"<b>ב (קכ</b>,<b> ב)</b>\n<i>לעולם יעסוק כו'</i> – פסחים נ, ב.\n----- הערות וציונים -----\nכבר הובא לעיל סי' ריג-ב, וראה שם בהערות."]]],[300010443,"שסה\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[דשמעתי </span><i>ממורי</i><span data-k=\"sm\"> .</span><span data-k=\"sm\"> . </span><span data-k=\"sm\">. כי]</span> יראת העונש, שהיא יראה חצונית, מורה על ידו ית' פשוטה לקבל שבים ויתעורר <span data-k=\"sm\">[מזה]</span> ליראה פנימית הנקרא אהבה לקבל באהבה, ואז יפטור מיראה חיצונית &lt;וד\"ל&gt; <span data-k=\"sm\">[וכו']</span> ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ בא לא</b>,<b> סע</b>\"<b>ג (קכא</b>,<b> ב)</b>\n<i>ידו ית' פשוטה כו'</i> – זח\"א כג, רע\"א. תקו\"ז תמ\"ז פד, סע\"ב. פדר\"א ר\"פ מג.\n----- הערות וציונים -----\nכבר הובא לעיל סי' קעז, וראה שם בהערות."]]],[300010444,"שסו\n\n<b>&lt;מהבעש\"ט</b> ז\"ל&gt; <span data-k=\"sm\">[דשמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> פירוש משנה דאבות <span data-k=\"sm\">[פ\"ב]</span> והוי מתחמם כנגד אורן של חכמים והוי זהיר בגחלתן שלא תכוה כו' וכל דבריהם כגחלי אש. וביאר כי &lt;הראשונים&gt; <span data-k=\"sm\">[התנאים]</span> נהגו לומר מלתא דבדיחותא קודם הלימוד, והטעם כי יש קטנות וגדלות בעולם שנה ונפש, וע\"י מלתא דבדיחותא עולה מהקטנות ומתדבק בגדלות. והנה בזמן הגדלות שיש בעולם, דהיינו שיוכל ללמוד ולהתפלל בדחילו ורחימו ויודע כי הוא מדבר עם המלך הגדול ומתדבק בו ית', אין תענוג גדול יותר מזה, והוא בחי' הגדלות. משא\"כ בימי הקטנות שיש בעולם, אז צריך האדם מלחמה כדי שיוכל להתקרב אליו ית', וזהו עיקר השכר שיש לאדם שעושה על צד ההכרח, &lt;וגם&gt; שלא יוכל לעשות הטוב בפועל, מ\"מ בלבי צפנתי אמרתיך ומבחוץ יעשה ענינים גשמיים. וזהו שארז\"ל בענין תורה ומלאכה שיגיעת שניהם משכחת עון. וגם ע\"י ספורים שמספר עם חבירו יכול לעשות עי\"ז יחודים, ופי' בש\"ס דר\"ה שהיה נחמיה מספר עם המלך <span data-k=\"sm\">[ארתחשסתא]</span> ואז <span data-k=\"sm\">[ועי\"ז]</span> היה מתפלל להש\"י, וד\"ל וכיו\"ב הרבה.\n<b>ובזה</b> יובן והוי מתחמם כנגד אורן של חכמים, ר\"ל כשהם בגדלות ועוסקין באור תורה ותפלה, שהם מתלהבין באור אש ממש, פשיטא דתהוי מתחמם כנגד אורן. אבל הוי זהיר בגחלתן, ר\"ל כשהם בימי הקטנות שאין להם אור להתלהב באור פנימי &lt;ואז נק' גחלת בלי אור פנימי&gt; וירצה התלמיד ללמוד ממנו מה שעוסק בגשמיות, ואינו יודע מה שמקיים הרב אז בלבי צפנתי אמרתיך לעסוק בגשמי ומכוין בפנימי ורוחני, והתלמיד ילמוד ממנו מה שנגלה לו עסקו בגשמי ויענש, שנשיכתן נשיכת שועל ועקיצתן עקיצת עקר\"ב, ר\"ל שמקרב ז' מדריגות שכל א' נכלל מעשרה ונק' ע' קרב, שמקרב ז' מדריגות אלו לשרשן, והתלמיד אינו יודע מזה וסובר שהרב עוסק בגשמי כפשיטתו, ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ בא לא</b>,<b> ד (קכב</b>,<b> א)</b>\n<i>דאבות פ\"ב</i> – סמ\"י. <i>מלתא דבדיחותא כו'</i> – שבת ל, ב. <i>בלבי צפנתי גו'</i> – תהלים קיט, יא. <i>תורה ומלאכה כו'</i> – אבות פ\"ב מ\"ב. <i>בש\"ס דר\"ה</i> – ר\"ה ג, ב. <i>שנשיכתן כו'</i> – אבות פ\"ב סמ\"י. <i>שכל א' נכלל כו'</i> – תקו\"ז תמ\"ז פד, א. תס\"ט קטז, ב.\n----- הערות וציונים -----\nבקו\"א דבפ\"י (הובא לעיל סי' עז) בקיצור, ועיין לעיל סי' רמד.\n<i>מלתא דבדיחותא</i> – ראה לעיל סי' לז.\n<i>עיקר השכר כו'</i> – להעיר משמנה פרקים להרמב\"ם פ\"ו עיי\"ש.\n<i>ואז היה מתפלל להש\"י</i> – עיין בחדושי אגדות למהרש\"א ר\"ה שם ד\"ה ושעריה: ועי\"ל ואומר למלך מוסב למעלה כו' עיי\"ש. וכן בעשרה מאמרות, מאמר אם כל חי ח\"א סי' ז, וביד יהודה שם.\n<i>שכל א' נכלל מעשרה</i> – מבואר בפ\"ר להרמ\"ק ש\"ה (ובפרט פ\"ה) וש\"ח (בפרט פ' א-ב, י-יא). ע\"ח ש\"ט פ\"ז ושם שכ\"ד פ\"א. ועיין שערי קדושה למהרח\"ו ח\"ג ש\"א. ולהעיר מהל' יסוה\"ת פ\"ד ה\"א וה\"ב (והשוה לזה זח\"ב כג, ב ואילך). ועיין או\"ת להרה\"מ סי' רנח (עז, ב). ורג\"כ לעיל סי' פא."]]],[300010445,"שסז\n\n[<b>שמעתי</b> <i>ממורי</i><span data-k=\"sm\"> זלה\"ה]</span> ענין והחיות רצוא ושוב [. . .<i>[ftnref_1_עח]</i>] &lt;כי&gt; ע\"י ביטולו מעבודת ה' &lt;בזמן עסק מו\"מ ומאכילה כו'&gt; ינוח הנשמה וכח השכלי יתחזק לחזור ולעסוק בעבודת ה' אח\"כ, וזהו והחיות רצוא ושוב <span data-k=\"sm\">[ודפח\"ח, אך שאין זה לשונו כי הוספתי מעט]</span>. וכל זה כשאדם עושה במשקל שכלו הקדוש שאינו מבטל מעסק התורה ועבודת ה' &lt;כ\"א קצת&gt; <span data-k=\"sm\">[רק]</span> זמן מה כדי שתנוח כח הנשמה ולא תתבטל הנשמה ממציאות, זה נק' עובד ה' בגשמי וברוחני כל ימיו מאחר שהגשמי הוא כסא לרוחני.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ בא לג</b>,<b> סע</b>\"<b>ב (קכז</b>,<b> א)</b>\n<i>והחיות רצו\"ש</i> – יחזקאל א, יד.\n----- שולי הגליון -----\n[ftn_1_עח]) <i>כאן חסר ההמשך והובא לעיל סי' קעח. עיי\"ש.</i>\n----- הערות וציונים -----\nכמש\"כ בשוה\"ג כאן, דברי הבעש\"ט במילואם הובאו לעיל סי' קעח ועיי\"ש בהערות.\n<i>שהגשמי כסא להרוחני</i> – להעיר מאזהרת הבעש\"ט לעיל סי' קפח בסוף ד\"ה והלבנה."]]],[300010446,"שסח\n\n<b>שמעתי</b> <i>ממורי</i> <span data-k=\"sm\">[זלה\"ה]</span> ענין מ\"ז האיך להעלות הפנימי ולתקנם וחיצונית יתפרדו, ואם אינו יודע דרך פרט על כל פנים ידע דרך כלל שבכל דבר ודבר יש בו יחוד ב' שמות הוי' אדנ-י וכו' ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ בשלח מט</b>,<b> ב (קעט</b>,<b> ב)</b>\n<i>רומח</i> – בלק כה, ז. <i>פלוגתא ב\"ש וב\"ה כו'</i> – כתובות יז, א.\n----- הערות וציונים -----\n<i>ענין מ\"ז האיך להעלות כו'</i> – ראה לעיל סי' לט ועיי\"ש בהערות.\n<i>וכעין זה שמ\"מ סוד רומח</i> – ראה לעיל סי' קלה בהערות.\n<i>פלוגתא ב\"ש וב\"ה</i> – ראה לעיל סי' קעט."]]],[300010447,"(שסט)\n\n<b>וכעין</b> זה שמעתי <i>ממנו</i> סוד רומח וכו', וביאור פלוגתא ב\"ש וב\"ה כלה נאה וחסודה או כלה כמו שהיא <span data-k=\"sm\">[וכו']</span>.",[["","","----- מקורות ומראה מקומות -----\nראה מקבילות לעיל סימן שסט.\n----- הערות וציונים -----\nראה הערות וציונים לעיל סימן שסח."]]],[300010448,"שע\n\n<b>&lt;מהבעש\"ט</b> ז\"ל&gt; <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> ביאור פ' כל אשר תמצא ידך לעשות בכחך עשה, &lt;פי'&gt; שיעשה המעשה שעושה בכל איבריו עפ\"י הדעת ובזה יש התפשטות הדעת בכל איבריו. כך בכללות העולם יש צדיק כמו משה סוד הדעת, ושאר אנשים שבדורו כשהם בחיבור א' עמו נקראו כולם דור דעה, והוא סוד תחיית המתים ומשיח. משא\"כ ההיפך כשיש פירוד ביניהם נפרדו מהחיות ומהדעת, ואז הוא סיבת הגלות מצרים ופרעה סוד העורף אחורי הדעת. ובזה תבין במ\"ש כל המבזה ת\"ח כו'. אכן נודע הדבר, שהלשינו על משה ונפרדו מהדעת, וזה סיבת הגלות. ובזה יבואר מה ששמעתי פי' הפ' יכרת ה' כל שפתי חלקות, &lt;פי'&gt; ע\"י שפתי חלקות כורת ח\"ו ומפריד בין ב' אותיות ה\"ו ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ יתרו סב</b>,<b> ב (רכב</b>,<b> ב)</b>\n<i>כל אשר תמצא גו'</i> – קהלת ט, י. <i>משה סוד הדעת</i> – זח\"ב רכא, א. ע\"ח שער הכללים פ\"י. <i>דור דעה</i> – ויק\"ר ט, א. פס\"ר פ' פרשת פרה אות ט. <i>הגלות מצרים ופרעה כו'</i> – פע\"ח שער חג המצות פ\"א. לקו\"ת להאריז\"ל פ' וישב. <i>כל המבזה כו'</i> – שבת קיט, ב. <i>אכן נודע הדבר</i> – שמות ב, יד. <i>שהלשינו על משה כו'</i> – שמ\"ר א, לא. תנחומא שמות י. <i>וזה סיבת הגלות</i> – שמ\"ר א, ל. <i>יכרת ה' גו'</i> – תהלים יב, ד.\n----- הערות וציונים -----\n<i>משה סוד הדעת</i> – ראה שער הפסוקים פ' שמות ד\"ה ויקם (קד, א) דמשה בחי' הדעת עצמו דז\"א, ושם (קה, ב) משה היה שרש הדעת עצמו בבחי' הטוב של הקדושה וענפיו הם בני ישראל שיצאו ממצרים הנקראים דור דעה. והא דמבואר בכ\"מ בינה איהי דמשה, ראה זח\"ג רכג, ב א\"ה בינה דרגא דילך ואמאי אוקמוהי ונתן ההוד למשה וכו'. ובשער הפסוקים פ' עקב ד\"ה ויאמר ה' אלי (קצז, א) משה מסוד הדעת ומסוד הבינה כנודע, וביאורו הוא כי הנה יסוד דבינה הוא דעת דזעיר שהוא המח האמצעי . . וסימן בי\"ד משה בינה יסוד דעת. וכן בלקו\"ת ושעה\"פ פ' בלק ועוד.\n<i>דור דעה</i> – ראה בהערה לפני זו, וע\"ח שער הכללים פי\"א, ושם של\"ב פ\"א.\n<i>והוא סוד תחה\"מ ומשיח</i> – ראה לעיל סי' קנח. וראה בצ\"פ כאן (לפני סימן זה): דכתב בפע\"ח הלכות פסח (פ\"א) סוד גלות מצרים אצל פרעה וז\"ל כי פרעה ומצרים הם כנגד העורף העליון שהוא אחוריים של הדעת העליון כו' יעו\"ש, והגואל הוא משה סוד הדעת, והענין דשמעתי ממורי ענין תחה\"מ ומשיח הוא סוד הדעת וכו' ודפח\"ח.\n<i>ופרעה סוד העורף כו'</i> – ראה לעיל סי' קי-ב ובהערות שם.\n<i>סיבת הגלות</i> – ראה תוי\"י ס\"פ וישלח (כח, א): ששמעתי ממורי כי ענין גלות מצרים היה שחסר מהם הדעת שידעו להכריע שיש בורא א' המחדש בטובו תמיד מעשה בראשית וכו' עד שבא משה בחי' הדעת וע\"י נסים שעשה נתפרסם בעולם שיש בורא א' המחדש תמיד, אמנם בחי' דעת זה היה דעת דנוקבא, אך דעת דדכורא יתגלה לעתיד בימות המשיח (וכו' עיי\"ש)."]]],[300010449,"שעא\n\n<b>שמעתי</b> <i>ממורי</i> <span data-k=\"sm\">[זלה\"ה]</span> ענין גזירה שוה, אם שוה רק בבחי' א' יליף זה מזה וכו', ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ יתרו סח</b>,<b> סע</b>\"<b>ד (רמה</b>,<b> א)</b>\n----- הערות וציונים -----\nבצ\"פ ממשיך: והכי נמי אם אין המוני עם רק בבחינה א' להת\"ח אז יוכל להתחבר עמו ולהדבק בו. ועיי\"ש בפ' וארא כו, סע\"ג (קו, א): דשמעתי בשם מורי זלה\"ה ענין התחברות להעלותו אם יש בו מדה א' שוה לו עכ\"פ אז יוכל לחברו ולהעלותו מצד גז\"ש אם יש לו שיווי בצד א' גם שבשאר הצדדים אינו שוה לו כמו שכתב הרמב\"ם, משא\"כ כשהוא ב' הפכים ממש א\"א להעלותן ודפח\"ח. וראה מזה לעיל סי' קפח (שם הזכיר מה שרמז לרמב\"ם)."]]],[300010450,"שעב\n\n<b>שמעתי</b> <i>ממורי</i> <span data-k=\"sm\">[זלה\"ה]</span> ושבית שביו כו', א\"כ מרצון המן יש לידע איך לעשות בחישוק וזריזות רצון מרדכי, והבן.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ יתרו סט</b>,<b> ריש ע</b>\"<b>ד (רמח</b>,<b> ב)</b>\n<i>ושבית שביו</i> – כי תצא כא, י.\n----- הערות וציונים -----\nראה לעיל סי' קלד ורנד."]]],[300010451,"שעג\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> זלה\"ה שיש יחודים בדיבור, בין בדיבור תורה ותפלה ובין בדיבור עם חבירו בשוק, ויוכל לחברו ולהעלותו לכ\"א לפי מדריגתו, יש ע\"י דיבור דקדושה ויש ע\"י דיבור חול שיש בו כ\"ב אותיות כו'. <span data-k=\"sm\">[וגם שמעתי </span><i>משמו</i><span data-k=\"sm\"> זלה\"ה]</span> שאם אדם מוכרח לדבר עם חבירו או לשמוע מחבירו דברים בעלמא, יכול להעלותו ג\"כ ע\"י שיתן דעתו כי השמיעה הוא ע\"י הנשמה שהיא חלק אלוה ממעל ויכוין לחברה ולייחדה וכו'.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ יתרו עו</b>,<b> א (רסז</b>,<b> א)</b>\n<i>חלק א</i>-<i>לוה ממעל</i> – איוב לא, ב.\n----- הערות וציונים -----\nבמקורו מבאר ע\"פ תורה זו לשון המשנה ראוה מדברת עם אחד בשוק (כתובות יג, א) – ועיין מזה לעיל סי' לב-ב ובהערות לסי' שסב, ולשון המשנה ארבעים חסר אחד (שבת עג, א) – ועיין מזה לעיל סי' יז.\n<i>שיש יחודים בדיבור כו'</i> – ראה צוה\"ר סוף סי' קיא. ולהעיר מלעיל סי' ח ושסו, ומדל\"י סי' צח (קז).\n<i>ובין בדיבור עם חבירו כו'</i> – ראה לעיל סי' צג-ג ושב-א והנסמן שם בהערות."]]],[300010452,"שעד\n\n<b>שמעתי</b> <i>ממורי</i> כי בשבת יש &lt;למעט הלימוד&gt; <span data-k=\"sm\">[כמעט אין ללמוד]</span> רק לייחד והבן.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ משפטים עז</b>,<b> ד (רעג</b>,<b> ב)</b>\n----- הערות וציונים -----\nראה פע\"ח שער השבת סוף פכ\"א דטוב לקרות בשבת קבלה לבד כמו שהיו נוהגים הקדמונים, והטעם וכו' עיי\"ש (והובא בנגיד ומצוה בסוף ע' מוסף לשבת, ושם עוד ס\"א). שער הפסוקים תהלים סי' ק. וראה בהקדמת ס' בפ\"י ד, סע\"ג: ובשבת יעסוק בחכמה אמיתית כמ\"ש המקובלים, והיא י' מהשם, ואז מייחד ב' אותיות ראשונות וממשיך לאות (ו) [ו\"ה] ב' אותיות אחרונות מהשם ונעשה יחוד שלם, והוא שביתא ונייחא (ועיי\"ש ההמשך). וכ\"כ בתוי\"י פ' בהר קט, ע\"ד ושם פ' שופטים קפג, ריש ע\"ד עיי\"ש. ולהעיר מלעיל סי' קל."]]],[300010453,"שעה\n\n[<b>בשם</b> <i>מורי</i><span data-k=\"sm\"> זללה\"ה]</span> הני תרי בדחי שהם בני עולם הבא שידעו להרים ולהניף כל בני העולם כו', ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ משפטים פג</b>,<b> רע</b>\"<b>א (רצא</b>,<b> ב)</b>\n<i>הני תרי כו'</i> – תענית כב, א.\n----- הערות וציונים -----\nראה לעיל סי' לז, נח, צג-ג וערב."]]],[300010454,"שעו\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> זללה\"ה פי' פ' הנה החשך יכסה ארץ וגו', ועל כל פשעים תכסה אהבה. כי היסוד הוא עיקר ושורש הבנין, ואם היסוד רעוע כל הבנין נופל. כך האדם, אם היסוד רעוע, כמו אדם שיש לו גסות הרוח, אז כל מעשיו הטובים נבנו על יסוד רעוע. משא\"כ ביסוד נכון גם השנאה ופשע תכסה אהבה. ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ תרומה צ</b>,<b> א (שיח</b>,<b> ב)</b>\n<i>הנה החשך גו'</i> – ישעי' ס, ב. <i>ועל כל פשעים גו'</i> – משלי י, יב.\n----- הערות וציונים -----\nראה ר\"ח שער היראה פ\"ד קרוב לסופו: ובלי ספק הגאוה שורש לכל מדות הרעות כמו שנאריך בע\"ה בשער שלו (שער הענוה רפ\"ב). ובלקו\"ת לאדה\"ז שה\"ש יד, סע\"ד שבחי' גסות נק' אבי אבות הטומאה שהוא מקור כל התאוות. וראה צ\"פ ס\"פ יתרו עו, סע\"ד: וכן ביאר מורי זלה\"ה מופת מובהק שהגאוה קשה מן החטא, כי בכל הטומאות והחטאים כתיב השוכן אתם בתוך טומאתם (אחרי טז, טז. תו\"כ עה\"פ. ספרי נשא סוף פיס' א' ומסעי ס\"פ קסא. יומא נו, ב), משא\"כ בגסי רוח דרשו בש\"ס פ\"ק דסוטה (ה, א) אין אני והוא יכולין לדור בעולם שנאמר גבה עינים ורחב לבב לא אוכל (תהלים קא, ה) ודפח\"ח."]]],[300010455,"שעז\n\n<b>שמעתי</b> <i>ממורי</i> <span data-k=\"sm\">[זללה\"ה]</span> כי התענוג שיש לבעל עבירה נמשך מן הניצוצות של מלאכים קדמאין שנפלו בשבירה בקליפות נגה וכו', ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ תרומה צ</b>,<b> ב (שיט</b>,<b> א)</b>\n----- הערות וציונים -----\nראה צ\"פ ר\"פ שמות ב, סע\"ג: בכל תענוג הגשמי הוא תענוג הגשמי לפי שיש בו ניצוץ רוחני מתענוג העליון וכאשר שמעתי ממורי כי גם תענוג העבירה ר\"ל נמשך בסוד השבירה בו מניצוץ תענוג רוחני ודי בזה, באופן שאין לך דבר בעולם שהוא גשמי ובתוכו יש חיות רוחני, וזה הוא דנשקי ארעא ורקיע אהדדי (ב\"ב עד, א) וכו'. ועיין כתונת פסים פ' בהעלתך לה, ריש ע\"ב: ששמעתי ממורי פי' הש\"ס זדונות וכו' (יומא פו, ב), וטעם שנק' חטא כי כבודו ית' מלא כל העולם כביכול, גם המקום החטא והתענוג של החוטא נמשך מתענוג העליון וכו', והנה יש מדה הנקרא המדה אשר ממנו יתברך מתפשט בכל הנבראים אדם ובהמה וחיות ושרצים וכו' כאשר החוש מעיד ע\"ז, ובכל אחד מהחמדה יש בחי' הויה אדני, כי החמדה קודם שנפעל הוא הויה ואחר הפעולה נק' אדני, הרי חי\"ת מן חטא שהם ח' אותיות של ב' שמות הנ\"ל, ובתוכו יש טוב הגנוז בתוכו הרי אות ט' מן חטא, ואות א' מובלע בו הרי חטא. והנה יש י\"ג מדות שהתורה נדרשת בהם ואחד מהם ק\"ו וכו', והנה ע\"י התעוררות זו החמדה למטה נתעורר מדה זו למעלה בק\"ו וכולי, רק הקליפה של החטא היא מסך מבדיל ומפסיק מלהתעורר הטוב למעלה כ\"א אחר ששב בתשובה ונסתלק חלק הרע והקליפה ונשאר רק טוב הגנוז, ואז נתעורר גם הטוב שלמעלה, ולכך זדונות נעשו כזכיות, ובלבד שהיה הזדון לתאבון ולא להכעיס אז נעשו זכיות ודפח\"ח. (ועיין מזה בדמ\"א פ' עקב ד\"ה ויש להבין: ששמעתי מאא\"ז זללה\"ה שלכך מובלע א' בתוכו [בחטא] להודיע ששם ג\"כ שורה אלופו של עולם ב\"ה מובלע ומכוסה, כי בלעדו לא ירים איש את ידו לעשות קטן וגדול). ולהעיר מצוה\"ר סי' קמא. לקו\"ת לאדה\"ז, דרושים לר\"ה סא, סע\"ג ואילך. ועיין היטב לעיל סי' קפח מש\"כ בהערות ד\"ה לפי זה."]]],[300010456,"שעח\n\n<b>שמעתי</b> <i>ממורי</i> <span data-k=\"sm\">[זללה\"ה]</span> כל תורה שאין עמה מלאכה סופה בטילה וגוררת עון כו', כי התורה והתפלה צריך שיהיה עם המוחין, ואחר שנסתלקו המוחין בסיום תורה ותפלה בא הקטנות שהוא הכעס והמחלוקת ולה\"ר, ולכך יעסוק אז במלאכה כו'. וז\"ש וכל תורה שאין עמה מלאכה וכו' וגוררת עון &lt;וכו'&gt;, ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ תרומה צג</b>,<b> סע</b>\"<b>א (שכט</b>,<b> א)</b>\n<i>כל תורה כו'</i> – אבות פ\"ב מ\"ב.\n----- הערות וציונים -----\nראה דמ\"א פ' תשא ד\"ה ואמלא: גלוי וידוע בשם אא\"ז זללה\"ה שאחר התפלה שאדם מתפלל צריך ליזהר במעשיו כי עלול הוא ליפול ח\"ו לכעס או לשאר דברים שאינם מהוגנים, והיינו אם מתפלל במדת יראה נופל מזה אח\"כ בכעס חלילה וחס, ואם מתפלל במדת אהבה גדולה יכול לבוא לפעמים אח\"כ לאהבה שאינה צריכה, ומזה תבין בכל מדה ומדה, ועצה היעוצה בזה הוא לסמוך תיכף אחר התפלה לד\"ת או למלאכה כו'. ראה לעיל בהערות לסי' שסב, ומה שהבאתי שם מס' כתונת פסים."]]],[300010457,"שעט\n\n<b>שמעתי</b> <i>ממורי</i> <span data-k=\"sm\">[זללה\"ה]</span> עד שדרשה בן זומא וכו', כי הדרשה משבר הקליפות <span data-k=\"sm\">[וכו']</span>, ודפח\"ח. <span data-k=\"sm\">[והענין כי כל ספק וקושיא הוא קליפה, וע\"י התירוץ משבר הקליפות כמבואר בכתבי האר\"י זלה\"ה ענין לימוד הלכה וקשוטי הכלה יעו\"ש]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ תרומה צג</b>,<b> סע</b>\"<b>ב (שכט</b>,<b> ב)</b>\n<i>עד שדרשה כו'</i> – ברכות יב, ב. <i>וכמבואר בכתבי האר\"י זלה\"ה</i> – לקו\"ת וטעה\"מ פ' ואתחנן ד\"ה תועלת אל העיון וד\"ה סוד העיון. שער המצות, פ' ואתחנן. פע\"ח שער הנהגת הלימוד.\n----- הערות וציונים -----\nנראה דקאי על רישא דמשנה אמר ראב\"ע כו' ולא זכיתי כו' עד שדרשה בן זומא כו' ר\"ל ששבר הקליפות ואז זכה ראב\"ע כו'. שוב ראיתי שכן הוא בתוי\"י ס\"פ וישלח בהמשך לדברי הבעש\"ט המובאים בהערות לסי' שע.\n<i>כל הספיקות הוא קליפה</i> – להעיר מלקמן בהוספות ריש סי' קיח (ומש\"כ שם ברזל ע\"ה בגי' עמלק . . בגי' ר\"מ כו', ראה אוה\"ת להצ\"צ פ' תצוה סוף ע' א'תרצא, ובהמשך שם (ע' א'תש ואילך) שעסק התורה מכניע ומשבר המחיצה של ברזל כו'). ולהעיר מר\"מ זח\"ג כז, ב, ושם קכד, ב (מבואר בתניא, אגה\"ק סי' כו), ותקו\"ז בסופו ת\"ט קמז, א."]]],[300010458,"שפ\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; <span data-k=\"sm\">[דשמעתי]</span> פי' המשנה <span data-k=\"sm\">[פ\"ג דשבת]</span> ר' שמעון אומר מטלטלין נר חדש כו' כל הנרות מטלטלין <span data-k=\"sm\">[חוץ מן הנר הדולק בשבת. והוא דנשמת אדם קרויה נר, שנאמר כי נר ה' נשמת אדם, וחז\"ל דרשו נרך בידי וכו']</span>. ובזוהר אמרו כי בשבת יוצאים כל הנשמות מהגיהנם חוץ ממחללי שבת <span data-k=\"sm\">[וכו' יעו\"ש]</span>. ובזה יובן מטלטלין נר חדש, ר\"ל נשמה <span data-k=\"sm\">[חדשה]</span> הקרוי נר שלא נתלכלכה בצואת עונותיו, מטלטלין ומוציאין אותה מגיהנם בשבת, אבל לא ישן שנתיישן בעונותיו. ר' שמעון אומר כל הנרות מטלטלין חוץ מן הנר הדולק בשבת, שמחלל השבת שדולק נשמתו בגיהנם ג\"כ בשבת, מדה כנגד מדה. ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ תרומה צג</b>,<b> ג (של</b>,<b> א)</b>\n<i>פ\"ג דשבת</i> – מד, א. <i>דנשמת אדם קרויה נר</i> – שבת ל, ב. <i>כי נר ה' גו'</i> – משלי כ, כז. <i>נרך בידי</i> – שמ\"ר לו, ג. <i>ובזוהר אמרו כו'</i> – זח\"ב קנ, סע\"ב ואילך.\n----- הערות וציונים -----\nבמקורו לא נזכר הבעש\"ט."]]],[300010459,"שפא\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> זלה\"ה בשם כתבי הרמב\"ם שהשיב תשובה למדינה א' שכפרו בתחיית המתים, ותשובתו נוצחת להם, כי השכל נעשה מברירות הדמים כו' יעו\"ש. והנה הר\"מ מקוצי חולק על הרמב\"ם ומנה בין הלאוין אזהרה לגסי הרוח <span data-k=\"sm\">[כו']</span>, כי נגלה אליו האלקים בחלום &lt;כו'&gt; כי הזכירה כו' וההיפך השכחה כו' יעו\"ש. וביאר הוא, <span data-k=\"sm\">[כי]</span> כאשר יש עכירות בדם אז האדם הוא בבחינת אחוריים, גי' תשכ\"ח, כי הזכירה נמשך משמות זכור, והשכחה מאחוריים דאו\"א, גי' תשכ\"ח, כמ\"ש ביחודים. וכמו שהוא בפרטות אדם א' כך הוא בכללות, שנמשך הגלות מהשכחה, ומהזכירה בא הגאולה &lt;זכור ה' חיבת ירושלים כו' אתה תקום תרחם כו'&gt;. ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>צ</b>\"<b>פ תרומה צו</b>,<b> סע</b>\"<b>ג (שמא</b>,<b> א)</b>\n<i>יעו\"ש</i> – לעיל סי' קפו. <i>הר\"מ מקוצי כו'</i> – סמ\"ג בהקדמה. שם מל\"ת סד. <i>כמ\"ש ביחודים</i> – שער היחודים שלהי פי\"ז. שער המצות ר\"פ ואתחנן. <i>זכור ה' כו'</i> – סדר סליחות ד\"ה זכור רחמיך. <i>אתה תקום גו'</i> – תהלים קב, יד.\n----- הערות וציונים -----\n<i>בשם כתבי הרמב\"ם כו'</i> – ראה לעיל בהערות לסי' קפו.\n<i>כאשר יש עכירות בדם כו'</i> – ראה הנסמן לעיל בסוף ההערות לסי' קפו.\n<i>הזכירה כו' והשכחה כו' כמ\"ש ביחודים</i> – רג\"כ שער המצות ר\"פ ואתחנן. ע\"ח שער הכללים פי\"א, ושם ש\"ט פ\"ב ושט\"ו פ\"ו.\n<i>שנמשך הגלות מהשכחה כו'</i> – ראה לעיל סי' שע ובהערות שם. להעיר מיומא לח, ב כל המשכח תלמודו כו'."]]],[300010460,"שפב\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> כשרוצין ליפרע העונש אזי נוטלין ממנו מדריגת הבטחון. ע\"כ ראוי להתפלל לפניו ית' שיתחזק בבטחון בו <span data-k=\"sm\">[וכו' ודפח\"ח]</span>. וזהו והאמין בה' ויחשבה לו צדקה, ר\"ל כשזכה אברהם למדריגות האמנה ובטחון בה' אז ויחשבה לו צדקה, כאלו זכה לזה מצד הצדקה ולא שראוי לכך <span data-k=\"sm\">[וכו']</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י משפטים נו</b>,<b> ב (רח</b>,<b> ב)</b>\n<i>והאמין בה' גו'</i> – לך לך טו, ו.\n----- הערות וציונים -----\nדברי הבעש\"ט כבר הובאו לעיל סי' קיג-א. על כללות התוכן להעיר מדמ\"א פ' עקב ד\"ה כל מדוי מצרים: שאמר אא\"ז זללה\"ה דאין הקב\"ה שולח יסורים על האדם אא\"כ שולח אליו מקודם חולי מרה שחורה.\nוי\"ל על זה, בדרך אפשר, ע\"פ המבואר בשבט מוסר פי\"ד ד\"ה שש עשרה, מי שאינו בעל הבטחון תמיד הוא עצב כו' (וכן שם שלהי פ\"י מעוט הבטחה שבו גורם לו העצבות). וזה מבואר ע\"פ ס' ארחות צדיקים, שער השמחה: והבטחון א\"א בלא אמונה . . כי הבטחון והאמונה שותפים, אם אין אמונה אין בטחון כו' (עיין מזה בחובה\"ל שער הבטחון פ' ב-ג) המאמין בלב שלם והבוטח בעזר הצור הוא שמח לעולם כו'. ומבואר כ\"ז באורך בר\"ח שער האהבה פי\"ב עיי\"ש. ורג\"כ לעיל סי' רל."]]],[300010461,"שפג\n\n<b>להנצל</b> מיצה\"ר הם ג' דברים תפלה דורן ומלחמה, והוא להלחם נגד מ\"ז עד שיקשר כ\"א בשרשו בכל ג' קוין, ואז מקבל דורן זה של המ\"ז ונתקרבה אל הקדושה מאבינו שבשמים.<i>[ftnref_1_עט]</i>",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י ס</b>\"<b>פ ויחי לה</b>,<b> ד (קכט</b>,<b> א)</b>\n<i>מג' דברים שהתקין יעקב כו'</i> – תנחומא (הקדום) וישלח ו. וש\"נ. רש\"י וישלח ל, ט.\n----- שולי הגליון -----\n[ftn_1_עט]) <i>במקורו</i>: ולהנצל מיצר הרע הוא בא' מג' דברים שהתקין יעקב את עצמו נגד עשיו, לתפלה ולדורן ולמלחמה. ובארתי שם כי בתפלה יש דורן ומלחמה שהוא להלחם נגד מ\"ז עד שיקשר כ\"א בשרשו, כאשר קבלתי <i>ממורי</i> בכל ג' קוין וכו', ואז מקבל בדורן זה של המחשבה שהיא זרה ונתקרב בשרש הקדושה אל אבינו שבשמים וכו'.\n----- הערות וציונים -----\n<i>להלחם נגד מ\"ז עד שיקשר כו'</i> – ראה לעיל סי' לט ועיין שם בהערות וש\"נ.\n<i>בכל ג' קוין כו'</i> – ראה לעיל סי' צט וקנב-א, ובהערות שם."]]],[300010462,"שפד\n\n<b>כשעוסק</b> בתורה נק' איש, וכשיורד ומדבר עם המוני עם נק' אשה, וכשהוא מקבל בשמחה מעלה שני מדריגות אלו למעלה. וז\"ש אחור וקדם צרתני, כשהוא בסוד אחור ועולה למדריגה הנק' קדם מעלה גם מדריגות הנק' אחור.<i>[ftnref_1_פ]</i>",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י שמות לו</b>,<b> ב (קלד</b>,<b> ב)</b>\n<i>אחור וקדם צרתני</i> – תהלים קלט, ה.\n----- שולי הגליון -----\n[ftn_1_פ]) <i>במקורו</i>: כשהאדם במדריגה עליונה ועוסק בתורה ותפלה נקרא בסוד איש. משא\"כ כשיורד ממדריגתו במדריגת המוני עם נקרא אשה, וכשהוא מקבל זה בשמחה ואהבה לייחד אלו מדריגות ולהעלותן, כמו ששמעתי <i>ממורי</i> בסוד אחור וקדם צרתני, כשהוא בסוד אחור אח\"כ כשחוזר ועולה למדריגה הנקרא קדם מעלה גם אותן המדריגות הנקראים אחור, וזהו סוד אחור וקדם צרתני, ודפח\"ח.\n----- הערות וציונים -----\n<i>בסוד אחו\"ק צרתני</i> – ראה לעיל סי' קג וקלט ובהערות שם."]]],[300010463,"שפה\n\n<b>בימי</b> הבעש\"ט זלה\"ה הי' פעם א' עצירות גשמים, וראה אדם אחד הדיוט שצועק ומתפלל ואומר פסוק זה ועצר את השמים ולא יהיה מטר, ולא גער בו מפני שראה שתפלתו מקובלת למעלה. ואח\"כ כשכבר ירדו גשמים קראו ושאל אותו מה הי' דעתך בקראך זה הפסוק ועצר את השמים ולא יהיה מטר. א\"ל, ה\"פ ועצר לשון וסחט את השמים, ולא יהיה מטר למעלה כ\"א כל המטר ירד למטה, וכן תרגום ואסחט תרגומו ועצרית, והיוצא מזה כו'.",[["","","----- מקורות ומראה מקומות -----\n<i>ועצר את גו'</i> – עקב יא, יז. <i>ואשחט</i> – וישב מ, יא.\n----- הערות וציונים -----\nלהעיר משהש\"ר ב, ד עה\"פ הביאני גו' ודגלו עלי אהבה. זח\"ג פה, ריש ע\"ב. ספר חסידים סוף סי' יח. תוס' ע\"ז כב, ב ד\"ה רגלא. שו\"ת הרשב\"א ח\"א סי' תכג. וראה בריש לקו\"י סי' ד בשם הבעש\"ט. השוה הסיפורים בס\"ח (כ\"י פרמא) סי' ה-ו; לעיל סי' שיז ולקמן סי' שפו; ובקונ' תורת החסידות לאדמו\"ר מוהריי\"ץ ע' ו-ז."]]],[300010464,"שפו\n\n<b>פעם</b> א' היה שובת הבעש\"ט והיה בשבת בכפר אחד עם מנין שלו. ובהגיע עת השלש סעודות גם המחזיק הכפר קיבץ כמה אנשים הכפרים וישב ואכל ושתה עמהם בזמירות שירות ותשבחות, וראה הבעש\"ט זלה\"ה שהוא מקובל מאד למעלה. וקראו אחר הסעודה ושאל אותו, מאיזה טעם אתה עושה זה לבזבז כ\"כ על סעודה ג'. והשיב, הנה שמעתי העולם אומרים תצא נשמתי בין אנשים מישראל, והנה שמעתי שבשבת יש לכ\"א מישראל נשמה יתירה ובמוצאי שבת יצאה ממנו, ואמרתי גם אני תצא נשמה יתירה שלי בין אנשים מישראל, ע\"כ אני מאסף אנשים מישראל כו'. והנאו הדבר מאד.",[["","","----- מקורות ומראה מקומות -----\n<i>שבשבת כו' נשמה יתירה כו'</i> – ביצה טז, א.\n----- הערות וציונים -----\nראה הסיפורים לעיל סי' שיז ושפה."]]],[300010465,"שפז-א\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה פי'&gt; <span data-k=\"sm\">[</span><i>והבעש\"ט</i><span data-k=\"sm\"> אמר]</span> על מה שאמרו בזוהר שדנין את האדם בכל היכל והיכל ומגרשין אותו מההיכל, פירוש כי הדיבורים נקראים היכלות שהשכל שורה בהן, והאדם המתפלל הוא הולך מאות לאות ומתיבה לתיבה, וכשהוא אינו כדאי מגרשין אותו, דהיינו שזורקין לו מחשבה זרה, וממילא הוא בחוץ.\n<b>וזהו</b> וימלוך באדום בלע בן בעור, אדום נקרא התלהבות, האדם שמתפלל בהתלהבות &lt;לשון אדמה לעליון, דומיה תהלה, והבן&gt; ושולטת עליו מ\"ז נקרא בלע, לשון כריתה, בן, כשהוא מבין את זאת המ\"ז מה היא, בעור, מבער אותה, שמכחה בא להתלהבות הבורא ית' כידוע, ושם עירו, כלומר מפני מה נתעורר, עירו לשון התעוררות, דנהבה, שנותן אל דעתו ומשים אל לבו שזהו נתינת הדין, ר\"ל שדנין אותו.\n<b>וזהו</b> פירוש <span data-k=\"sm\">[איה סופר את המגדלים, דקשה איך המחשבה אין לה בושה לתפוס ולהאחז בתוך התפלה, אך התירוץ שהיא מביאה למדת גדלות, מחמת שרצונה לעלות למעלה להשי\"ת. וזהו סופר, שמזהיר את המגדלים, ר\"ל המחשבה זרה שע\"י בא לבחינת גדלות כנ\"ל </span>. . .<span data-k=\"sm\">]</span> כו'. הבה לנו עזרת מצר, שתהא העזרה באה מכח הצרה.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י שלהי סי</b>'<b> פד (צה)</b>; <i>הבה </i>. .<i> הצרה</i>:<b> שם סוף סי</b>'<b> פה (צה)</b>\n<i>בזוהר</i> – זח\"ב רמה, ב. זח\"א רלד, א. <i>וימלוך באדום גו' ושם עירו דנהבה</i> – וישלח לו, לב. <i>אדמה לעליון</i> – ישעי' יד, יד. <i>דומי' תהלה</i> – תהלים סה, ב. <i>איה סופר גו'</i> – ישעי' לג, יח. <i>הבה לנו גו'</i> – תהלים ס, יג.\n----- הערות וציונים -----\nראה מדל\"י סי' ד (ג).\n<i>שזורקין לו מ\"ז</i> – להעיר מתניא, אגה\"ת פ\"ז. דרך חיים לאדה\"א ספ\"ג ושם פ\"ד.\n<i>אדום נקרא התלהבות</i> – נראה דר\"ל שבהתלהבות פניו מאדימים. ולחדודי להעיר מתקו\"ז ת\"ע קכט, רע\"א ב\"נ דאנפוי סומקין דיראי אלקים, ושם דיראי אלקים מסטרא דלבא.\n<i>עירו לשון התעוררות</i> – תיב\"ע לבמדבר כא, כז. וראה צוה\"ר סו\"ס קלח. מדל\"י סו\"ס קעז (קפב).\n<i>דנהבה </i>. .<i> נתינת הדין</i> – ר\"ל לשון דין-הבה, כמו בזח\"ג קלה, סע\"א.\n<i>העזרה באה מכח הצרה</i> – ראה לקמן בהוספות סי' ט-י. ובפי' הבעש\"ט להודו עה\"פ ויצעקו גו' ממצוקותיהם יצילם. ומפורש כן בתנחומא ס\"פ וישב. וראה דבש לפי להחיד\"א מע' ת אות כא."]]],[300010466,"שפז-ב\n\n<b>בתפלה</b> צריך לשים כל כחו בהדיבורים, וילך כך מאות לאות עד שישכח מגופניות, ויחשוב שהאותיות מצטרפים ומתחברים זה עם זה, וזהו תענוג גדול. דמה אם בגשמיות הוא תענוג גדול, מכ\"ש ברוחניות, וזהו עולם היצירה. ואח\"כ יבוא לאותיות המחשבה ולא ישמע מה שהוא מדבר, וזהו בא לעולם הבריאה. ואח\"כ הוא בא למדת אי\"ן שנתבטלו אצלו כל כוחותיו הגשמיים, וזהו עולם האצילות, מדת חכמה.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י פז (צז)</b>\n----- הערות וציונים -----\nראה לעיל סי' רפא-א.\n<i>למדת אין </i>. .<i> מדת חכמה</i> – ראה מדל\"י סי' ז (ח) ורג (ריג). ועיין קיצורים והערות לתניא להצ\"צ, פי\"ח אות ז.\n<i>למדת אין שנתבטלו אצלו כו'</i> – להעיר ממדל\"י סו\"ס פו."]]],[300010467,"שפח\n\n<b>בשם</b> <i>הבעש\"ט</i> זלה\"ה, דאם אדם בא לסכנה וצריך לנס אזי יתן ח\"י גדולים בשביל נרות לבית הכנסת ויאמר בפה מלא: אני מנדר אותן ח\"י גדולים לנרות בשביל נשמת רבינו מאיר בעל הנס, אלקא דמאיר ענני אלקא דמאיר ענני אלקא דמאיר ענני, ובכן יהי רצון מלפניך ה' או\"א [אבותינו] כשם ששמעת את תפלת עבדך מאיר ועשית לו ניסים ונפלאות כן תעשה עמדי ועם כל ישראל עמך הצריכים לנסים נסתרים ונגלים אכי\"ר.",[["","","----- מקורות ומראה מקומות -----\n<b>?</b>\n<i>אלקא דמאיר כו'</i> – ע\"ז יח, ב.\n----- הערות וציונים -----"]]],[300010468,"שפט\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; כשמוכיח את הרבים ואינו כולל <span data-k=\"sm\">[את]</span> עצמו בתוכחתו אין עושה בהם רושם.\n<b>וכן</b> שמעתי &lt;ממורי הבעש\"ט&gt; <span data-k=\"sm\">[בשם </span><i>מורי</i><span data-k=\"sm\">]</span> בענין התפלה וכונתה ויחודים שצריך לקשר א\"ע בהם, וידוע שהאדם הוא עולם קטן ובהתעוררות דלמטה יתעוררו למעלה למעלה וישפיעו למטה עד מדריגת של אדם זה המכוין זה ומקבל השפעה <span data-k=\"sm\">[וכו']</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י קדשים צ</b>,<b> ד (שלח</b>,<b> א)</b>\n<i>שהאדם הוא עולם קטן</i> – תנחומא פקודי ג.\n----- הערות וציונים -----\n<i>כשמוכיח כו'</i> – ראה לעיל סי' קיג-ב ועיי\"ש בהערות.\n<i>בענין התפלה כו'</i> – להעיר מצוה\"ר סי' עה, ושם סי' קיח."]]],[300010469,"שצ\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; <span data-k=\"sm\">[אמר </span><i>הבעש\"ט</i><span data-k=\"sm\"> ז\"ל]</span> והכהנים הלוים, שכל שפע הבאה היא בב' בחינות, דהיינו אהבה שמחמתה משפיע לעולם התחתון, ובחי' צמצום לעולם היא השפע בעצמו שירדה מעולם העליון לשרות בעולם התחתון. וכן בצמצום הראשון הי' בחינת אהבה ובחינת צמצום הכל בפעם א' בלתי פירוד כלל, שאהבה שאהב את ישראל הוא בעצמו הצמצום &lt;כו'&gt; <span data-k=\"sm\">[כנ\"ל]</span> וד\"ל.\n<b>והנה</b> עי\"ז נתהוו כל העולמות, ואלולי זה לא היה יכול להתגלות אלהותו ית' בעולמות, ובלעדי אלהותו לא היו יכולין העולמות להתקיים רגע א', אך ע\"י הצמצום יכולים העולמות לסבול אלהותו ית' <span data-k=\"sm\">[וד\"ל]</span>. . .\n<b>והנה</b> אע\"פ ששם היה אהבה וצמצום הכל ברגע א' <span data-k=\"sm\">[וכנ\"ל]</span>, אעפ\"כ בעולם העשיה צריך לזה ב' כלים, כי כן דרך העולמות שמה שבעולם העליון הוא אחדות פשוט בעולם התחתון נראה בהתחלקות קצת, והוא מצד הכלים, אבל מצד החיות מה שהוא בעולם העליון הוא גם כאן אחדות פשוט, כמו המחשבה &lt;שהיא&gt; <span data-k=\"sm\">[שמחשבה]</span> בלב בלבד, ואח\"כ כשרוצה לגלותה ע\"י קול ודיבור יש לה כמה כלים נפרדים, ה' כנפי ראיה והמבטאים והקנה, ואח\"כ מדיבור לעשיה נראה הפירוד עוד יותר. ובאמת האיש &lt;החכם&gt; <span data-k=\"sm\">[הנלבב]</span> אינו עושה פירוד גם בעולם התחתון,\n<b>(&lt;כמ\"ש</b> <span data-k=\"sm\">ועתה ישראל מה ה' שואל מעמך כ\"א ליראה, פי' כי&gt; הנה תכלית הכל הוא היראה, כי אם אין יראה אין חכמה ספונה וחשובה כלל, ותכלית חכמה הוא יראה. הגם שצריך לעבוד הש\"י באהבה ויראה, א\"צ לתפוס כ\"א יראה, וממילא תשרה עליו אהבת הבורא ית', כי דרכו של איש כו' &lt;ובמדת יראה שהיא חכמה כלול הכל בלי שום פירוד&gt;).</span><i>[ftnref_1_פא]</i>\n<b>כיון</b> שרואה &lt;המשכיל&gt; שכל קומתו וחיותו של עולם התחתון הוא מהעליון, שאלולי עולם העליון היה עולם התחתון אפס מוחלט, א\"כ הוא דבוק לעולם העליון, וכמו ששם הכל אחדות פשוט בודאי גם כאן &lt;ע\"י מדת היראה&gt; <span data-k=\"sm\">[ואינו משגיח על הכלים הנראים נפרדים, כי הוא בבחי' מקבלים, אבל הדיבור בעצמו אחדות פשוט]</span>. ובזה מייחד עולם התחתון לעולם העליון, ויכול להעלות ממדריגה למדריגה עד ראש כולם, ששם הכל אחדות פשוט &lt;והבן&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י באמצע סי</b>'<b> צג (קב)</b>\n<i>והכהנים הלוים</i> – יחזקאל מד, טו.\n----- שולי הגליון -----\n[ftn_1_פא]) <i>שמתי כל קטע זה בחצאי עיגול ובאותיות קטנות דאין כאן מקומו</i>,<i> וצ\"ל בריש סי' שצא</i>, <i>עיי\"ש</i>.\n----- הערות וציונים -----\n<i>והכהנים הלוים כו'</i> – ראה זח\"ג מח, סע\"ב ליואי דאתו מהאי סטרא דדינא כו' כהנא דאתי מסטרא דחסד עלאה. ובזח\"א רמד, א כהנא וליואי מתערי לאתחברא שמאלא בימינא כו'.\n<i>שאהבה כו' בעצמו הצמצום</i> – ראה מדל\"י סי' א. וראה לקו\"י לא, א (יד\"א ר\"פ נב).\n<i>והנה עי\"ז כו' ואלולי זה כו'</i> – ראה תניא, שהיוה\"א פ' ד-ו.\n<i>שמחשבה בלב בלבד ואח\"כ כו'</i> – ראה תקו\"ז תי\"ג כח, א."]]],[300010470,"שצא\n\n[הנה <span data-k=\"sm\">תכלית הכל הוא היראה, כי אם אין יראה אין חכמה ספונה וחשובה כלל, ותכלית חכמה הוא יראה. הגם שצריך לעבוד הש\"י באהבה ויראה, אין צריך לתפוס רק יראה, וממילא תשרה עליו אהבת הבורא ית', כי דרכו של איש וכו'. ובזה]</span> הבחינה &lt;ש&gt;יבחין האדם את עצמו אם יש לו יראה בשלימות.\n<b>ונבין</b> זה ממשל, אם אחד מן השרים &lt;בשעה ש&gt;עומד לפני המלך, ויעבירו לפניו דבר שהוא הגדולה שבתאוות, שאם לא היה עומד לפני המלך היה מתאוה לתאוה ההוא, עם כל זה בעמדו לפני המלך <span data-k=\"sm\">[נתרחק תאוות ה-]</span> &lt;מרחיק את עצמו מלהתאות ל&gt;דבר ההוא, ודבר זה הוא מפני שכ\"כ גדלה עליו הבושה והאימה מפני המלך עד שאינו רואה א\"ע במדותיו, וכולם בטלו ממציאות נגד יראת המלך, כמו שאמרו רז\"ל למה צדיק דומה לפני הקב\"ה כנר לפני אבוקה, כמו שרגא בטיהרא לא מהני, ואינו עושה פעולתו כלל, כן מדותיהם אינם עושים שום פעולה בתאות העולם, כי תמיד הם בטילים ממציאותם מיראת הקב\"ה.\n<b>&lt;וז\"ש</b> מה ה' שואל מעמך, שתהיה במדריגות מה, שאינו חומד ומתאוה לשום דבר, וע\"י מה תזכה לזה ע\"י כ\"א ליראה כו'&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י צב (קא)</b>\n<i>ועתה ישראל גו'</i> – עקב י, יב. <i>אם אין יראה כו'</i> – ע\"פ אבות פ\"ג מי\"ז. <i>דרכו של איש כו'</i> – קידושין ב, ב. <i>למה צדיק דומה כו'</i> – פסחים ח, א. <i>שרגא בטיהרא כו'</i> – חולין ס, ב. <i>מה ה' שואל גו'</i> – עקב י, יב.\n----- הערות וציונים -----\n<i>תכלית חכמה הוא היראה</i> – להעיר מברכות יז, א. עיין דרך חיים לאדה\"א בריש ההקדמה.\n<i>לעבוד הש\"י באהו\"י</i> – תקו\"ז ת\"י כה, ב, וראה לעיל סי' לו, לח-א, קל ושמט-ב.\n<i>א\"צ לתפוס כו' כי דרכו של איש כו'</i> – הובא ג\"כ במדל\"י סי' קי (קכב) ואו\"ת סי' נט וקפד (לקו\"י סי' קלה). ומבואר במדל\"י סי' רכא (רלג) כי יראה נק' שער, זה השער לה', שהיא נוקבא אשה יראת ה', והאהבה הוא דכר מרומז בפסוק זכר חסדו כו' (וכ\"ה בתניא פמ\"ג עיי\"ש). ולהעיר מזח\"ג קמה, ב עיי\"ש.\n<i>ממשל כו'</i> – ראה לעיל סי' שיד ובהערות שם.\n<i>וז\"ש מה כו'</i> – ראה לעיל סו\"ס שיד.\n<i>במדרגות מה שאינו חומד כו'</i> – שבחי' מה ה\"ה בחי' אי\"ן, והאי\"ן אינו מתאוה לשום דבר, כמבואר במדל\"י סו\"ס צא (ק), ושם סי' קעז (קפב) קרוב לסופו."]]],[300010471,"שצב\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי זה]</span> משל <span data-k=\"sm\">[</span><i>ממורי</i><span data-k=\"sm\">]</span>, לבן מלך שהיה בין אנשי הכפרים ובא לו אגרת שלומים מאביו ורצה לשמוח והיה בוש וירא מאנשי הכפר, וצוה לתת להם יין <span data-k=\"sm\">[שרף]</span> והם שמחו בשמחתן והוא שמח בשמחת אביו. כך החומר והצורה של אנשי סגולה <span data-k=\"sm\">[וכו', ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י נשא קכ</b>,<b> סע</b>\"<b>ב (תנא</b>,<b> א)</b>\n----- הערות וציונים -----\nראה לעיל סי' קז ובהערות שם, וכן המובא בהערות לסי' שח."]]],[300010472,"שצג\n\n<b>&lt;מהבעש\"ט&gt;</b> במדרש <span data-k=\"sm\">[אחד בפרשת קרח שאמר שם]</span> מה ראה קרח לחלוק על משה פרה אדומה ראה &lt;ותמוה&gt; <span data-k=\"sm\">[וצריך להבין זה] </span>. . .\n<b>&lt;ופירש</b> בשם&gt; <span data-k=\"sm\">[נודע מ\"ש]</span> <i>הבעש\"ט</i> זללה\"ה ששאלוהו &lt;תלמידיו&gt; על ענין פרה אדומה היכן &lt;הוא רומז במצוה זו&gt; <span data-k=\"sm\">[היא רמוזה]</span> לבוא מזה לעבודת הש\"י תמיד, כמו &lt;שלימד הבעש\"ט זלה\"ה&gt; <span data-k=\"sm\">[שכתבתי לעיל]</span> שכל המצות הם נצחיות בשכל, אף שבפועל הם בזמן ובמעשה, בשכל הם תמיד נצחיים, כי התורה היא אלקותו ואלקותו נצחיות, כמו שאומרים כל תלמידי הבעש\"ט ז\"ל <i>בשמו</i> שכל התורה צריכה להמצא תמיד בכל זמן בדרך חכמה ושכל, שיש ללמוד מכל מצוה רמיזתה [. . .] ושאלוהו על פרה אדומה &lt;שאפי' בזמן בהמ\"ק לא נהג אלא לעיתים רחוקות, כמ\"ש במשנה מס' פרה מי עשאן כו', וגם מה&gt; שמטהרת טמאים ומטמאה טהורים.\n<b>והשיב</b> &lt;הבעש\"ט זלה\"ה&gt; שזהו ענין הגבהות, שמתחלה אם האדם מתנהג בדרך לא טוב והוא רחוק מהש\"י, התחלת תיקונו הוא מצד הגבהות ושלא לשמה, כמו להתפארות או עולם הבא, שזהו ג\"כ גבהות נסתר, שחושב שראוי שישלם לו הש\"י שכר על מעשיו, וחושב א\"ע שעושה איזה דבר למענו, ובאמת מצדינו בלתי כח הבורא מה אנו והאיך יתכן לקבל שכר. רק מתחלה א\"א לבוא לזה, וח\"ו ישאר בחצוניות, והותר לו לאחוז הגבהות והתפארות, ויעשה שלא לשמה ומתוך שלא לשמה יבוא לשמה, ובלשמה צריך להיות זך &lt;ונקי&gt; מכל סיג גבהות, כ\"א יתערב בו גבהות יתועב לפני ה'.\n<b>&lt;וזה</b> פי'&gt; <span data-k=\"sm\">[וכבר אמרתי בפ']</span> כי כל שאור וכל דבש לא תקטירו כו' קרבן ראשית כו' ואל המזבח לא יעלו <span data-k=\"sm\">[כו']</span>, &lt;פי'&gt; שהרמז בשאור ודבש לגבהות שהם מרתיחים ועולים כמו הגבהות שמגביה לב האדם &lt;והם דיני הקטנות, כי קטן רוצה להיות גדול, והדיוט קופץ בראש&gt;, ואמר הכתוב לא תקטירו ממנו אשה לה' &lt;לעבוד ע\"י גבהות&gt;, רק קרבן ראשית, ר\"ל ראשית ההתקרבות להש\"י מותר להיות בגבהות, אבל אח\"כ אל המזבח העליון לא יעלו לריח ניחוח לה', שאין נחת רוח לפניו ית' בגבהות ח\"ו, כי תועבת ה' כל גבה לב, אפי' בכל דהו <span data-k=\"sm\">[כידוע]</span>, נמצא הגבהות מטהרת הטמאים וכו'.\n<b>וענין</b> הזה הוא אפילו בצדיקים שכבר הם טהורים הוא נוהג תמיד ע\"ד הנ\"ל, שצריך להתקרב להש\"י בגבהות ושפלות, כי קודם שרוצה האדם להתקרב להש\"י ע\"י איזה מצוה &lt;גדולה&gt; ותורה או תפלה נמצא שעדיין הוא מרוחק ונקרא לערך הקירוב שיתקרב אח\"כ ע\"י העובדא שעתיד לעשות, נקרא עתה ע\"ד הכינוי טמא ומרוחק מהש\"י וא\"א להתקרב להש\"י אם לא יהי' לו גבהות, &lt;פי' דיש קטנות וגדלות בקדושה ולעומת זה בסט\"א, דבסט\"א קטנות היינו שהיצה\"ר אומר לו אתה אינך ראוי לעשות מצוה גדולה ועובדא כזו, וע\"כ שצריך&gt; שיגבה לבו בדרכי ה' &lt;כמרז\"ל במשנה למה נברא אדם יחידי, שצ\"ל עלי העולם עומד כו'&gt;, דאל\"כ יאמר לו יצרו שאתה אינך ראוי להתקרב אליו &lt;ע\"י עובדא זו&gt; כנ\"ל. לזה צריך להשתמש בגבהות ושיגבה לבו בדרכי ה' להתקרב דווקא <span data-k=\"sm\">[ובאמת הוא שפלות כמש\"ל, רק שדומה לגבהות נגד היצה\"ר שרוצה לפתותו מצד מצוה, שמצוה להיות שפל]</span>. וא\"כ ע\"י גבהות זה יטהר ויקרב א\"ע להש\"י כשיעשה העובדא של תורה או תפלה או מצוה. ואח\"כ בעת העובדא שעושה, או אח\"כ, צריך &lt;להשמר&gt; <span data-k=\"sm\">[להשתמט]</span> מכל צד גבהות, וישפיל א\"ע לפני הש\"י ולפני כל, &lt;וזהו קטנות שבקדושה&gt;, שלא ידומה לו שהוא גדול מחבירו כשיראה שהם אינם עושים עובדא זו <span data-k=\"sm\">[כי זהו גבהות, וכבר ידעת המוסר השכל </span><i>מבעל שם טוב</i><span data-k=\"sm\"> על זה וכתוב הדור הוא ומפורסם מבעש\"ט אצל כל איך לשוב אל לבו על זה, ואין צריך להאריך בזה]</span>.\n<b>נמצא</b> הגבהות בשעת מעשה המצוה שאז הוא נקרא טהור, ואז הגבהות מטמא טהורים ח\"ו, והגבהות נקרא פרה שמפרה ומגדיל דעת האדם, ואדומה מצד הקליפה. <span data-k=\"sm\">[ויש עוד טעם אחר ע\"ז למה הגבהות נקרא פרה אדומה, ולא רציתי להאריך]</span>. &lt;גם ע\"כ צריך להשליך אל תוך שריפת הפרה עץ ארץ ואזוב ושני תולעת, דפירש רש\"י מי שהתגאה כארז כו' ישפיל כאזוב ע\"ש, ופסק הרמב\"ם מקל של ארז ארכו אמה פי' כנ\"ל, שהגבורות וגדלות שיקח לעצמו לעשיית המצוה יהי' מדוד ומשוער באמת ובמדה, ואח\"כ תיכף ישפיל עצמו כאזוב&gt;, ונקרא זה פרה אדומה המטהרת את הטמאים וכו'.\n<b>ולזה</b> אמר במדרש מה ראה קרח לחלוק על משה, &lt;פירוש&gt; היכן ראה וחשב שיהיה למשה התנשאות ח\"ו הלא &lt;ידעו הכל ענותנותו&gt; <span data-k=\"sm\">[ידע שבודאי משה היה מוכתר בענוה]</span> עד שהעיד עליו הכתוב &lt;והאיש משה עניו מאד כו'&gt; <span data-k=\"sm\">[שהיה עניו מכל האדם אשר על פני האדמה, אפילו מכל השפלות הנקרא אדם אשר על פני האדמה, והוא היה עניו מאד יותר מהם]</span>, וא\"כ האיך חשדו בעון הגבהות <span data-k=\"sm\">[לצדיק גדול כזה]</span>, והא קרח פקח הי'. והשיב המדרש, פרה אדומה ראה, ר\"ל שראה שגם מדת הגבהות מוכרח להיות לכל צדיק לעבודת השי\"ת &lt;כו'&gt; <span data-k=\"sm\">[אפילו לצדיק גדול כנ\"ל]</span>, והיא מטהרת הטמאים כנ\"ל, וחשב &lt;קרח&gt; <span data-k=\"sm\">[שמשה טעה]</span> להיפך, כי מה שהתנשא הוא ואהרן להתקרב להש\"י לא היה מחמת הגבהות המותר המטהרת הטמאים והמרוחקים רק נתערבה בהם הגבהות האסור המטמאת הטהורים, ועי\"ז נשא לבם להתקרב להשי\"ת הוא ואהרן יותר מכל העם, ולהיות <span data-k=\"sm\">[מלך ולעשות הכל על פי מאמרו]</span> ולחשבו שזה הי' מצד גבהות.<i>[ftnref_1_פב]</i>\n<b>כי</b> באמת מרע\"ה היה בתכלית השפלות כמו שהעידה התורה עליו, ואעפ\"כ היה משתמש בגבהות בכמה דברים שעשה, שהיה מלך על ישראל <span data-k=\"sm\">[והנהיג א\"ע כמלך לעמו]</span>, רק <span data-k=\"sm\">[באמת]</span> היה זה לעבודת הש\"י להדריך העם לעבודת הש\"י, כי לא היה אפשר בלתי זה &lt;שהי' מצטרך&gt; שיהיה איש אשר יצא לפניהם, ואעפ\"כ לא רצה לקבל זה בתחלה <span data-k=\"sm\">[כנודע]</span> שסירב ואמר שלח נא ביד תשלח, עד שהכריחו הש\"י <span data-k=\"sm\">[שיהיה לו שררה זו]</span>. וקרח אעפ\"י שפקח היה, והיה לו רוה\"ק, עכ\"ז &lt;מחמת קנאה שהוא מצד הגבהות&gt; <span data-k=\"sm\">[ניצוץ קנאה נשארה בו ולא נטהר לבו ממנה בכל מכל כל, וקנאה היא מצד הגבהות, ואמונה לא היה לו שיעשה משה הכל מפי הש\"י, באמת מצדו בתכלית הענוה, רק]</span> חשב שמשה השתמש <span data-k=\"sm\">[בגבהות להיפך ולנגד האמת . . .]</span> &lt;בגבהות האסור.\n<b>וזה</b> שפרש\"י ע\"פ כי כל העדה כולם קדושים ומדוע תתנשאו כו' הרבה יותר מדאי לקחתם לעצמכם גדולה, שהוא אריכות וכפל לשון. אלא ה\"ק קרח, הן אמת שמותר להשתמש בגבהות בתחלת עשיית המצות ועובדא כו', אלא שחשד למשה בגבהות האסור גם לאחר עשיית המצות, וז\"ש יותר מדאי, וכן לקחתם לעצמיכם לא בשביל עבודתו ית'. וקרח&gt; על עצמו לא דימה שיהיה לו גבהות, רק חשב שמה שלבו נוטה לזה להיות נשיא הכל הוא מצד האמת, כנ\"ל בפסוק ויגבה לבו בדרכי ה', כי זאת הגאוה הותרה, ולא רצה לתלות הפחיתות בו בגבהותו &lt;האסור&gt;, ובאמת היושר של הגבהות המותר הוא במשה, רק חשב להיפך מפני הקנאה של הרע שהפך לבו לאמר על רע טוב ועל טוב רע, &lt;ולא האמין שמפי הדיבור עשה משה הכל. וזהו פרה אדומה ראה כנ\"ל&gt;.\n<b>ולפיכך</b> אמר משה <span data-k=\"sm\">[רבינו ע\"ה]</span> רב לכם בני לוי, באמת אני רואה שלא כאשר אתם סוברים שהגבהות שלכם הוא לש\"ש ושלי הוא מצד הרע, לא כן, כ\"א רב לכם <span data-k=\"sm\">[בני לוי]</span>, ר\"ל הגדולה נקרא רב, הרב הוא לכם למענכם, לא למען הש\"י. ולזה נחלקו &lt;קרח וכל עדתו&gt; כי זה דבר עמוק, וצריך לזה האמנה לתלות החסרון תמיד בו, ולחפוץ תמיד בכניעה ושפלות אפילו לדבר מצוה, פן ואולי הוא מצד הגבהות של הקליפה לעשות מצוה שאינה מוטלת עליו, ושיוכל ליעשות ע\"י אחר, ולא יחשוב שהוא ראוי לה יותר מחבירו, כי זהו גבהות. ואפילו משה לא היה חפץ להשתלח לישראל ואמר שלח נא ביד תשלח, אע\"פ שהוא דבר מצוה ללכת בשליחות השי\"ת וללמד לישראל תורה ואין לך מצוה גדולה מזה, אעפ\"כ חשב שאהרן ראוי לזה יותר, עד שהכריחו הש\"י לזה.\n<b>וצריך</b> האדם ללמוד מזה ולא להתקוטט בעבור מצוה שיש בה צד שררה ח\"ו ולברוח ממנה. ואם יהיה ראוי לה הש\"י יכריח כל העולם להזמינו לידו הנהגה זו וכדומה, וצריך לשקול דבר זה תמיד בשכל <span data-k=\"sm\">[עמוק]</span> &lt;זך וצדק&gt; <span data-k=\"sm\">[וצדק וזך]</span>, ולשאול מהש\"י ע\"ז עזר שיעזרנו שלא &lt;יטנו&gt; <span data-k=\"sm\">[יסיתנו]</span> היצה\"ר בזה לצד ההיפך ח\"ו, רק ידריכנו הש\"י בדרך האמת והטוב.",[["","","----- מקורות ומראה מקומות -----\n<i>במדרש</i> . . <i>להבין זה</i>: <b>לקו</b>\"<b>י – יד</b>\"<b>א כד</b>,<b> ב (יד</b>\"<b>א רפכ</b>\"<b>ו) </b><i>נודע מ\"ש הבעש\"ט</i> . . <i>מצד גבהות</i>: <b>שם כה</b>,<b> סע</b>\"<b>ב עד ריש ע</b>\"<b>ד (שם פל</b>\"<b>ב) </b><i>כי באמת</i> עד גמירא: <b>שם כד</b>,<b> שלהי ע</b>\"<b>ד ואילך (שם פ</b>\"<b>ל)</b>\n<i>שכתבתי לעיל</i> – לקו\"י-יד\"א כד, א (פכ\"ד). <i>מס' פרה</i> – פ\"ג מ\"ה. <i>שמטהרת טמאים כו'</i> – תנחומא (הקדום) חקת ד. כג. מדרש אגדה ר\"פ חקת. וש\"נ. <i>ויעשה שלא לשמה כו'</i> – פסחים נ, ב. <i>כי כל שאור גו'</i> – ויקרא ב, יא. <i>שהרמז בשאור ודבש כו'</i> – פס\"ז ויקרא ב, יא. ספר החינוך מצוה קיז. <i>והדיוט כו'</i> – מגילה יב, ב. <i>תועבת ה' גו'</i> – משלי טז, ה. <i>אפילו בכל דהו</i> – סוטה ה, א. רמב\"ם הל' דעות פ\"ב ה\"ג. <i>שיגבה לבו בדרכי ה'</i> – ע\"פ דה\"ב יז, ו. <i>למה נברא כו'</i> – סנהדרין לז, א. <i>להשליך אל תוך כו'</i> – ע\"פ חקת יט, ו. <i>דפירש רש\"י</i> – פרש\"י מצורע יד, ד מתנחומא מצורע ג. <i>ופסק הרמב\"ם כו'</i> – הלכות טומאת צרעת פי\"א ה\"א. <i>והאיש משה גו'</i> – בהעלתך יב, ג. <i>קרח פקח הי'</i> – במ\"ר יח, ח. תנחומא קרח ה. <i>שהיה מלך על ישראל</i> – זבחים קב, א. תנחומא בהעלתך ט. שם קרח א. זח\"ב קנד, א. <i>שלח נא גו'</i> – שמות ד, יג. <i>וקרח כו' והי' לו רוה\"ק</i> – במ\"ר יח, ח ובפי' מהרז\"ו שם. <i>כי כל העדה כולם גו'</i> – קרח טז, ג. <i>ויגבה לבו גו'</i> – דה\"ב יז, ו. <i>רב לכם בני לוי</i> – קרח טז, ז.\n----- שולי הגליון -----\n[ftn_1_פב]) <i>במקורו ממשיך כאן</i>: ולא האמין שמפי הדיבור עשה הכל, ולדון את משה לכף זכות, שחשב שמשה טעה וסבר שזה הגבהות הוא לש\"ש, ובאמת הוא שלא לש\"ש רק מצד גבהות הרע, ועליו חשב להיפוך שהוא מצד הטוב, הכל מפני חסרון האמונה וחסרון טהרת הלב, מקנאה וכבוד. וזהו פרה אדומה ראה, והבן היטב כי הוא דבר עמוק וא\"א לפרש בכתב היטב רק להבין בעומק הלב.\n----- הערות וציונים -----\n<i>כמו שאומרים כל תלמידי הבעש\"ט כו'</i> – ראה לעיל סי' קי-א ובהערות שם. ובהערות לסי' קטו.\n<i>מצדינו כו' והאיך יתכן לקבל שכר</i> – ראה לעיל סו\"ס קצג ובהערות שם. רג\"כ צוה\"ר סי' קלח.\n<i>קרבן ראשית ר\"ל ראשית ההתקרבות</i> – ראה ספר הבהיר סי' קט. זח\"ג ה, רע\"א ושם ע\"ב, ושם ח, א.\n<i>מותר להיות בגבהות כו'</i> – ראה לעיל סי' סח וקמה. צוה\"ר סי' צא.\n<i>דבס\"א קטנות היינו כו'</i> – ראה לעיל סי' קמה.\n<i>הגבהות מטהרת הטמאים וכו'</i> – להעיר שכבר הובא בתוי\"י ר\"פ אמור בשם הרה\"מ הרמ\"מ עיי\"ש.\n<i>שלא ידומה לו שהוא גדול מחבירו</i> – ראה צוה\"ר סי' יב ומח.\n<i>ואדומה מצד הקליפה</i> – להעיר מזח\"ב רלו, ב. מדרש אגדה ר\"פ חקת.\n<i>והנהיג א\"ע כמלך לעמו</i> – ע\"פ ההלכות המבוארות ברמב\"ם הלכות מלכים פ\"ב.\n<i>הגדולה נק' רב</i> – להעיר מפרש\"י קרח טז, ג.\n<i>חשב שאהרן ראוי לזה יותר</i> – ראה שמ\"ר ג, טז. תנחומא שמיני ג."]]],[300010473,"שצד\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> ביאור למה ע\"י מכות בכורות יצאו ממצרים כו', וכאשר לקו בכור השפחה והוסר הקליפה ממילא יצאו מהגלות. ולכך הוקדשו בכורי ישראל, שהוא השכל, אלא שא\"א שיהיו על מדריגה אחת כי החיות רצוא ושוב, בסוד קטנות וגדלות, וזהו שעשו עגל ולקח הש\"י תמורת הבכורים שבט לוי, כי אותיות לו\"י &lt;ל' וי&gt; וכו'. וזהו ג' בחינות קהת גרשון ומררי וכו'. וכאשר האדם בסוד הקטנות ויודע מזה, מוליד נשמות גרים, כי ג' הוא ג' קוין דרך ר' עלמין דכסופין &lt;ים מלכות&gt; וכו', ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>סו</b>\"<b>ס תוי</b>\"<b>י רא</b>,<b> רע</b>\"<b>א (תשכח</b>,<b> ב אות ו)</b>\n<i>וכאשר לקו כו' יצאו מהגלות</i> – זח\"ב לח, רע\"א. שם מח, ריש ע\"ב. <i>והוסר הקליפה</i> – ראה זח\"ב לז, סע\"ב ובמ\"מ שם. <i>ולכך הוקדשו בכורי ישראל</i> – רש\"י בא יג, ב. <i>החיות רצו\"ש</i> – יחזקאל א, יד. <i>ולקח הש\"י תמורת הבכורים כו'</i> – במדבר ג, יב. <i>ר' עלמין דכסופין</i> – זח\"א קכד, ב.\n----- הערות וציונים -----\nכבר הובא לעיל סי' קנד."]]],[300010474,"שצה-א\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה&gt; <span data-k=\"sm\">[בזוהר פנחס . . . דף ר\"מ ע\"א פתח ואמר שמעו אלי רודפי צדק מבקשי ה', רודפי צדק אינון דאזלין בתר מהימנותא, רודפי צדק ודאי אינון מבקשי ה' אי בעיתו למנדע מהמנותא ולאחדא להאי צדק לא תסתכלון בה כשאר בני עלמא דגרמו מיתה לגרמייהו על דא, אבל]</span> הביטו אל צור חוצבתם <span data-k=\"sm\">[וכו'. וכבר שמעתי פירוש מאמר זה </span><i>ממורי</i><span data-k=\"sm\"> הוא ענין כלל גדול בעבודת ה', וכבר נשכח ממני כולו. ונראה מכל מקום להעלות מעט קט, ואיני יודע אם הוא בכללות דבריו או לאו, והש\"י יצילנו משגיאות, והוא]</span> &lt;פי'&gt; שכבר נזכר שכל תפלות האדם יהיו לתועלת השכינה, שהיא נק' תפלה &lt;כמ\"ש ואני תפלה&gt;, ששואלת ומתפללת מדודה למלאות חסרונה. וכל מה שנחסר לאדם הכל הוא בשביל החסרון שבשכינה, וצריך האדם שיתפלל למלא חסרונה שמה, ובתיקון למעלה ממילא נמשך למטה שגם <span data-k=\"sm\">[שם]</span> הוא א' מאיברי השכינה, כי מלכותו בכל משלה, ואין לך מקום פנוי ממנה.\n<b>אך</b> הלב יודע מרת נפשו שאין כל העיתים שוות, שאם ח\"ו יש לאדם איזה צער גדול ותפלתו הוא על עצמו, ואינו משים על לבו שצער זה הוא בשכינה, ויותר היה ראוי שיתפלל עליה כי ממנה פנה ויתד שהכל בה, או שהוא מתפלל ובתוך כך נזכר שצריך להניח את עצמו ולהתפלל על השכינה רק שאינו יכול להתאפק על צער עצמו, ואם יאמר שהוא מתפלל על השכינה, ובוחן לב הוא ה' היודע שאין זה אמת, אפשר שח\"ו נדחה מכל. וע\"כ יתפלל כפשוטו לפי מה שהאדם הוא במדריגה בעת ההיא, רק שיהי' פיו ולבו שוין כי דובר שקרים לא יכון וגו'. <span data-k=\"sm\">[וכן שמעתי מפורש מפי הרב המגיד מו' מנחם מענדל, ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י קדשים צא</b>,<b> ב (שמ</b>,<b> ב)</b>\n<i>שמעו אלי גו' הביטו גו'</i> – ישעי' נא, א. <i>השכינה שהיא נק' תפלה</i> – זח\"א רנג, ריש ע\"ב. זח\"ג מט, ריש ע\"ב. <i>ואני תפלה</i> – תהלים קט, ד. <i>מלכותו בכל גו'</i> – תהלים קג, יט. <i>ואין לך מקום כו'</i> – שמ\"ר ב, ה. תקו\"ז תנ\"ז צא, סע\"ב. שם ת\"ע קסב, ב. <i>לב יודע גו' </i>– ע\"פ משלי יד, י. <i>דובר שקרים גו'</i> – תהלים קא, ז.\n----- הערות וציונים -----\n<i>לתועלת השכינה</i> – ראה לעיל סי' כ וש\"נ בהערות. רג\"כ בהערות לסי' פ ד\"ה לתועלת השכינה.\n<i>הוא א' מאברי השכינה</i> – ראה זח\"ג רלא, סע\"ב. רג\"כ זח\"ב קיח, רע\"א וזח\"ג יז, רע\"א."]]],[300010475,"שצה-ב<i>[ftnref_1_פג]</i>\n\n<b>כשישראל</b> מתפללים ומתדבקים את עצמן להש\"י קלא נפיק צאינה וראינה בנות ציון כו'. כלומר, מי שאינו ראוי ליחוד זה ולא ניחא ליה יצא, וזהו צאינה, ומי שראוי לזה וניחא ליה יראה, וזהו וראינה. וכששומעין הקליפות קול הזה, אז רוצים לבטל האדם הזה מתפלתו במח\"ז מתענוגי הזמן – &lt;והחכם מתדבק באהבה ויראת הבורא ית', ובזה מעלה ניצוצי חיות שבתוך הדבר ההוא, ואומר בלבו מה לי לדבק בחומריות הדבר, מוטב אדבק בחיותו שהוא כח מכחות הש\"י, שהוא החכמה, כמ\"ש כולם בחכמה עשית. וכן באכילה ושאר תענוגים מתענוגי הזמן, כמו בשבת וי\"ט, יהיה בתענוג רוחני שבדבר ההוא שהוא החיות של הדבר, ולא לחומריות הדבר, שע\"י שהוא דבוק בתענוג רוחני נזכר אצל הש\"י, שגם הוא ית' דבוק בתענוג רוחני שאין אנחנו יכולין להשיגו, אבל כשהוא דבוק לחומריות הוא מרוחק מהש\"י&gt;.",[["","","----- מקורות ומראה מקומות -----\n<b>קטע ממדל</b>\"<b>י סי</b>'<b> קז (קיח)</b>\n<i>צאינה וראינה גו'</i> – שה\"ש ג, יא. <i>כולם בחכמה עשית</i> – תהלים קד, כד. <i>ה' בחכמה</i> – משלי ג, יט.\n----- שולי הגליון -----\n[ftn_1_פג]) <i>שינה סדר הדברים</i>,<i> הוסיף והשמיט כו'</i>.<i> וזהו לשון המדל\"י (ולהעיר שבמקבילו באו\"ת יש כו\"כ שנויי נוסחאות)</i>:\nצריך כל אדם להיות תמיד דבוק בתענוג רוחני, וגם כשיזדמן לו תענוגים מתענוגי הזמן (<i>נ\"א</i> עוה\"ז), כמו בשבת ויו\"ט, יהיה דבוק בתענוג רוחני שבדבר ההוא, שהוא החיות של הדבר, ולא לחומריות הדבר, שע\"י שהוא דבוק בתענוג רוחני נזכר אצל השי\"ת, שגם הוא ית' דבוק בתענוג רוחני שאין אנו יכולים להשיגו, אבל כשהוא דבוק לחומריות הדבר כגון אוכל. . . אדרבה בזה הוא מרוחק מהבורא ית'. . . והנה כשישראל <i>(כבפנים</i>,<i> עד</i> מתענוגי הזמן), וגם החיות של תענוג זה מעורר חשק עם חומריות וקליפות התענוג ההוא, כי החיות הוא ניצוץ קדוש. . . כי הניצוצות חשקם לדבק באביו, וע\"כ הוא ג\"כ בשמחה. ואם יהיה האיש הזה איש נלבב, אזי ידבק את עצמו עי\"ז יותר להש\"י במחשבתו, שהרי המחיה הדבר ההוא שנפלה במחשבתו הוא חכמה, כי כולם בחכמה עשית כנודע, וכתיב ה' בחכמה, דהיינו שכח הבורא שורה בחכמה. א\"כ לפי זה יש חלק אלהות במח\"ז, כח הפועל המחיה אותו הדבר, ותיכף מלביש א\"ע באהבה ויראה מפני ניצוץ הקדוש שבאותו דבר, באמרו בלבו, כיון שאלולי חלק אלהות המחיה את הדבר לא היה יכול להיות, א\"כ למה לי לדבק בחומריות הדבר, מוטב שאדבק בחיותו, והוא כח מכחות השי\"ת. ולכן מתדבק באהבה ויראת הבורא ית', ובזה מעלה ניצוץ שבתוך הדבר ההוא. וכן באכילה ושארי תענוגים בכונה הנ\"ל מעלה ניצוצות מתוכם, לכן שניהם רוצים (<i>נ\"א</i>: רצים) בשמחה, הניצוץ והקליפות.\n----- הערות וציונים -----\n(ההערות על סדר נוסח המקורי)\n<i>יהיה דבוק בתענוג הרוחני כו'</i> – ראה לעיל סי' שז ובהערות שם.\n<i>שגם הוא ית' דבוק כו'</i> – להעיר ממדל\"י סי' א, ושם סי' – (ק).\n<i>קלא נפיק כו'</i> – ראה זח\"ב קלד, ב וזח\"ג קט, סע\"א.\n<i>ותיכף כו' באמרו בלבו כיון כו'</i> – עיין צוה\"ר סי' – ובהערות שם.\n<i>וכן באכילה כו'</i> – ראה לעיל סי' נג וריח, ובהערות שם."]]],[300010476,"שצה-ג\n\n<b>והנה</b> יש ב' אהבות, א' שהאב אוהב מעשה בנו החכם, ומתפאר במעשה החכמה שעושה או בדבר החכמה שמדבר, והב' שאוהב את בנו בעצם, וכל מה שמדבר לפניו הכל הגון בעיניו בשביל אהבתו אותו. והנה באהבת הש\"י <span data-k=\"sm\">[עלינו]</span> &lt;על ישראל&gt;, אהבה א' הנ\"ל כשהצדיק עושה מצות ומעש\"ט הכל בחכמה נפלאה, ומעלה ניצוצות הקדושים מה שבדומם צומח חי מדבר, ואז הש\"י אוהב מעשיו מאד, ובזה מקשר גם חצוניות העולמות להש\"י, שהש\"י שורה בכל מעשיו, וזה מתתקן לגמרי אי\"ה בביאת משיח בב\"א, כמ\"ש ומלאה הארץ דעה וכו' <span data-k=\"sm\">[וגם בהמות וחיות כולם יהיו יודעים את הש\"י, לא ירעו וכו']</span>. ואהבה הב' הנ\"ל, הוא כשהצדיק בעצמו מקושר להש\"י והש\"י אוהבו מאוד אותו בעצמו, <span data-k=\"sm\">[ואינו]</span> &lt;אע\"פ שאינו&gt; עושה מעשיו בחכמה כמו הראשון, רק הולך בתמימות גדול ומקושר להש\"י, לכן הש\"י אוהבו, וזה נק' עליות פנימיות העולמות, שהצדיק הוא <span data-k=\"sm\">[פנימיות]</span> העולם.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י סי</b>'<b> ק (קט)</b>\n<i>ומלאה הארץ גו'</i> – ישעי' יא, ט. <i>לא ירעו גו'</i> – שם.\n----- הערות וציונים -----\n<i>כשהצדיק כו' ומעלה כו'</i> – ראה לעיל סי' שצה-ב ובהערות שם. וראה מדל\"י סי' יא.\n<i>ובזה מקשר כו'</i> – להעיר ממדל\"י סי' רנ (רסא).\n<i>וזה מתתקן </i>. .<i> בביאת משיח בב\"א</i> – ראה ע\"ח של\"ט פ\"א."]]],[300010477,"שצו\n\n<b>&lt;מהבעש\"ט</b> זלה\"ה אהא&gt; דארז\"ל ופרעה הקריב שהקריב את ישראל לאביהם שבשמים כו'. לכאורה קשה, דא\"כ לזכות יחשב לו שעל ידו נתקרבו לאביהם שבשמים, וזה אינו, לנצח נאבד זכרו. &lt;ופי'&gt; <span data-k=\"sm\">[ונ\"ל דשמעתי מ]</span><i>מורי</i> &lt;הבעש\"ט זלה\"ה כי&gt; בענין קשוטי הכלה, שמקשטין אותה בכמה מיני לבושין כדי שיבואו לקירוב הזווג ע\"י שמצאה חן בעיניו ע\"י הקשוטין, ובעת הזווג אישתלילו מלבושיהן בקירוב בשר כו'. ומבשרי אחזה אלוה כביכול, שהתפלה היא השכינה, כלה עליונה, והשושבין הוא הצדיק שעל ידו נעשה היחוד וזווג עליון, בתפלה מעומקא דלבא מייחד התפלה שהיא הכלה לאלהי ישראל, והוא זווג עליון, וע\"כ קודם הזווג צריך לקשטה בכמה קשוטין ולבושין &lt;וכו'&gt; <span data-k=\"sm\">[וכנ\"ל]</span>. וצריך שתדע מה הם לבושין הגורם לקישוט, וע\"כ נודע מה שמצינו כי הפרי הוא הצדיק, והלבוש אל הפרי הוא המוץ ותבן, הרשעים, שא\"א בטבע הבריאה להוציא הפרי בעצמו בלתי לבושי המוץ ותבן, כ\"א לעתיד &lt;לבוא&gt; <span data-k=\"sm\">[על דרך]</span> שאחז\"ל עתידה א\"י שתוציא גלוסקאות וכלי מילת <span data-k=\"sm\">[ויבואר זה אח\"כ]</span>, ובעת אשר שלט האדם באדם לרע לו, של השליט, והטעם בכתבים להוציא ניצוצי קדושה חיותו ע\"ש. ולדברינו הנ\"ל מבואר כי הרשע הנק' לבוש ומיצר להצדיק כדי שיקרא ממיצר, א\"כ הוא קשוטי לבושי השכינה שגורם להתפלל ממיצר, ונעשה יחוד התפלה שהיא הכלה עם דודה, וכאשר נעשה היחוד אז כביכול אישתליל מלבושי' ויתפרדו כל פועלי און. &lt;וכתב הרב הגאון המחבר מ' יעקב יוסף הכהן זלה\"ה&gt; ע\"כ תוכן דבריו, הגם שאין זה לשונו, ודפח\"ח.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י שלח קלח</b>,<b> סע</b>\"<b>א (תצא</b>,<b> ב)</b>\n<i>ופרעה הקריב</i> – בשלח יד, י. <i>שהקריב את ישראל כו'</i> – פס\"ז שמות יד, י. ראה שמ\"ר כא, ה. <i>אשתלילו כו'</i> – זו\"ח בראשית ד, סע\"ג. <i>ומבשרי אחזה גו'</i> – איוב יט, כו. <i>שהתפלה היא השכינה</i> – זח\"א רנג, ריש ע\"ב. זח\"ג מט, ריש ע\"ב. <i>עתידה א\"י כו'</i> – שבת ל, סע\"ב. <i>ובעת אשר שלט גו'</i> – קהלת ח, ט. <i>בכתבים</i> – פע\"ח שער ק\"ש פ\"ג. שער המצות, פ' ראה (מצוות זכירת יצ\"מ). ספר הגלגולים פ\"ב. <i>ויתפרדו גו'</i> – תהלים צב, י.\n----- הערות וציונים -----\n<i>שהתפלה היא השכינה</i> – ראה לעיל סי' קעו ושצה-א.\n<i>התפלה שהיא הכלה</i> – דהשכינה נק' כלה (זח\"ב ה, ב וזח\"ג ד, ב).\n<i>והוא זווג עליון</i> – ראה זח\"ב ר, ע\"ב. צוה\"ר סי' סח.\n<i>הפרי הוא הצדיק כו'</i> – להעיר מזח\"ב רלג, ב בסוד רשע מכתיר את הצדיק.\n<i>שא\"א </i>. .<i> להוציא הפרי בעצמו בלתי כו'</i> – להעיר ממש\"כ באו\"ת ס\"פ בראשית (סו\"ס יב) בענין תוכו אכל קליפתו זרק.\n<i>הרשע הנק' לבוש כו'</i> – כנ\"ל מזח\"ב רלג, ב.\n<i>ומיצר להצדיק כדי שיקרא ממיצר</i> – ראה לעיל סי' שה.\n<i>א\"כ הוא קשוטי כו'</i> – ובזה מבואר מה שהקשה לעיל בענין ופרעה הקריב.\n<i>וכאשר נעשה היחוד כו' אשתליל כו'</i> – ראה תקו\"ז תנ\"ח צב, א, ושם סוף תס\"ו צח, א."]]],[300010478,"שצז\n\n<b>&lt;מהבעש\"ט&gt;</b> <span data-k=\"sm\">[שמעתי </span><i>ממורי</i><span data-k=\"sm\">]</span> זלה\"ה כי תיקון בעלי תשובה העיקר הוא על ידי גדולי הדור שיכול להעלותו ולקשרו בשרשו <span data-k=\"sm\">[וכו', ודפח\"ח]</span>.",[["","","----- מקורות ומראה מקומות -----\n<b>תוי</b>\"<b>י קרח קמד</b>,<b> א (תקלג</b>,<b> ב)</b>\n----- הערות וציונים -----\nכבר הובא לעיל סי' ער ועיי\"ש בהערות."]]],[300010479,"שצח-א\n\n<b>&lt;ופי'&gt;</b> הנה ה' רוכב על ע\"ב קל, פי' הנה ה' רוכב על אותו האדם שעשה איזה עבירה והיא עבה וחמורה בעיניו אף שהיא קלה בעצם.",[["","","----- מקורות ומראה מקומות -----\n<b>מדל</b>\"<b>י סו</b>\"<b>ס קד (קטו)</b>\n<i>הנה ה' רוכב גו'</i> – ישעי' יט, א.\n----- הערות וציונים -----"]]]]});
